// كتاب الصلاة — القسم الأول (أ): ص5–128 (أُعيدت قراءته من الصور)
const { NO_N, NO_O } = require('../b4/common');

module.exports = [
  {
    title: `باب بدء الأذان (ص5–10)`,
    items: [
      { q: `أصل معنى «الصلاة» في اللغة`, p: `5–6`,
        n: `اختلف العلماء في أصل الصلاة: فقيل: هي الدعاء لاشتمالها عليه، وهذا قول جماهير أهل العربية والفقهاء وغيرهم. وقيل: لأنها ثانية لشهادة التوحيد كالمصلي من السابق في خيل الحلبة. وقيل: هي من (الصلوين) وهما عرقان مع الردف. وقيل: هما عظمان ينحنيان في الركوع والسجود، قالوا: ولهذا كُتبت (الصلاة) بالواو في المصحف. وقيل: هي من الرحمة. وقيل: أصلها الإقبال على الشيء، وقيل غير ذلك.`,
        o: NO_O,
        s: `أرجح الأقوال الأول والذي هو الدعاء لأنها مشتملة على الدعاء.`,
        f: [`(ص5) الأذان شرف الأمة الإسلامية، فمن شرفها وكرمها وكرامتها عند الله أمر الأذان، فالأذان نعمة من أجل النعم.`, `(ص6) «ناقوس»: أي جرس على الشكل المعروف والصوت المعروف.`] },
      { q: `حكم المشاورة: هل هي واجبة على النبي ﷺ؟ وهل يلزم الإمام الأخذ برأي المستشارين؟`, p: `6–7`,
        n: `وفيه التشاور في الأمور لا سيما المهمة؛ وذلك مستحب في حق الأمة بإجماع العلماء، واختلف أصحابنا هل كانت المشاورة واجبة على رسول الله ﷺ أم كانت سنة في حقه كما في حقنا؟ والصحيح عندهم وجوبها، وهو المختار، قال الله تعالى: ﴿وَشَاوِرْهُمْ فِي الأَمْرِ﴾ والمختار الذي عليه جمهور الفقهاء ومحققو أهل الأصول أن الأمر للوجوب. وفيه أنه ينبغي للمتشاورين أن يقول كل منهم ما عنده، ثم صاحب الأمر يفعل ما ظهرت له مصلحة.`,
        o: `نقل القرطبي اتفاق العلماء على أن المشاورة مستحبة في حق الأمة؛ واختلف الشافعية في وجوبها على النبي ﷺ: واجبة (الصحيح عندهم)، أو سنة في حقه كما في حقنا.`,
        s: `مسألة نقله اتفاق العلماء على أنه مستحب في حق الأمة فيه نظر، فقد ذكر القرطبي ... عن ابن عطية: «والشورى من قواعد الشريعة وعزائم الأحكام؛ من لا يستشير أهل العلم والدين فعزله واجب. هذا ما لا خلاف فيه»، وليس هذا بترك للمشاورة، فقد قال تعالى في صفات المؤمنين (وأمرهم شورى بينهم) وهذا دليل على الوجوب لأنه ذكرها صفة مستقرة لهم وإذا كان الأمر واجباً على النبي ﷺ فإنه واجب على من قام مقامه، فالإمام عليه أن يشاور الناس فيما ينزل بهم من أمور عظيمة، أما الأمور الخاصة بأن يشاور الإنسان غيره في شأنه الخاص مثلاً أو في شؤونه المهمة فهذا يمكن حمل الاستحباب عليه، ويمكن حمل هذا الإجماع على ما كان في الأمور خاصة وليس في أمر الإمام. وهناك فرق بين المشاورة وبين الأخذ برأي المستشارين: فالمشاورة أمر واجب على الصحيح بالنسبة للإمام، وأما أن يلتزم برأي من أشار عليه فلا يلزمه إلا أن يجمعوا على أمر لأن الأمة لا تجتمع على ضلالة؛ فإذا أجمع أهل علم محلة الإمام على أمر وخالف فيه واحد فقط أو حتى اثنان فالصحيح أنه يلزم الإمام الأخذ برأي المجموع، لقوله ﷺ: «لا يزال طائفة من أمتي ظاهرين على أمر الله وهم ظاهرون» (البخاري) وكلمة (طائفة) فلابد أن تكون جماعة وأقلها ثلاثة، والواحد والاثنان لا يقدحان في الإجماع. أما إذا اختلفوا فلا يلزمه رأي الأكثرية طالما كان الإمام مجتهداً، ويمكن الترجيح بالأكثرية في غياب الإمام أو في غياب اجتهاده، لأن عمر ﵁ أمر إذا اختلف أصحاب الشورى بأن اختار أربعة واحداً واختار اثنان واحداً أن يأخذوا برأي الأربعة، وأنه إذا استووا يكون رأي ابن عمر مرجحاً، فإذا لم توجد أنواع أخرى من الترجيح كما ذكرنا فلا يلزمه اجتهاد غيره إذا كان الإمام مجتهداً، وإذا فقد الإمام أو فقد اجتهاده أي لم يكن مجتهداً فوارد أن يكون مشروع زراعي أو صناعي أو مسألة تجارية وليس للإمام خبرة في هذا الباب ولابد أن يأخذ قرار فيكون أهل الخبرة في هذا الباب يكون رأيهم ملزماً له ويرجح بالأكثرية.`,
        f: [] },
      { q: `هل كان النبي ﷺ يجتهد؟ وهل شُرع الأذان بوحي أم باجتهاد؟ وحكم العمل بالرؤيا (المنام)`, p: `8`,
        n: `قال القاضي عياض رحمه الله: ظاهره أنه إعلام ليس على صفة الأذان الشرعي، بل إخبار بحضور الصلاة ووقتها. وهذا الذي قاله محتمل أو متعيّن، فقد صحّ في حديث عبد الله بن زيد في سنن أبي داود والترمذي وغيرهما أنه رأى الأذان في المنام فجاء إلى رسول الله ﷺ يُخبره به، فجاء عمر ﵁ فقال: يا رسول الله والذي بعثك بالحق لقد رأيت مثل الذي رأى. فهذا ظاهره أنه كان في مجلس آخر، فيكون الواقع الإعلام أولًا، ثم رأى عبد الله بن زيد، فشرعه النبي ﷺ بعد ذلك إما بوحي، وإما باجتهاده ﷺ على مذهب الجمهور في جواز الاجتهاد له، وليس هو عملًا بمجرد المنام. هذا ما لا يُشكّ فيه بلا خلاف.`,
        o: `مذهب الجمهور جواز الاجتهاد للنبي ﷺ.`,
        s: `الصحيح أن النبي ﷺ كان يجتهد ويقره الوحي، وإذا لم يقره نزل الوحي ببيان ما حصل فيه خطأ، فإذا نظرنا إلى خلاصة المسألة الآن وجدنا أنه لا فرق بين القولين أن هذا كان بوحي أو باجتهاد لأنه هو اجتهاد أقره الوحي فيكون وحياً. وهذا هو الصحيح لأن المنام إنما يُعمل به إذا أقره الوحي، وأما العمل بالمنام المجرد فلا، وهذا هو الفرق بين أهل السنة وبين طوائف من الصوفية الذين يجعلون المنامات حجة قطعية أو مرجحة بمجرده مستقلة بذاتها، وكذا الكشف والإلهام؛ فنحن نثبت أثر المنام ونثبت الاستئناس به ولكن لابد وأن يوافق الشرع، فيستأنس به في الترجيح وكذا الاستنباط، ولكن لا يستدل به استدلالاً مستقلاً لأنه قابل للخطأ والصواب في حق غير الأنبياء، فالمنام قابل أن يكون رؤية من الله وقابل أن يكون حُلم من الشيطان وقابل أن يكون حديث نفس وقابل أن يخطأ ويصيب الإنسان في التأويل لأن بعض المنامات يحتاج إلى تأويل وبعضها يكون على ظاهره.`,
        f: [] },
      { q: `القيام في الأذان: هل هو واجب أو شرط؟ وحكم أذان القاعد والمضطجع`, p: `8–9`,
        n: `(يا بلال قم فناد بالصلاة) قال القاضي عياض رحمه الله: فيه حجة لشرع الأذان من قيام، وأنه لا يجوز الأذان قاعدًا. قال: وهو مذهب العلماء كافة إلا أبا ثور فإنه جوّزه ووافقه أبو الفرج المالكي، وهذا الذي قاله ضعيف لوجهين: أحدهما أنا قدمنا عنه أن المراد بهذا النداء الإعلام بالصلاة لا الأذان المعروف. والثاني أن المراد قم فاذهب إلى موضع بارز فناد بالصلاة ليسمعك الناس من البعد، وليس فيه تعرض للقيام في حال الأذان، لكن يُحتج للقيام في الأذان بأحاديث معروفة غير هذا. وأما قوله: مذهب العلماء كافة أن القيام واجب فليس كما قال، بل مذهبنا المشهور أنه سنة، فلو أذّن قاعدًا بغير عذر صح أذانه لكن فاتته الفضيلة، وكذا لو أذّن مضطجعًا مع قدرته على القيام صح أذانه على الأصح لأن المراد الإعلام وقد حصل، ولم يثبت في اشتراط القيام شيء.`,
        o: `القاضي عياض: القيام واجب وهو مذهب العلماء كافة إلا أبا ثور وأبا الفرج المالكي. والنووي: سنة، ويصح الأذان قاعدًا ومضطجعًا.`,
        s: `الصحيح أن نقول بوجوب القيام لظاهر حديث وقوله (قم) أي اذهب إلى موضع بارز متضمن القيام، ونادِ بالصلاة أي وأنت قائم باستصحاب حال القيام السابق، ولكن لا يبطل الأذان من قعود، فنقول بالوجوب وعدم الشرطية. وهذا هو الأصل فظاهر الأمر الوجوب (قم يا بلال) فهذا دليل على وجوب الأذان قائماً.`,
        f: [] },
      { q: `إذا اجتمع من يتبرع بالأذان ومن يطلب أجرًا وهو أحسن صوتًا: أيهما يُقدَّم؟ (وحكم أخذ الأجرة على الأذان)`, p: `9–10`,
        n: `فيؤخذ منه: استحباب كون المؤذن رفيع الصوت وحسنه. وهذا متفق عليه. قال أصحابنا: فلو وجدنا مؤذنًا حسن الصوت يُطلَب على أذانه رزقًا وآخر يتبرع بالأذان لكنه غير حسن الصوت، فأيهما يؤخذ؟ فيه وجهان: أصحهما يرزق حسن الصوت، وهو قول ابن شريح. وذكر العلماء في حكمة الأذان أربعة أشياء: إظهار شعار الإسلام، وكلمة التوحيد، والإعلام بدخول وقت الصلاة وبمكانها، والدعاء إلى الجماعة.`,
        o: `وجهان عند الشافعية: يُرزق حسن الصوت (الأصح، وهو قول ابن سريج)، أو يُقدَّم المتبرع.`,
        s: `يُعطاه من بيت المال؛ والوجه الثاني الذي جعله مقابل للأصح أنه يكره أخذ الأجرة على الأذان وبالتالي فدرء المفاسد مقدم على جلب المصالح ففيه احتمال، فهو يرجح وهو المذهب عندهم ترجيح حسن الصوت مراعاةً لفضيلة حسن الصوت في هذا المقام.`,
        f: [`(ص9) وهذا دليل على أن الإنسان عليه ألا ينازع حسن الصوت الأذان، فربما يأتي إنسان ويريد أن يؤذن وهو ليس حسن الصوت ولا برفيع الصوت، فينبغي أن يترك حسن الصوت إذا وجد أن يؤذن، فهذا شعار لنا جميعاً فثواب للمجموع أكثر أن يؤذن حسن الصوت.`, `(ص10) والظاهر والله أعلم وجوب الأذان كما سنذكره إن شاء الله.`] },
    ],
  },
  {
    title: `باب الأمر بشفع الأذان وإيتار الإقامة (ص10–14)`,
    items: [
      { q: `قول الصحابي «أُمر بلال» و«أُمرنا» و«نُهينا»: هل هو مرفوع؟`, p: `11`,
        n: `(أُمر بلال) هو بضم الهمزة وكسر الميم؛ أي أمره رسول الله ﷺ، هذا هو الصواب الذي عليه جمهور العلماء من الفقهاء وأصحاب الأصول وجميع المحدثين، وشذ بعضهم فقال: هذا اللفظ وشبهه موقوف لاحتمال أن يكون الآمر غير رسول الله ﷺ، وهذا خطأ والصواب أنه مرفوع لأن إطلاق ذلك إنما ينصرف إلى صاحب الأمر والنهي وهو رسول الله ﷺ. ومثل هذا اللفظ قول الصحابي: أُمرنا بكذا، ونُهينا عن كذا، أو أُمر الناس بكذا، ونحوه فكله مرفوع سواء قال الصحابي ذلك في حياة رسول الله ﷺ أم بعد وفاته.`,
        o: `قول بعضهم (شاذ): هو موقوف لاحتمال أن يكون الآمر غير النبي ﷺ.`,
        s: `هذا الكلام صحيح على ما هو عليه ولكن نضيف إليه: [إلا أن تدل قرينة على أنه قصد أمر غير النبي ﷺ].`,
        f: [`(ص11) «هذا اللفظ وشبهه»: أي شبه لفظ أمر (أمرنا بكذا أو نهينا عن كذا).`] },
      { q: `الترجيع في الأذان: تعريفه وحكمه`, p: `12`,
        n: `واختلف العلماء في إثبات الترجيع كما سأذكره في الباب الآتي إن شاء الله تعالى.`,
        o: NO_O,
        s: `الترجيع وهو أن يكرر (أشهد أن لا إله إلا الله) مرتين و(أشهد أن محمد رسول الله) مرتين بصوت منخفض قبل أن يرفع صوته بها، اختلف في إثباته والصحيح التخيير.`,
        f: [] },
      { q: `عدد كلمات الإقامة وصفتها: مذاهب العلماء (الشافعي وأحمد، مالك، أبو حنيفة)`, p: `12–13`,
        n: `واختلف العلماء في لفظ (الإقامة): فالمشهور من مذهبنا الذي تظاهرت عليه نصوص الشافعي، وبه قال أحمد وجمهور العلماء أن الإقامة إحدى عشرة كلمة: [الله أكبر، الله أكبر، أشهد أن لا إله إلا الله، أشهد أن محمدًا رسول الله، حي على الصلاة، حي على الفلاح، قد قامت الصلاة، قد قامت الصلاة، الله أكبر، الله أكبر، لا إله إلا الله]. وقال مالك رحمه الله في المشهور عنه: هي عشر كلمات فلم يثنِّ لفظ الإقامة، وهو قول قديم للشافعي. ولنا قول شاذ: أنه يقول في الأول: الله أكبر مرة، وفي الآخر الله أكبر، ويقول: قد قامت الصلاة مرة فتكون ثمان كلمات، والصواب الأول. وقال أبو حنيفة: الإقامة سبع عشرة كلمة فيثنيها كلها وهذا المذهب شاذ. قال الخطابي: مذهب جمهور العلماء والذي جرى به العمل في الحرمين والحجاز والشام واليمن ومصر والمغرب إلى أقصى بلاد الإسلام أن الإقامة فُرادى. قال الإمام أبو سليمان الخطابي رحمه الله تعالى: مذهب عامة العلماء أنه يكرر قوله (قد قامت الصلاة) إلا مالكًا فإن المشهور عنه أنه لا يكررها. والله أعلم.`,
        o: `مالك: عشر كلمات (لا تثنية لفظ «قد قامت الصلاة»)، وهو قول قديم للشافعي. أبو حنيفة: سبع عشرة كلمة فيثنيها كلها (وعدّه النووي شاذًّا). قول شاذ عند الشافعية: ثمان كلمات.`,
        s: `هذا غير ظاهر، فاعتبار شذوذ مذهب أبي حنيفة في هذه المسألة غير ظاهر، يمكن أن يرجح هو القول الثاني، بل الراجح صحة تسمية الإقامة بصحة الحديث بها في التمرين وغيره ولكنها تفعل أحياناً وتترك أحياناً والأغلب الأعم أن يفرد الإقامة (يوتر الإقامة) ولكن إذا ثناها يقول: (الله أكبر) أربعاً، أشهد أن لا إله إلا الله مرتين، و(أشهد أن محمد رسول الله) مرتين، (حي على الصلاة) مرتين، (حي على الفلاح) مرتين، (قد قامت الصلاة) مرتين، (الله أكبر الله أكبر) مرتين، لا إله إلا الله.`,
        f: [`(ص12) «أي غير معتبر ولذلك قال (والصواب الأول)»؛ وقد ذكرنا قبل ذلك أن اصطلاحات الإمام النووي والشافعية خصوصاً دقيقة جداً في ذكر درجات الخلاف: فكلمة الصواب التي يقابلها الباطل أو الشاذ فيكون الخلاف غير سائغ وغير معتبر لأنه خلاف النص والنص آتٍ في الحديث القادم بإثبات أن الإقامة يقال فيها (الله أكبر الله أكبر) إذاً معنى يوتر الإقامة إلا الإقامة وإلا الله أكبر في أوله وآخره فيقول الله أكبر مرتين في الأولى والثانية. ولفظ الصحيح يقابله الضعيف ولفظ الظاهر أو الراجح يقابله المرجوح. وأما لفظ الأصح فيقابله مقابل الأصح فيكون الخلاف فيها ضعيف جداً وقريب والترجيح فيه عسر ولكنه رجح بكلمة الأصح.`] },
      { q: `الحكمة في إفراد الإقامة وتثنية الأذان، وهل تكبير الإقامة (الله أكبر أولًا وآخرًا) يُعدّ تثنية؟`, p: `13`,
        n: `والحكمة في إفراد الإقامة وتثنية الأذان: أن الأذان لإعلام الغائبين، فيُكرَّر ليكون أبلغ في إعلامهم، والإقامة للحاضرين، فلا حاجة إلى تكرارها، ولهذا قال العلماء: يكون رفع الصوت في الإقامة دونه في الأذان، وإنما كرر لفظ الإقامة خاصة لأنه مقصود الإقامة. فإن قيل: قد قلتم إن المختار الذي عليه الجمهور أن الإقامة إحدى عشرة كلمة منها الله أكبر أولًا وآخرًا وهذا تثنية؟ فالجواب: أن هذا وإن كان صورة تثنية فهو بالنسبة إلى الأذان إفراد.`,
        o: NO_O,
        s: `هذا الكلام ينطبق على الأول لو اخترنا تربيع التكبير، لكن لا ينطبق على الثاني؛ لذلك قلنا أن الراجح في هذه المسألة الاحتياج إلى استثناء آخر بدليل منفصل، الحديث فيه استثناء متصل وهو قوله (إلا الإقامة)، ثم نخصص عموم قوله: (أمر أن يوتر الإقامة) نخصصه بدليل آخر وهو الحديث الآتي الذي ثنى فيه لفظ الله أكبر أولاً وآخراً، فيصبح عندنا تخصيص بدليل متصل (إلا الإقامة) وعندنا تخصيص بدليل منفصل وهو حديث أبي محذورة الآتي.`,
        f: [] },
      { q: `الإتيان بكل تكبيرتين بنفَس واحد في الأذان، وكيفية التربيع`, p: `14`,
        n: `ولهذا قال أصحابنا: يُستحب للمؤذن أن يقول كل تكبيرتين بنفَس واحد، فيقول في أول الأذان: [الله أكبر الله أكبر] بنفَس واحد، ثم يقول: [الله أكبر الله أكبر] بنفَس آخر. والله أعلم.`,
        o: NO_O,
        s: `خلافاً لمن يقول: (الله أكبر) بنفس ويقول (الله أكبر) بنفس آخر، فالسنة أن يقولها: (الله أكبر الله أكبر) بنفس واحد، ففي الحديث الآتي أن النبي ﷺ: [فَسَمِعَ رَجُلاً يَقُولُ اللَّهُ أَكْبَرُ اللَّهُ أَكْبَرُ. فَقَالَ رَسُولُ اللَّهِ ﷺ: «عَلَى الْفِطْرَةِ»]. وقوله ﷺ: (إِذَا قَالَ الْمُؤَذِّنُ اللَّهُ أَكْبَرُ اللَّهُ أَكْبَرُ فَقَالَ أَحَدُكُمْ اللَّهُ أَكْبَرُ اللَّهُ أَكْبَرُ) فظاهر جداً أنه يقول ذلك بنفس واحد. وهذا اختيار منه لاستحباب التربيع وهو أن يقول (الله أكبر) أربع مرات، اثنين بنفس واحد واثنين بنفس؛ أما الترجيع بأن يقول الشهادتين الأربعة مرتين مرتين بصوت منخفض ومرة بصوت عالٍ.`,
        f: [`(ص14) الحمد لله الذي هدانا إلى سبيل الحق واجتبانا، فالإنسان إذا تدبر فضل الأذان إلى وسائل الإعلام الأخرى عند الأمم الأخرى التي يستوي فيها تنبيه البشر مع البهائم، فالذي يريد أن ينبه الغنم قد يصدر صوت بوق أو جرس أو نحو ذلك، ففضل الله ﷻ على أمة الإسلام بأن جعل الأذان الذي تضمن أشرف المعاني وأكمل معاني التوحيد والإيمان وما يحيي الإيمان في القلوب يتكرر بينهم بفضله ﷺ.`] },
    ],
  },
  {
    title: `باب صفة الأذان (ص15–18)`,
    items: [
      { q: `تربيع التكبير في أول الأذان أم تثنيته؟`, p: `16`,
        n: `هكذا وقع هذا الحديث في صحيح مسلم في أكثر الأصول في أوله [الله أكبر مرتين] فقط، ووقع في غير مسلم [الله أكبر الله أكبر الله أكبر الله أكبر] أربع مرات. قال القاضي عياض رحمه الله: ووقع في بعض طرق الفارسي في صحيح مسلم أربع مرات، وكذلك اختُلف في حديث عبد الله بن زيد في التثنية والتربيع، والمشهور فيه التربيع، وبالتربيع قال الشافعي وأبو حنيفة وأحمد وجمهور العلماء، وبالتثنية قال مالك واحتج بهذا الحديث وبأنه عمل أهل المدينة وهم أعرف بالسنن. واحتج الجمهور بأن الزيادة من الثقة مقبولة، وبالتربيع عمل أهل مكة وهي مجمع المسلمين في المواسم وغيرها ولم يُنكر ذلك أحد من الصحابة وغيرهم، والله أعلم.`,
        o: `مالك: التثنية (مرتين). الشافعي وأبو حنيفة وأحمد والجمهور: التربيع (أربع مرات).`,
        s: `والصحيح أن كلا الأمرين مشروع فيؤذن أحياناً بالتثنية ويؤذن أحياناً بالتربيع، فإن اجتماع المسلمين بمكة والمدينة حاصل ولا يُنكر هذا ولا يُنكر هذا، والصحيح أن هذا من باب الأفضلية والأفضلية أن يُربع لأنه يُزيد لأنه ذكر أكثر، أما جواز ذلك وأنه يفعل أحياناً فقد ثبت الحديث به، فإذا كان الأمر كذلك جاز أن يربع وجاز أن يثني، فيقول (الله أكبر) مرتين في الأول أو يقولها أربعة مرات.`,
        f: [] },
      { q: `الترجيع في الأذان: حكمه (ركن أم سنة أم تخيير)، ومذاهب العلماء فيه`, p: `17–18`,
        n: `وفي هذا الحديث: حجة بينة ودلالة واضحة لمذهب مالك والشافعي وأحمد وجمهور العلماء أن الترجيع في الأذان ثابت مشروع، وهو العود إلى الشهادتين مرتين مرتين برفع الصوت، بعد قولهما مرتين مرتين بخفض الصوت. وقال أبو حنيفة والكوفيون: لا يُشرع الترجيع عملًا بحديث عبد الله بن زيد فإنه ليس فيه ترجيع. وحجة الجمهور هذا الحديث الصحيح، والزيادة مقدَّمة مع أن حديث أبي محذورة هذا متأخر عن حديث عبد الله بن زيد، فإن حديث أبي محذورة سنة ثمان من الهجرة بعد حنين، وحديث ابن زيد في أول الأمر، وانضم إلى هذا كله عمل أهل مكة والمدينة وسائر الأمصار، وبالله التوفيق. واختلف أصحابنا في الترجيع هل هو ركن لا يصح الأذان إلا به، أم هو سنة ليس ركنًا حتى لو تركه صح الأذان مع فوات كمال الفضيلة؟ على وجهين: والأصح عندهم أنه سنة، وقد ذهب جماعة من المحدثين وغيرهم إلى التخيير بين فعل الترجيع وتركه، والصواب إثباته. والله أعلم.`,
        o: `أبو حنيفة والكوفيون: لا ترجيع. الجمهور (مالك والشافعي وأحمد): الترجيع مشروع؛ وعند الشافعية وجهان: ركن، أو سنة (الأصح). وجماعة من المحدثين وغيرهم: التخيير بين فعله وتركه.`,
        s: `الصحيح أن هذا أيضاً يفعل ويترك فيفعل هذا أحياناً ويتركه أحياناً لأنه ليس كل الروايات فيها الترجيع، وقد ثبت هذا وثبت هذا. كما قلنا الصحيح في الترجيع أن يفعل ويترك، والأفعال لا تتعارض حتى يلجأ إلى النسخ، لأن كلام النووي هذا مُشعر بأن حديث أبي محذورة متأخر فكأنه ناسخ، [والصحيح أن] حديث أبي محذورة متأخر والآخر صحيح مقدم لا تعارض بينهما بل كلاهما مشروع. وأنه سنة: وهذا هو الصحيح، لأنه قد ثبتت الروايات من غير ترجيع فدل ذلك على جواز ترك الترجيع. والصحيح هو التخيير ولكن مع فضيلة الترجيع لأنه ذكر لله أكثر.`,
        f: [`(ص18) «حيَّ على الصلاة»: بعض الناس في نطقهم لـ(حي) يكسرون الياء مع مدها وهذا خطأ والصحيح تشديد الياء وفتحها. و(حيعل) فعل مركب مؤلف.`] },
    ],
  },
  {
    title: `باب استحباب اتخاذ مؤذنين للمسجد الواحد (ص18–21)`,
    items: [
      { q: `جواز وصف الإنسان بعيبه للتعريف (الغيبة المباحة)`, p: `19`,
        n: `ومنها جواز وصف الإنسان بعيبٍ فيه للتعريف أو مصلحة تترتب عليه، لا على قصد التنقيص، وهذا أحد وجوه الغيبة المباحة وهي ستة مواضع يباح فيها ذكر الإنسان بعيبه ونقصه وما يكرهه، وقد بيّنتها بدلائلها واضحة في آخر كتاب الأذكار الذي لا يستغني عن مثله متدين، وسأذكرها إن شاء الله تعالى في كتاب النكاح عند قول النبي ﷺ: «أمّا معاوية فصعلوك» وفي حديث (إنّ أبا سفيان رجل شحيح) وفي حديث «بئس أخو العشيرة» وأنبّه على نظائرها في مواضعها إن شاء الله تعالى، وبالله التوفيق.`,
        o: NO_O,
        s: `فالعبرة في ذلك النية. والست مواضع هم: (الاستفتاء – التظلم – التعريف – الاستعانة على تغيير المنكر – النصيحة و(تحذير المسلمين من الشر) وتدخل فيها السادسة وهي المجاهر بفسقه وبدعته).`,
        f: [`(ص19) ابن أم مكتوم كان يدخل المعارك ليحفز المسلمين ويحثهم على القتال ﵁.`] },
      { q: `اتخاذ مؤذنين للمسجد الواحد وعددهم (حدّ الأربعة)`, p: `19–20`,
        n: `وفي هذا الحديث: استحباب اتخاذ مؤذنين للمسجد الواحد يُؤذَّن أحدهما قبل طلوع الفجر، والآخر عند طلوعه، كما كان بلال وابن أم مكتوم يفعلان. قال أصحابنا: فإذا احتيج إلى أكثر من مؤذنين اتُّخذ ثلاثة وأربعة فأكثر بحسب الحاجة، وقد اتخذ عثمان ﵁ أربعة للحاجة عند كثرة الناس. قال أصحابنا: ويُستحب أن لا يُزاد على أربعة إلا لحاجة ظاهرة.`,
        o: NO_O,
        s: `كل واحد منهم يؤذن في جهة. (لفعل الصحابة ﷺ.)`,
        f: [] },
      { q: `إذا تعدد المؤذنون: هل يؤذنون دفعة واحدة؟ ومن يتولى الإقامة (الراتب أم الأول)؟ وإقامة غير المؤذن`, p: `20`,
        n: `قال أصحابنا: وإذا ترتب للأذان اثنان فصاعدًا فالمستحب ألا يؤذنوا دفعة واحدة، بل إن اتسع الوقت ترتبوا فيه فإن تنازعوا في الابتداء به أقرع بينهم، وإن ضاق الوقت فإن كان المسجد كبيرًا أذنوا متفرقين في أقطاره، وإن كان ضيقًا وقفوا معًا وأذنوا، وهذا إذا لم يؤد اختلاف الأصوات إلى تهويش، فإن أدّى إلى ذلك لم يؤذن إلا واحد، فإن تنازعوا أقرع بينهم. وأما الإقامة فإن أذنوا على الترتيب فالأول أحق بها إن كان هو المؤذن الراتب، أو لم يكن هناك مؤذن راتب. فإن كان الأول غير المؤذن الراتب فأيهما أولى بالإقامة؟ فيه وجهان لأصحابنا أصحهما أن الراتب أولى لأنه منصبه، ولو أقام في هذه الصور غير من له ولاية الإقامة اعتد به على المذهب الصحيح المختار الذي عليه جمهور أصحابنا، وقال بعض أصحابنا: لا يُعتد به كما لو خطب بهم واحد وأم بهم غيره، فلا يجوز على قول. وأما إذا أذنوا معًا فإن اتفقوا على إقامة واحد وإلا فيقرع. قال أصحابنا رحمهم الله: ولا يقيم في المسجد الواحد إلا واحد إلا إذا لم تحصل الكفاية بواحد.`,
        o: `وجهان عند الشافعية فيمن يقيم إذا كان الأول غير الراتب: الراتب أولى (الأصح)، أو الأول. وقول لبعض الأصحاب: لا يُعتد بإقامة من ليس له ولاية الإقامة، وقيل غير ذلك.`,
        s: `وهذا ليس مستفاداً من الحديث، والذي يظهر والله أعلم أنهم إذا احتاجوا أذنوا في أقطار المسجد ونواحيه. ولذلك نقول الذي يقيم لصلاة الفجر هو الأول ولأن بلال ﷺ هو الذي كان يقيم للصلاة وبلال هو الذي كان يؤذن قبل الوقت. والراجح وهو الصحيح المختار أنه يجوز ولكن خلاف السنة، فالسنة أن الذي خطب هو من يؤم، والسنة أن الذي أذن هو الذي يقيم ولكن لو حدث غير ذلك صح. حتى لو الخطيب أقل حفظاً فهو الذي يصلي بهم. (كأن لا يسمع من هو بمؤخرة المسجد فالمؤذنين الآخرين يقيموا في مواضع أخرى ليسمعوا الناس إقامة الصلاة.)`,
        f: [] },
      { q: `الأذان والإقامة لجماعة ثانية تُقام في المسجد بعد الجماعة الأولى`, p: `21`,
        n: `وقال بعض أصحابنا: لا بأس أن يقيموا معًا إذا لم يؤدِّ إلى التهويش.`,
        o: NO_O,
        s: `ولذلك لا مانع إذا أقيمت جماعة ثانية في المسجد أن يؤذنوا ويقيموا كما فعل أنس ﷺ قال البخاري في صحيحه: [باب فضل صلاة الجماعة. وكان الأسود: " إذا فاتته الجماعة ذهب إلى مسجد آخر"، وجاء أنس بن مالك إلى مسجد قد صُلّي فيه فأذّن وأقام وصلى جماعة] وفي السنن الكبرى للبيهقي: عن يونس عن أبي عثمان، قال: " جاءنا أنس بن مالك وقد صلينا الفجر فأذّن وأقام ثم صلى الفجر بأصحابه " فالناس عندما يصلون جماعة ثانية يؤذنوا ويقيموا ولا يشوشوا على الناس بل على قدر أنفسهم.`,
        f: [] },
    ],
  },
  {
    title: `باب جواز أذان الأعمى إذا كان معه بصير (ص21)`,
    items: [
      { q: `أذان الأعمى، وكراهة أن يكون الأعمى مؤذنًا وحده`, p: `21`,
        n: `فيه حديث عائشة رضي الله عنها: (كان ابن أم مكتوم يؤذن لرسول الله ﷺ وهو أعمى) وقد تقدم معظم فقه الحديث في الباب قبله ومقصود الباب أن أذان الأعمى صحيح، وهو جائز بلا كراهة إذا كان معه بصير، كما كان بلال وابن أم مكتوم. قال أصحابنا: ويُكره أن يكون الأعمى مؤذنًا وحده. والله أعلم.`,
        o: NO_O,
        s: `(إذا كان معه بصير) بصير يخبره بالوقت لأنه إنما يعرف الأعمى الوقت بالخبر. (ويكره أن يكون مؤذنًا وحده) لأنه لن يستطيع معرفة الوقت على الدقة.`,
        f: [] },
    ],
  },
  {
    title: `باب الإمساك عن الإغارة على قوم في دار الكفر إذا سُمع فيهم الأذان (ص22–23)`,
    items: [
      { q: `الأذان للمنفرد: هل هو مشروع؟ وما حكمه؟`, p: `22`,
        n: `(فإذا هو راعي معزى) أُحتجّ به في أن الأذان مشروع للمنفرد، وهذا هو الصحيح المشهور في مذهبنا ومذهب غيرنا.`,
        o: NO_O,
        s: `ولكن الراجح أنه مستحب متأكد الاستحباب في حقه وليس بواجب، وإنما يؤذن وجوباً للجماعة فهو فرض كفاية لكل جماعة.`,
        f: [] },
      { q: `الأذان يمنع الإغارة على أهل الموضع: هل هو دليل على إسلامهم؟ وهل يُعدّ الدخول في المسجد إسلامًا؟`, p: `23`,
        n: `وفي الحديث دليل على أن الأذان يمنع الإغارة على أهل ذلك الموضع، فإنه دليل على إسلامهم.`,
        o: NO_O,
        s: `مع أنه قد يوجد فيهم كفار ولكنه إسلام بالقرينة لكل أهل المحلة. فالمؤذن نفسه لو رجع إلى الكفر لصار مرتداً، ولذلك نحن نفرق بين الأذان كقرينة للحكم بإسلام كل أهل البلد مثل المسجد قرينة لإسلام كل من فيه وقد يكون واحد نصراني دخل المسجد ليشاهد المسلمين وهم يصلون كالسياح إذا دخلوا بعض المساجد، فلا يلزم دخولهم المسجد إسلامهم بحيث أنه لو خرج وقال سأذهب إلى الكنيسة فهل يكون مرتداً؟ لا، بل دخوله المسجد ووجوده في طائفة تؤذن لا يُعد إسلاماً في حقه ولكن هي قرينة نكف بها عن الطائفة ككل وتعامل كطائفة مسلمة لجميع أفرادها ما لم يُعلم خلاف ذلك، بخلاف النطق المباشر فهذا إسلام حتى ولو معلوم عنه أنه كان كافراً قبل ذلك. فالشهادتان إسلام بمجردهما وهو إسلام للمؤذن نفسه بالقطع واليقين ولأهل المحلة بالقرينة، فإذا تبين أن واحداً من أهل المحلة كافر لا يصير مرتداً بسبب أن المؤذن قد أذن.`,
        f: [] },
      { q: `النطق بالشهادتين يكون إسلامًا وإن لم يكن باستدعاء، وخلاف «لا إله إلا الله» وحدها`, p: `23`,
        n: `وفيه أن النطق بالشهادتين يكون إسلامًا، وإن لم يكن باستدعاء ذلك منه، وهذا هو الصواب، وفيه خلاف سبق في أول كتاب الإيمان.`,
        o: `خلاف سبق في أول كتاب الإيمان (هل يشترط الاستدعاء للنطق؟، وهل يكفي النطق بـ«لا إله إلا الله» وحدها).`,
        s: `وهذا لا شك فيه أن نطق الشهادتين يكون إسلاماً ولا يحتاج إلى امتحانات ولا إلى تفصيل. الخلاف الذي ذكره: الصحيح فيه أنه ليس اختلاف وإنما هو اختلاف حال، وهو أن الوثني إذا نطق شهادة أن لا إله إلا الله فقط صار بذلك مسلماً، وأن الكتابي وكل من يقر بلا إله إلا الله لا يكون مسلماً حتى يضيف إلى ذلك أن محمداً رسول الله. فبعض العلماء ظن أن فيه قولان: أن لا إله إلا الله فقط تدخله في الإسلام من غير أن محمداً رسول الله، والصحيح أنه اختلاف حال وليس خلافاً حقيقياً؛ فحال الوثني غير حال الكتابي، ومن يقر بنبوة محمد ﷺ ومن يقر بالشهادتين ويكون كفره بغير جحد الشهادتين أو أحدهما فلا يكون إسلامه إسلاماً حتى يضيف إلى الشهادتين الإقرار بما كان سبباً في كفره. فهذا هو الصواب وأن الصحيح عدم وجود الخلاف في المسألة والخلاف فيه غير معتبر.`,
        f: [] },
    ],
  },
  {
    title: `باب استحباب القول مثل قول المؤذن لمن سمعه ثم يصلي على النبي ﷺ ثم يسأل الله له الوسيلة (ص24–33)`,
    items: [
      { q: `ما يقوله السامع عند الحيعلتين («حي على الصلاة» و«حي على الفلاح»)`, p: `27–28، 31`,
        n: `أما أحكام الباب: فيه استحباب قول سامع المؤذن مثل ما يقول إلا في الحيعلتين فإنه يقول: لا حول ولا قوة إلا بالله. وقوله ﷺ في حديث أبي سعيد: «إذا سمعتم النداء فقولوا مثل ما يقول المؤذن» عامٌّ مخصوصٌ بحديث عمر أنه يقول في الحيعلتين: لا حول ولا قوة إلا بالله. (وفي لفظ: قال القاضي عياض ... الحول والقوة.)`,
        o: `خلاف بعض العلماء القائلين في (حي على الصلاة وحي على الفلاح) يقول: [حي على الصلاة لا حول ولا قوة إلا بالله] فيقول حي على الصلاة لحديث أبي سعيد.`,
        s: `خلافاً لبعض العلماء القائلين في (حي على الصلاة وحي على الفلاح) يقول: [حي على الصلاة لا حول ولا قوة إلا بالله] فيقول حي على الصلاة لحديث أبي سعيد، وهذا غير ظاهر الصحيح كما قال النووي أنع عام مخصوص بحديث عمر ﷺ. الصحيح نص حديث عمر ﷺ أنه يردد ما بعد الشهادتين أيضاً ولا يكتفي بها بل يقول في (حي على الصلاة) و(حي على الفلاح) لا حول ولا قوة إلا بالله ويقول أيضاً: [اللهُ أَكْبَرُ اللهُ أَكْبَرُ لاَ إِلَهَ إِلاَّ اللهُ].`,
        f: [`(ص27) «لا حول ولا قوة إلا بالله»: وكأن الحول هو البُعد عن الشر والقوة تكون في تحصيل الخير. («بمعنًى»: أي بمعنًى واحد.)`, `(ص28) وهذا يقوي ما قلناه في أن الحروف المقطعة في أوائل السور من أسماء الله تعالى [حرف من كل اسم].`] },
      { q: `حكم ترديد قول المؤذن: واجب أم مندوب؟`, p: `28، 30`,
        n: `وهل هذا القول مثل قول المؤذن واجب على من سمعه في غير الصلاة أم مندوب؟ فيه خلاف حكاه الطحاوي، الصحيح الذي عليه الجمهور أنه مندوب.`,
        o: `الجمهور: مندوب. الحنفية (حكاه الطحاوي): واجب على السامع.`,
        s: `مسألة استحباب ترديد قول المؤذن: قال الحنفية بالوجوب على السامع لأنه قال: [إِذَا سَمِعْتُمُ الْمُؤَذِّنَ فَقُولُوا مِثْلَ مَا يَقُولُ] فقالوا بالوجوب ولا صارف لهذا الأمر، ولا يعرف جواباً للجمهور عليه يصرف هذا الأمر من الوجوب إلى الاستحباب. هناك خلاف في المسألة كما قلنا ولكن من جهة الدليل المجرد فلا نعرف صارفاً.`,
        f: [] },
      { q: `متى يردد السامع: بعد كل كلمة أم بعد فراغ المؤذن من الأذان؟ ومن يكون معذورًا (في الخلاء)`, p: `28–29`,
        n: `وفيه أنه يُستحب أن يقول السامع كل كلمة بعد فراغ المؤذن منها ولا ينتظر فراغه من كل الأذان. اعلم أنه يُستحب إجابة المؤذن بالقول مثل قوله لكل من سمعه من متطهر ومحدث وجنب وحائض وغيرهم ممن لا مانع له من الإجابة. فمن أسباب المنع: أن يكون في الخلاء، أو جماع أهله، أو نحوهما.`,
        o: NO_O,
        s: `يردد بعد كل كلمة، وقلنا أنه يقول: [الله أكبر الله أكبر] فصلها، يقولها على بعضها، وهذا الحديث من أصرح الأدلة على ذلك فمن الخطأ قول [الله أكبر] أربع مرات مقطعة لأن النبي ﷺ في الحديث قال: [إِذَا قَالَ الْمُؤَذِّنُ اللَّهُ أَكْبَرُ اللَّهُ أَكْبَرُ. فَقَالَ أَحَدُكُمُ اللَّهُ أَكْبَرُ اللَّهُ أَكْبَرُ] رغم أنهم جملتين إلا أنهم كالواحدة في القول. إلا أن يكون له عذر كأن يكون في صلاة أو في الخلاء فيؤجل ذكر الأذان حتى يزول عذره فيردد كل ما قاله المؤذن متتابعاً. والأظهر من الخلاء أن يكون أثناء قضاء الحاجة.`,
        f: [] },
      { q: `ما يقوله السامع بعد فراغ الأذان («وأنا أشهد...رضيت بالله ربًّا»)، وفضل الصلاة على النبي ﷺ والوسيلة`, p: `29`,
        n: `وفيه أنه يُستحب أن يقول بعد قوله: وأنا أشهد أن محمدًا رسول الله، رضيت بالله ربًّا، وبمحمد رسولًا، وبالإسلام دينًا. وفيه أنه يُستحب لمن رغّب غيره في خير أن يذكر له شيئًا من دلالته لينشّطه لقوله ﷺ: «فإنه من صلى عليّ مرة صلى الله عليه بها عشرًا ومن سأل لي الوسيلة حلت له الشفاعة». وفيه أن الأعمال يُشترط لها القصد والإخلاص لقوله ﷺ: (من قلبه).`,
        o: NO_O,
        s: `الصحيح أن [أَشْهَدُ أَنَّ مُحَمَّدًا رَسُولُ اللَّهِ ] التي في منتصف الأذان يرددها كما هي ولكن بعدما ينتهي من الأذان، يقول السامع: [وأنا أشهد أن لا إله إلا الله وحده لا شريك له وأن محمداً عبده ورسوله رضيت بالله رباً وبمحمد رسولاً وبالإسلام ديناً.] وهذا هو الصحيح الذي يُقال بعد فراغ المؤذن من الأذان.`,
        f: [`(ص29) «فإنه من صلى عليّ...»: وهو أسلوب الترغيب وهو أن يذكر له شيئاً من ثواب هذا الخير.`, `(ص29) «من قلبه»: فقد يقول الإنسان هذا الكلام وهو غافل وقد يقوله وهو ذاكر لقوله: (ثُمَّ قَالَ لاَ إِلَهَ إِلاَّ اللهُ. قَالَ لاَ إِلَهَ إِلاَّ اللهُ. مِنْ قَلْبِهِ دَخَلَ الْجَنَّةَ) وهذا دليل أن ليس كل الناس إذا تكلم بالأذان تستحضر معاني الأذان حين تتكلم به، فينبغي للعبد أن يستحضر معاني الأذان العظيمة التي هي قضايا الإيمان الكلية وهو يسمع الأذان ويردده وكذلك من يؤذن من باب أولى.`, `(ص31) هناك مناسبة لطيفة جداً في (رضيت بالله رباً) وهو شهود النعمة التي أنعم الله علينا بالإسلام وببعثة محمد ﷺ الجلية في الأذان فنعمة الله في الأذان جلية من المقارنة بين وسائل الإعلام عند الأمم الأخرى في الدعوة إلى العبادة فأولاً نعمة الله علينا بأن جعلنا نعبده وحده لا شريك له دون ما سواه، ثم بهذه النعمة العظيمة ببعثة النبي ﷺ وبهذا الدين العظيم، فتتجلى معاني الإسلام والإيمان في الأذان.`] },
      { q: `إجابة المؤذن وفي الصلاة: هل تُكره؟ وهل يحكي المصلي لفظ المؤذن في الفريضة والنافلة؟`, p: `29–30`,
        n: `ومنها أن يكون في صلاة فمن كان في صلاة فريضة أو نافلة فسمع المؤذن فلم يوافقه وهو في الصلاة، فإذا سلّم أتى بمثله. فلو فعله في الصلاة فهل يُكره؟ فيه قولان للشافعي ﷺ: أظهرهما أنه يكره لأنه إعراض عن الصلاة، لكن لا تبطل صلاته إن قال ما ذكرناه لأنها أذكار، فلو قال حي على الصلاة أو الصلاة خير من النوم بطلت صلاته إن كان عالمًا بتحريمه لأنه كلام آدمي. ولو سمع الأذان وهو في قراءة أو تسبيح أو نحوهما قطع ما هو فيه وأتى بمتابعة المؤذن. وقال القاضي عياض رحمه الله: اختلف أصحابنا هل يحكي المصلي لفظ المؤذن في صلاة الفريضة والنافلة، أم لا يحكيه فيهما، أم لا يحكيه في الفريضة دون النافلة؟ على ثلاثة أقوال، ومنعه أبو حنيفة فيهما.`,
        o: `ثلاثة أقوال عند المالكية: يحكيه في الفريضة والنافلة، أو لا يحكيه فيهما، أو يحكيه في النافلة دون الفريضة؛ ومنعه أبو حنيفة فيهما.`,
        s: `(يكره) ولأن النبي ﷺ ترك رد السلام الواجب حين سلم عليه: (فَقَالَ: " إِنَّ فِي الصَّلاَةِ لَشُغْلاً) ((خ) ١١٥٨ ، (م) ٣٤ – (٥٣٨)، (د) ٩٢٣). (حي على الصلاة) لأن كلمة (حي) كأنه يقول لإنسان (حي على الصلاة). (قطع ما هو فيه وأتى بمتابعة المؤذن) لأنه واجب الوقت أو سنة مؤكدة على الأقل. (وهذا قول الشافعية وهو الراجح) أي أن الإجابة تكره في الصلاة.`,
        f: [] },
      { q: `ما يقوله السامع عند الإقامة وعند «الصلاة خير من النوم» في أذان الفجر`, p: `30`,
        n: `ويتابعه في الإقامة كالأذان إلا أنه يقول في لفظ الإقامة: [أقامها الله، وأدامها]، وإذا ثوّب المؤذن في صلاة الصبح فقال: [الصلاة خير من النوم] قال سامعه: [صدقت، وبررت]. هذا تفصيل مذهبنا.`,
        o: NO_O,
        s: `وهذا لم يثبت فيه حديث صحيح فالصحيح أن يقول مثلما يقول، يقول: [قد قامت الصلاة، قد قامت الصلاة] طالما لم يرد دليل يخرج عن عموم قوله ﷺ: (إِذَا سَمِعْتُمُ الْمُؤَذِّنَ فَقُولُوا مِثْلَ مَا يَقُولُ)، تركناها في (حي على الصلاة) و(حي على الفلاح) لحديث عمر ﷺ، وفي (الصلاة خير من النوم) يقول السامع (الصلاة خير من النوم). [صدقت وبررت] ليس عليه دليل.`,
        f: [] },
      { q: `إذا تعدد المؤذنون: هل يردد السامع مع كل مؤذن؟ وهل يتابع إلى آخر الأذان أم إلى آخر الشهادتين؟`, p: `31`,
        n: `قال: واختلفوا هل يقوله عند سماع كل مؤذن أم لأول مؤذن فقط. قال: واختلف قول مالك هل يتابع المؤذن في كل كلمات الأذان أم إلى آخر الشهادتين لأنه ذكر، وما بعده ليس بذكر، وبعضه تكرار لما سبق. والله أعلم.`,
        o: `مالك (اختلف قوله): هل يتابع في كل كلمات الأذان أم إلى آخر الشهادتين.`,
        s: `أي إذا كان هناك أكثر من مؤذن، فالأقرب والله أعلم أنه إن أمكنه أن يقوله مع كل مؤذن فليفعل، وإلا فإن عجز عن متابعة الجميع فاليكن مع أول مؤذن. الصحيح نص حديث عمر ﷺ أنه يردد ما بعد الشهادتين أيضاً ولا يكتفي بها بل يقول في (حي على الصلاة) و(حي على الفلاح) لا حول ولا قوة إلا بالله ويقول أيضاً: [اللهُ أَكْبَرُ اللهُ أَكْبَرُ لاَ إِلَهَ إِلاَّ اللهُ].`,
        f: [] },
      { q: `الداخل إلى المسجد والمؤذن يؤذن للجمعة والإمام على المنبر: هل يصلي تحية المسجد أم يردد الأذان؟ (فتوى)`, p: `32`,
        n: NO_N,
        o: `فيه قولان: قول أنه يدرك تحية المسجد، والقول الثاني أن يردد الأذان أولًا.`,
        s: `إن دخل والمؤذن يؤذن للجمعة والإمام على المنبر فيه قولان: قول أنه يدرك تحية المسجد، والقول الثاني أن يردد الأذان أولاً، والذي عندي أن يردد الأذان أولاً؛ لأنه عندي هو أوجب. (فتوى)`,
        f: [`(ص32) في بيان المعاني العقدية للأذان عند القاضي عياض: «من الأمور التي دل عليها العقل بالإضافة إلى السمع وهي الأدلة النقلية وتتضمن الأمور التي دل عليها السمع من أدلة نقلية ولو لم تُعرف بالعقول المجردة، فالتوحيد دل عليه العقل والأدلة السمعية النقلية تؤكده. (أي دالة على العقائد العقلية والسمعية.) (بقوله: لا إله إلا الله.) وقوله «جائزة الوقوع» أي يقصد جائزة الوقوع عقلاً فإرسال الرسالة غير ممتنع عقلاً، بل الصحيح أن الرسالة من منة الله تعالى وأن العقول السليمة تشهد بأن الله أحق على نفسه أنه لا يعذب الناس إلا بعد إرسال الرسل. فالتوحيد من باب الواجبات والرسالة عند المتكلمين من باب الأفعال الجائزة.»`, `(ص33) لولا الإشارات الكلامية فإنها ليست من النفائس وللحق فإن الأذان أعظم مما ذكر، فعند التدبر نجد معاني التوحيد والإيمان أعظم مما ذكر.`] },
    ],
  },
  {
    title: `باب فضل الأذان وهرب الشيطان عند سماعه (ص33–38)`,
    items: [
      { q: `معنى «المؤذنون أطول الناس أعناقًا يوم القيامة»`, p: `35–36`,
        n: `فقوله ﷺ: (المؤذنون أطول الناس أعناقًا) هو بفتح همزة أعناقًا جمع عنق، واختلف السلف والخلف في معناه: فقيل: معناه أكثر الناس تشوفًا إلى رحمة الله تعالى لأن المتشوف يطيل عنقه إلى ما يتطلع إليه، فمعناه كثرة ما يرونه من الثواب. وقال النضر بن شميل: إذا ألجم الناس العرق يوم القيامة طالت أعناقهم لئلا ينالهم ذلك الكرب والعرق. وقيل: معناه أنهم سادة ورؤساء والعرب نصف السادة بطول العنق. وقيل: معناه أكثر أتباعًا. وقال ابن الأعرابي: معناه أكثر الناس أعمالًا. قال القاضي عياض وغيره: ورواه بعضهم (إعناقًا) بكسر الهمزة أي إسراعًا إلى الجنة، وهو من سير العنق.`,
        o: `أقوال: أكثر تشوفًا إلى رحمة الله؛ طول الأعناق حقيقةً يوم القيامة (النضر بن شميل)؛ السيادة؛ كثرة الأتباع؛ كثرة الأعمال (ابن الأعرابي)؛ (إعناقًا) أي إسراعًا إلى الجنة.`,
        s: `وهنا حمل الحديث على ظاهره وهذا أولى. (وقوله «إعناقًا»: أي السير السريع.)`,
        f: [] },
      { q: `شهادة الجن والإنس وغيرهم للمؤذن يوم القيامة: هل هي عامة للمؤمن والكافر والحيوان والجماد؟`, p: `36–37`,
        n: `قال العلماء: وإنما أدبر الشيطان عند الأذان لئلا يسمعه فيضطر إلى أن يشهد له بذلك يوم القيامة لقول النبي ﷺ: «لا يسمع صوت المؤذن جنٌّ ولا إنس ولا شيء إلا شهد له يوم القيامة». قال القاضي عياض: وقيل: إنما يشهد له المؤمنون من الجن والإنس، فأما الكافر فلا شهادة له. قال: ولا يُقبل هذا من قائله لما جاء في الآثار من خلافه. قال: وقيل: إن هذا فيمن يصح منه الشهادة ممن يسمع. وقيل: بل هو عام في الحيوان والجماد، وأن الله تعالى يخلق لها ولما لا يعقل من الحيوان إدراكًا للأذان وعقلًا ومعرفة. وقيل: إنما يُدبر الشيطان لعظم أمر الأذان لما اشتمل عليه من قواعد التوحيد، وإظهار شعائر الإسلام، وإعلانه. وقيل: ليأسه من وسوسة الإنسان عند الإعلان بالتوحيد.`,
        o: `أقوال: لا يشهد له إلا المؤمنون من الجن والإنس؛ أو فيمن تصح منه الشهادة؛ أو هو عام في الحيوان والجماد وأن الله يخلق لها إدراكًا وعقلًا ومعرفة؛ وفي سبب إدبار الشيطان: عظم أمر الأذان، أو اليأس من وسوسة الإنسان عند الإعلان بالتوحيد.`,
        s: `والإنس تشمل المؤمن والكافر. (وعن القول بالعموم في الحيوان والجماد:) وهذا هو الصحيح. (إدراكًا وعقلًا ومعرفة:) يكفي كلمة (إدراكًا) و(عقلًا) لا نعرفها.`,
        f: [] },
      { q: `الأفضل للإنسان: أن يرصد نفسه للأذان أم للإمامة؟`, p: `38`,
        n: `أما فقه الباب: فضيلة الأذان والمؤذن، وقد جاءت فيه أحاديث كثيرة في الصحيحين مصرِّحة بعظم فضله، واختلف أصحابنا هل الأفضل للإنسان أن يرصد نفسه للأذان أم للإمامة على أوجه: أصحها الأذان أفضل، وهو نص الشافعي في الأم وقول أكثر أصحابنا. والثاني الإمامة أفضل وهو نص الشافعي أيضًا. والثالث هما سواء. والرابع إن علم من نفسه القيام بحقوق الإمامة وجميع خصالها فهي أفضل، وإلا فالأذان، قاله أبو علي الطبري وأبو القاسم بن كج والمسعودي والقاضي حسين من أصحابنا.`,
        o: `أربعة أوجه عند الشافعية: الأذان أفضل (الأصح)، الإمامة أفضل، سواء، التفصيل (الإمامة أفضل إن علم القيام بحقوقها وإلا فالأذان).`,
        s: `الله أعلم، فليس عندنا دليل يرجح بين الأذان والإمامة في حق الناس، وأما في حق النبي ﷺ فلا شك أن الإمامة أفضل، وعلى أي الأحوال كان الأئمة من بعده يؤمون الناس: أبو بكر وعمر وعثمان وعلي ﷺ كانوا يؤمون الناس.`,
        f: [] },
      { q: `الجمع بين الإمامة والأذان لرجل واحد`, p: `38`,
        n: `وأما جمع الرجل بين الإمامة والأذان: فإن جماعة من أصحابنا يُستحب ألّا يفعله. وقال بعضهم: يُكره. وقال محققوهم وأكثرهم: أنه لا بأس به، بل يُستحب، وهذا أصح. والله أعلم.`,
        o: `قيل: يُستحب ألا يفعله، وقيل: يُكره، وقال أكثر المحققين: لا بأس به بل يُستحب (الأصح).`,
        s: `وهذا هو الظاهر ولا يُكره لعدم وجود دليل يدل على الكراهة. والأصح والأفضل أن يكون المؤذن غير الإمام ولكن إن فعل فصح ذلك ولا حرج.`,
        f: [] },
    ],
  },
  {
    title: `باب استحباب رفع اليدين حذو المنكبين مع تكبيرة الإحرام والركوع وفي الرفع من الركوع وأنه لا يفعله إذا رفع من السجود (ص39–49)`,
    items: [
      { q: `مواضع رفع اليدين في الصلاة: عند تكبيرة الإحرام وعند الركوع والرفع منه، وعند القيام من التشهد الأول، وفي السجود`, p: `40–42`,
        n: `أجمعت الأمة على استحباب رفع اليدين عند تكبيرة الإحرام، واختلفوا فيما سواها: فقال الشافعي وأحمد وجمهور العلماء من الصحابة ﵃ فمن بعدهم: يُستحب رفعهما أيضًا عند الركوع وعند الرفع منه، وهو رواية عن مالك. وللشافعي قول أنه يُستحب رفعهما في موضع آخر رابع وهو إذا قام من التشهد الأول، وهذا القول هو الصواب، فقد صح فيه حديث ابن عمر عن النبي ﷺ أنه كان يفعله، رواه البخاري، وصح أيضًا من حديث أبي حميد الساعدي، رواه أبو داود والترمذي بأسانيد صحيحة. وقال أبو بكر بن المنذر وأبو علي الطبري من أصحابنا وبعض أهل الحديث: يُستحب أيضًا في السجود. وقال أبو حنيفة وأصحابه وجماعة من أهل الكوفة: لا يُستحب في غير تكبيرة الإحرام، وهو أشهر الروايات عن مالك.`,
        o: `الجمهور (الشافعي وأحمد ومالك في رواية): عند الإحرام والركوع والرفع منه (وللشافعي قول بموضع رابع: القيام من التشهد الأول). ابن المنذر والطبري وبعض أهل الحديث: وفي السجود أيضًا. أبو حنيفة وأصحابه وجماعة من أهل الكوفة وأشهر الروايات عن مالك: لا يرفع إلا عند تكبيرة الإحرام.`,
        s: `استدلالاً بحديث مسلم: (أَنَّ أَبَا هُرَيْرَةَ كَانَ يُصَلِّي لَهُمْ فَيُكَبِّرُ كُلَّمَا خَفَضَ وَرَفَعَ فَلَمَّا انْصَرَفَ قَالَ وَاللَّهِ إِنِّي لأَشْبَهُكُمْ صَلاَةً بِرَسُولِ اللَّهِ ﷺ.) وأكثر العلماء على تصحيح حديث (يكبر في كل خفض ورفع) وليس (يرفع في كل خفض ورفع) والألباني صحح حديث (يرفع في كل خفض ورفع) ويحمله على بعض الأحيان أي أنه يفعله أحياناً ولكن كثير من العلماء يرون هذه الرواية شاذة وهي مخالفة لما في الصحيحين في أنه لا يفعله في السجود، وذكر حديث ابن عمر في الصحيحين (ولا يفعل ذلك حين يسجد ولا حين يرفع رأسه من السجود). وهذا هو الأقرب عندي ولكن المسألة محل اجتهاد فلو فعل ذلك أحياناً لم ينكر عليه. وقول أبي حنيفة وهو قول مخالف للأحاديث الثابتة الصحيحة أن النبي ﷺ كان يرفع يديه إذا كبر في الركوع وفي الرفع منه.`,
        f: [`(ص40–41) تخريج الحديث: رواية البخاري عن ابن عمر: «إِذَا دَخَلَ فِي الصَّلاَةِ كَبَّرَ وَرَفَعَ يَدَيْهِ وَإِذَا رَكَعَ رَفَعَ يَدَيْهِ وَإِذَا قَالَ سَمِعَ اللَّهُ لِمَنْ حَمِدَهُ رَفَعَ يَدَيْهِ وَإِذَا قَامَ مِنَ الرَّكْعَتَيْنِ رَفَعَ يَدَيْهِ وَرَفَعَ ذَلِكَ ابْنُ عُمَرَ إِلَى نَبِيِّ اللَّهِ ﷺ»؛ ورواية أبي داود لحديث أبي حميد الساعدي في عشرة من أصحاب النبي ﷺ (ورفع اليدين في المواضع المذكورة)؛ ورواية الترمذي (حسن صحيح)، ورواية البخاري في التكبير والرفع أثناء القيام عن أبي هريرة.`] },
      { q: `حكم رفع اليدين في الصلاة: واجب أم مستحب؟`, p: `42`,
        n: `وأجمعوا على أنه لا يجب شيء من الرفع، وبهذا قال الإمام أبو الحسن أحمد بن سيَّار السيَّاري من أصحابنا أصحاب الوجوه، وقد حكيته عنه في شرح المهذب وفي تهذيب اللغات. وحُكي عن داود إيجابه عند تكبيرة الإحرام.`,
        o: `داود (حُكي عنه): يجب الرفع عند تكبيرة الإحرام.`,
        s: `هذا الإجماع هو الصارف لقول النبي ﷺ: (صلوا كما رأيتموني أصلي) مع ثبوت رفع اليدين في هذه المواضع فهذا الإجماع هو الصارف لهذا الحديث من الوجوب إلى الاستحباب. (أصحاب الوجوه:) أي علماء الشافعية المجتهدون في المذهب هم أصحاب الوجوه فيه. (وحُكي عن داود:) ولكن هذا خلاف شاذ.`,
        f: [] },
      { q: `صفة رفع اليدين: إلى أين ترتفع؟ ومحاذاة الكفين والإبهامين، وهل تُمدّ اليدان؟`, p: `43`,
        n: `وأما صفة الرفع: فالمشهور من مذهبنا ومذهب الجماهير أنه يرفع يديه حذو منكبيه بحيث تحاذي أطراف أصابعه فروع أذنيه أي أعلى أذنيه، وإبهاماه شحمتي أذنيه، وراحتاه منكبيه، فهذا معنى قولهم: حذو منكبيه، وبهذا جمع الشافعي ﷺ بين روايات الأحاديث فاستحسن الناس ذلك منه.`,
        o: `بعض العلماء يجعلها روايات متعارضة؛ وبعضهم يجعلها أحوالًا.`,
        s: `يحاذي بإبهاميه شحمتي الأذن ويحاذي براحة يديه منكبيه ولا يلزم اللمس فلم يرد اللمس، ولكن يحاذي بها ولو لمسها بدون قصد فلا شيء عليه ولكن هي المحاذاة فتكون أطراف الأصابع أمام أعلى الأذن وراحة يديه أمام المنكب لو نزل قليلاً فهذا من المسموح به؛ ومن الخطأ جعل أطراف الأصابع ممدودة إلى الأرض تجاه القبلة ولا يكاد يرفع يديه فهذا مما لم يرد نهائياً؛ فلم يرد اللمس ولم يرد الرفع القصير جداً. ولو أحد فعل ذلك سيحتج بفعل الشيخ فلان فلننتبه فقد سُئل الإمام أحمد فقيل له أنت تفعل كذا، فقال: أنا أسهو، فلا تحتج بالأفعال واحتج بالأقوال لأنه في بعض الأوقات لا يدري الإنسان فقد يكون مشغولاً بشيء فلم تتم الصفة كما ينبغي. ولا ينبغي أن يثني يديه فالسنة في رفع اليدين أن يمدها. ومحاذاة الكفين المنكبين ومن أين نستقبل القبلة وذلك من محاذاة المنكب: فالكف هو الراحة فلو حاذت المنكب فلو كان الكفين فاتجاه بعض فيكون بذلك عمودي على الكتف فلم تكون بذلك محاذية، ولكنه إذا حاذى براحتيه منكبيه فهذا يدل على استقبال القبلة. والبعض يجعلها أحوال وأحوال فيمكن أن يحاذي بها منكبيه فتكون يديه أمام المنكب فهذا حال، وأحياناً أخرى يرفع إلى أطراف أذنيه، وقول الشافعي حسن ولكن لا أقل من أنه يرفع يديه حذو منكبيه وجمع الشافعي أحسن لأنه يجمع بين الأدلة كلها وأقصى هبوط أن تكون اليد كلها أمام الكتف لكن السنة أن يرفع يديه إلى أطراف أذنيه.`,
        f: [] },
      { q: `وقت الرفع: هل يكون قبل التكبير أم معه أم بعده؟ وكيف يبتدئ وينتهي؟`, p: `43–44`,
        n: `وأما وقت الرفع: ففي الرواية الأولى [رفع يديه ثم كبّر]، وفي الثانية [كبّر ثم رفع يديه]، وفي الثالثة [إذا كبّر رفع يديه]، ولأصحابنا فيه أوجه: أحدها يرفع غير مكبِّر، ثم يبتدئ التكبير مع إرسال اليدين وينهيه مع انتهائه. والثاني يرفع غير مكبِّر، ثم يكبِّر ويداه قارَّتان، ثم يرسلهما. والثالث يبتدئ الرفع من ابتدائه التكبير، وينهيهما معًا. والرابع يبتدئ بهما معًا وينهي التكبير مع انتهاء الإرسال. والخامس وهو الأصح يبتدئ الرفع مع ابتداء التكبير، ولا استحباب في الانتهاء.`,
        o: `خمسة أوجه عند الشافعية في وقت الرفع بالنسبة للتكبير.`,
        s: `ثلاث روايات، والأقرب أنه إذا فعل أي من ذلك أجزأ. بل كل ذلك جائز، وكما قلنا الروايات تدل على جواز أن يرفع يديه ثم يكبر أو يكبر ثم يرفع يديه أو أن يكبر مع رفع اليدين، ويمكن أن يكون (ثم) لعطف فعل على فعل والله أعلم، ولكن الأقرب هو حمل الأحاديث على ظاهرها والتخيير بأن كل ذلك جائز. الفرق بين الثالث والرابع: في الرابع ينهي التكبير (الراء) مع انتهاء الارسال، وفي الثالث يبدأ في تنزيل يديه مع (الراء) فينزل يده قبل انتهاء التكبير وعندما يصل (للراء) في (أكبر) تكون يده على صدره مع انتهاء التكبير؛ والنووي يرجح أن يكون الرفع مع ابتداء التكبير ولا استحباب في الانتهاء أي كل ذلك هو فيه مخير، وهذا أولى من شغل النفس بهذا، فالنبي ﷺ كان يصنع هذا وهذا فالأمر واسع.`,
        f: [] },
      { q: `من فرغ من التكبير قبل تمام الرفع أو بالعكس، ومن قُطعت يداه أو إحداهما، ومن لم يقدر على الرفع إلا بزيادة أو نقص`, p: `44`,
        n: `(مسائل) فإن فرغ من التكبير قبل تمام الرفع أو بالعكس تمّم الباقي، وإن فرغ منهما حطَّ يديه ولم يستدم الرفع. ولو كان أقطع اليدين من المعصم أو إحداهما رفع الساعد، وإن قُطع من الساعد رفع العضد على الأصح، وقيل: لا يرفعه، ولو لم يقدر على الرفع إلا بزيادة على المشروع أو نقص منه فعل الممكن، فإن أمكن فعل الزائد...`,
        o: `قيل: لا يرفع العضد إذا قُطع من الساعد (قول مرجوح عند الشافعية).`,
        s: `(على الأصح) لأن الرفع فيه رفع جزء من العضد ليصل إلى الرفع حذو الأذنين ولذلك قال على الأصح. (وقيل: لا يرفعه) طريقة الإمام النووي عندما ينقل مذهبهم بها [أنه] إذا قال (وقيل) يكون هذا قول ضعيف مرجوح عند الشافعية. (ولو لم يقدر على الرفع إلا بزيادة...) بمعنى أن يده بها وجع ولا يستطيع الرفع إلا مسافة صغيرة لا تصل إلى المنكبين يرفع أم لا؟ يرفع (فاتقوا الله ما استطعتم)، وكذلك هو يستطيع أن يرفع عالياً جداً ولكن لا يستطيع الرفع عند هذا الموضع المشروع فعليه أن يرفع عالياً.`,
        f: [] },
      { q: `هيئة الكفين والأصابع عند الرفع (استقبال القبلة، كشفهما، تفريق الأصابع)`, p: `45`,
        n: `ويُستحب أن يكون كفّاه إلى القبلة عند الرفع، وأن يكشفهما، وأن يفرِّق بين أصابعهما تفريقًا وسطًا.`,
        o: NO_O,
        s: `(أن يكشفهما) لأن الصحابة رأوا راحتي النبي ﷺ. (تفريقًا وسطًا) لا نعرف نصًّا في هذه الجزئية.`,
        f: [] },
      { q: `من ترك الرفع حتى أتى ببعض التكبير: هل يرفع في الباقي؟ ومن تركه حتى أتمّه`, p: `45`,
        n: `ولو ترك الرفع حتى أتى ببعض التكبير رفعهما في الباقي، فلو تركه حتى أتمّه لم يرفعهما بعده.`,
        o: NO_O,
        s: `بل الظاهر أن يرفعها لرواية ابن عمر قال: كان رسول الله ﷺ إذا قام للصلاة رفع يديه حتى تكونا حذو منكبيه ثم كبر فإذا أراد أن يركع فعل مثل ذلك وإذا رفع من الركوع فعل مثل ذلك ولا يفعله حين يرفع رأسه من السجود. وتحتمل أنه أثناء الرفع كبر. وهذا أولى أن يحرص على أن يكون جزء من التكبير مقارن لجزء من الرفع.`,
        f: [] },
      { q: `مدّ التكبير: كيف يكون؟ وهل يمدّه أو يخففه؟`, p: `45`,
        n: `ولا يقصِّر التكبير بحيث لا يُفهم، ولا يبالغ في مدِّه بالتمطيط، بل يأتي به مبيَّنًا. وهل يمدُّه أو يخفِّفه؟ فيه وجهان أصحهما يخفِّفه.`,
        o: `وجهان: يمده أو يخففه (الأصح التخفيف).`,
        s: `وهو مد (الله) لا يقصره بحيث لا يفهم ولا يبالغ في مده بالتمطيط بل يمد المد الطبيعي. أي يجعله مقصور أم أربع حركات، الصحيح أنه يخففه لأن هذا موضع ليس من مواضع المد، فيمد مد طبيعي فقط فلا يمد مداً مبالغ فيه وهذا أصح؛ ولكن بعض القراء يقول: هذا مد تعظيم والصحيح ما ذكرنا.`,
        f: [] },
      { q: `موضع وضع اليدين في الصلاة: على الصدر أم فوق السرة أم تحتها؟`, p: `45–46`,
        n: `وإذا وضع يديه: حطَّهما تحت صدره فوق سُرَّته، هذا مذهب الشافعي والأكثرين، وقال أبو حنيفة وبعض أصحاب الشافعي: تحت سرَّته. والأصح أنه إذا أرسلهما إرسالًا خفيفًا إلى تحت صدره فقط، ثم يضع اليمين على اليسار. وقيل: يرسلهما إرسالًا بليغًا ثم يستأنف رفعهما إلى تحت صدره.`,
        o: `الشافعي والأكثرون: تحت الصدر فوق السرة. أبو حنيفة وبعض الشافعية: تحت السرة. وقيل: يرسلهما إرسالًا بليغًا ثم يرفعهما.`,
        s: `والصحيح أنه يضعها على صدره فإنه لم يثبت فوق السرة ولا تحتها أحاديث وإنما ثبتت أحاديث أنه ﷺ كان يضعها على صدره في الصلاة، فأي موضع من الضلوع تجزئ طالما يده موضوعة على الضلوع.`,
        f: [`(ص45–46) أحاديث وضع اليدين على الصدر: حديث طاووس مرسلاً (رواه أبو داود في المراسيل)، قال الأرنؤوط: مرسل رجاله ثقات؛ وقال الألباني: صحيح. وحديث وائل بن حجر عند ابن خزيمة: «صَلَّيْتُ مَعَ رَسُولِ اللَّهِ ﷺ وَوَضَعَ يَدَهُ الْيُمْنَى عَلَى يَدِهِ الْيُسْرَى عَلَى صَدْرِهِ» قال الألباني: إسناده ضعيف لأن مؤملاً وهو ابن إسماعيل سيئ الحفظ لكن الحديث صحيح جاء من طرق أخرى بمعناه وفي الوضع على الصدر أحاديث تشهد له. وفي «معرفة السنن والآثار» للبيهقي عن علي في الآية ﴿فَصَلِّ لِرَبِّكَ وَانْحَرْ﴾: وضع يده اليمنى على يده اليسرى على صدره. والذي روي عنه تحت السرة لم يثبت، تفرد بإسناده عبد الرحمن بن إسحاق الواسطي وهو متروك، وروي عن ابن عباس ثم عن سعيد بن جبير وأبي مجلز مثل قولنا.`, `(ص46) روايات تحت السرة: حديث علي «مِنَ السُّنَّةِ وَضْعُ الْكَفِّ عَلَى الْكَفِّ فِي الصَّلاَةِ تَحْتَ السُّرَّةِ» (د ٧٥٦، ضعفه الألباني)، و(حم ٨٧٥) إسناده ضعيف، وحديث أبي هريرة «أَخْذُ الأَكُفِّ عَلَى الأَكُفِّ فِي الصَّلاَةِ تَحْتَ السُّرَّةِ» (د ٧٥٨، ضعيف لضعف عبد الرحمن بن إسحاق الكوفي)، وما رُوي عن سعيد بن جبير «فوق السرة» (د ٧٥٧، ضعيف).`] },
      { q: `الحكمة في رفع اليدين في الصلاة`, p: `47`,
        n: `واختلفت عبارات العلماء في الحكمة في رفع اليدين: فقال الشافعي ﵁: فعلته إعظامًا لله تعالى واتباعًا لرسول الله ﷺ. وقال غيره: هو استكانة واستسلام وانقياد، وكان الأسير إذا غُلب مدَّ يديه علامة للاستسلام. وقيل: هو إشارة إلى استعظام ما دخل فيه. وقيل: إشارة إلى طرح أمور الدنيا والإقبال بكليَّته على الصلاة ومناجاة ربه سبحانه وتعالى كما تضمن ذلك قوله (الله أكبر)، فيطابق فعله قوله. وقيل: إشارة إلى دخوله في الصلاة وهذا الأخير مختص بالرفع لتكبيرة الإحرام. وقيل غير ذلك، وفي أكثرها نظر. والله أعلم.`,
        o: `أقوال: إعظام لله واتباع للرسول (الشافعي)، استكانة واستسلام وانقياد، استعظام ما دخل فيه، طرح الدنيا والإقبال على الصلاة، إشارة إلى الدخول في الصلاة (خاص بتكبيرة الإحرام).`,
        s: `كلام الشافعي أحسن كلام: [تعظيماً لله واتباعاً لرسول الله ﷺ]. وليس هذا متعارضاً مع كلام الشافعي بل هو تفصيل له فإن التعظيم يشمل الاستكانة والاستسلام والانقياد. وأما «طرح أمور الدنيا» فهذه ليست بظاهرها وهو أن يرمي الدنيا وراء ظهره، فهذه إشارات تشبه إشارات الصوفية.`,
        f: [] },
      { q: `حكم تكبيرة الإحرام: ركن أم واجب أم سنة؟ (والفرق بين الركن والواجب والسنة عند الحنابلة)`, p: `48`,
        n: `وتكبيرة الإحرام: واجبة عند مالك والثوري والشافعي وأبي حنيفة وأحمد والعلماء كافة من الصحابة والتابعين فمن بعدهم ﷺ. إلا ما حكاه القاضي عياض رحمه الله وجماعة عن ابن المسيب والحسن والزهري وقتادة والحكم والأوزاعي أنه سنة ليس بواجب، وأن الدخول في الصلاة يكفي فيه النية، ولا أظن هذا يصح عن هؤلاء الأعلام مع هذه الأحاديث الصحيحة مع حديث علي ﷺ أن رسول الله ﷺ قال: «مفتاح الصلاة الطهور وتحريمها التكبير وتحليلها التسليم».`,
        o: `ابن المسيب والحسن والزهري وقتادة والحكم والأوزاعي (على ما حكاه القاضي عياض): سنة، والنية تكفي في الدخول.`,
        s: `كلمة (واجبة) عند مالك والشافعي وأبي حنيفة مقصدهم ما يساوي الركن لأن ليس عندهم تقسيم إلى واجب وركن، والواجب والركن تقسيم موجود عند الإمام أحمد فقط مثلما يقسم في الحج إلى: أفعال ركن وأفعال واجبة وأفعال مستحبة فكذلك يفعل في الصلاة وهذا أحسن تقسيم وأحسن مذهب تجتمع فيه الأدلة كما سيأتي. فالكلام يقصد به هنا الركنية. والفرق بينهما: أن الواجب: إذا تركه جاهل صحة صلاته، وإذا تركه ساهٍ سجد للسهو، وإذا تركه متعمداً بطلت الصلاة عند أحمد؛ أما الركن: فلا تصح الصلاة إلا به من جاهل أو ناسي أو عامد، فإذا تركه فلابد أن يأتي به حتى تصح صلاته؛ فالفرق بين الركن والواجب موجود عند الإمام أحمد فقط، فإذا وجد شيء واجب عند غيرهم فهي ركن عندهم ولذلك عند بقية المذاهب يرون أنه إذا ثبت شيء يجبر بسجود السهو فيكون عندهم ليس بواجب بل سنة مؤكدة، فالتشهد الأوسط عند مالك والشافعي يرونه سنة مؤكدة لأنه يجبر بسجود السهو. التحريم تشبيهاً لها بالحج وهو أن هناك لحظة يدخل فيها في المناسك وكذلك هناك لحظة يدخل فيها للعبادة وهي التكبير، وتحليلها التسليم تشبيهاً لها بالتحلل من المناسك أيضاً. ونحن لا نشك في ركنية تكبيرة الإحرام لصحة ذلك في حديث المسيء صلاته وهو الأصل في معرفة الأركان.`,
        f: [] },
      { q: `لفظ التكبير: هل يجزئ غير «الله أكبر»؟ («الله الأكبر»، «الله الكبير»، «الرحمن أكبر»، «الله أعظم»)`, p: `48–49`,
        n: `ولفظة التكبير (الله أكبر)، فهذا يجزي بالإجماع. قال الشافعي: ويجزي [الله الأكبر] لا يجزي غيرهما، وقال مالك: لا يجزي إلا [الله أكبر]، وهو الذي ثبت أن النبي ﷺ كان يقوله، وهذا قول منقول عن الشافعي في القديم، وأجاز أبو يوسف (الله الكبير)، وأجاز أبو حنيفة الاقتصار فيه على كل لفظ فيه تعظيم الله تعالى كقوله الرحمن أكبر، أو الله أجل أو أعظم، وخالفه جمهور العلماء من السلف والخلف. والحكمة في ابتداء الصلاة بالتكبير افتتاحها بالتنزيه والتعظيم لله تعالى ونعته بصفات الكمال. والله أعلم.`,
        o: `الشافعي (الجديد): يجزئ «الله أكبر» و«الله الأكبر». مالك والشافعي في القديم وأحمد: لا يجزئ إلا «الله أكبر». أبو يوسف: «الله الكبير». أبو حنيفة: كل لفظ فيه تعظيم لله تعالى.`,
        s: `وهذا هو الصحيح أنه لا يجزئ إلا (الله أكبر) ولم يرد غير ذلك، والأصل في العبادة التوقيف، فكما لا يجوز أن نقول مثلاً "استجاب الله لمن شكره" بالمعنى فكذلك فلابد أن نلتزم بالألفاظ، إذ كان النبي ﷺ قد قال للذي قال: ورسولك الذي أرسلت، قال: لا، بل قل: "ونبيك الذي أرسلت" في غير الصلاة وقد أكد على التكبير، وكل من نقل صلاته ﷺ لم ينقل إلا (الله أكبر) فلم ينقلوا قط (الله الأكبر) ولا (الله الكبير) ولا (الله أعظم) مرة من المرات. فيكون كلام الشافعي القديم هو المعتمد وقول مالك وهو قول أحمد.`,
        f: [`(ص49) وكذلك تصغير كل شيء يهم العبد من أمور الدنيا حتى يقبل بصلاته على الله ﷻ. (تعليقًا على الحكمة في ابتداء الصلاة بالتكبير.)`] },
    ],
  },
  {
    title: `باب إثبات التكبير في كل خفض ورفع في الصلاة إلا رفعه من الركوع فيقول فيه سمع الله لمن حمده (ص49–55)`,
    items: [
      { q: `تكبيرات الانتقال في الصلاة: عددها، وحكمها (ركن أم واجب أم سنة)، ومن تلا آية سجدة`, p: `51–52`,
        n: `فيه إثبات التكبير في كل خفض ورفع إلا في رفعه من الركوع فإنه يقول: سمع الله لمن حمده، وهذا مُجمَع عليه اليوم ومن الأعصار المتقدمة، وقد كان فيه خلاف في زمن أبي هريرة، وكان بعضهم لا يرى التكبير إلا للإحرام، وبعضهم يزيد عليه بعض ما جاء في حديث أبي هريرة، وكان هؤلاء لم يبلغهم فعل رسول الله ﷺ، ولهذا كان أبو هريرة يقول: إني لأشبهكم صلاة برسول الله ﷺ، واستقر العمل على ما في حديث أبي هريرة هذا: ففي كل صلاة ثنائية إحدى عشرة تكبيرة: وهي تكبيرة الإحرام، وخمس في كل ركعة. وفي الثلاثية سبع عشرة: وهي تكبيرة الإحرام، وتكبيرة القيام من التشهد الأول، وخمس في كل ركعة. وفي الرباعية اثنتان وعشرون، ففي المكتوبات الخمس: أربع وتسعون تكبيرة. واعلم أن تكبيرة الإحرام واجبة، وما عداها سنة، لو تركه صحت صلاته، لكن فاتته الفضيلة، وموافقة السنة. هذا مذهب العلماء كافة إلا أحمد بن حنبل ﷺ وفي إحدى الروايتين عنه أن جميع التكبيرات واجبة، ودليل الجمهور أن النبي ﷺ علّم الأعرابي الصلاة فعلّمه واجباتها فذكر منها تكبيرة الإحرام ولم يذكر ما زاد، وهذا موضع البيان ووقته، ولا يجوز التأخير عنه.`,
        o: `الجمهور: تكبيرة الإحرام واجبة وما عداها سنة. أحمد (في إحدى الروايتين): جميع التكبيرات واجبة. (وكان بعضهم في زمن أبي هريرة لا يرى التكبير إلا للإحرام.)`,
        s: `قلنا أنه يقصد أنها ركن. فإنها [إحدى الروايتين] هي المرجحة، وهي أنها واجبة ولكن ليست واجبة كما عند الجمهور، فهي عنده واجبة وليست بركن. قلنا حديث المسيء صلاته ما من أحد من العلماء إلا وأوجب شيئاً زائداً على ما في حديث المسيء صلاته استدلالاً بالأحاديث الأخرى إلا الإمام أحمد رحمه الله فإن مذهبه أن حديث المسيء صلاته أصل في الأركان، وأفعال النبي ﷺ وأقواله أصل في بيان الواجبات بالإضافة إلى الأركان، وإذا وقع إجماع أو دل دليل على عدم وجوب شيء من هذه الأفعال والأقوال فهو الصارف إلى الاستحباب؛ وبهذا فإن أفعال الصلاة ثلاثة أنواع: فالواردة في حديث المسيء صلاته هي الأركان التي لابد من فعلها ولا يجوز تركها ولا تصح الصلاة إلا بها عمداً أو سهواً أو جهلاً. وما سوى ذلك من الأفعال التي ورد بها أمر مباشر من قول النبي ﷺ أو فعل مع قوله: (صلوا كما رأيتموني أصلي)، ولم يصرفها صارف من كتاب أو سنة أو إجماع إلى الاستحباب فهي واجبات، إذا سها عنها سجد للسهو وإذا تركها جاهلاً صحة صلاته حتى يُعلم، فتكون العلة في عدم بلاغ المسيء صلاته في هذا الموطن حتى لا تستكثر عليه فيعجز عن حفظها فعلمه النبي ﷺ ما تصح به صلاته فقط ويعفى عن باقي الواجبات لجهله، ولكن لا يجوز تركها عمداً، فإذا تركها عمداً بطلت صلاته عند أحمد.`,
        f: [`(ص51) فبعضهم كان يقول التكبير في بعض الأحيان ويترك الباقي، والذي يدل على وجود الخلاف أنهم قالوا له: (فَقُلْنَا يَا أَبَا هُرَيْرَةَ: مَا هَذَا التَّكْبِيرُ؟) لوجود أُناس كانت تصلي على خلاف ذلك.`, `(ص52) وسيزاد عليها لو أنه قرأ في آياتها سجدة فإنه يكبر في كل خفض ورفع على ظاهر الحديث أنه يكبر كلما خفض ورفع وهذا هو الصحيح خلافاً لبعض المعاصرين القائلين أن تكبير سجود التلاوة غير مشروع بل هو مشروع لأنه داخل في عموم قوله يكبر في كل خفض ورفع.`] },
      { q: `موضع التكبير في الانتقالات: هل يقارن الحركة أم يُبسط عليها؟ وما مذهب مالك في القيام من الركعتين، وتعقيب الشيخ على الألباني`, p: `53–54`,
        n: `وقوله: (يكبّر حين يهوي ساجدًا. ثم يكبّر حين يرفع، ويكبّر حين يقوم، من المثنى) هذا دليل على مقارنة التكبير لهذه الحركات وبسطه عليها، فيبدأ بالتكبير حين يشرع في الانتقال إلى الركوع ويمدُّه حتى يصل حدَّ الراكعين، ثم يشرع في تسبيح الركوع، ويبدأ بالتكبير حين يشرع في الهويّ إلى السجود ويمدُّه حتى يضع جبهته على الأرض، ثم في تسبيح السجود، ويبدأ في قوله سمع الله لمن حمده حين يشرع في الرفع من الركوع ويمدُّه حتى ينتصب قائمًا، ثم يشرع في ذكر الاعتدال وهو ربنا لك الحمد إلى آخره، ويشرع في التكبير للقيام من التشهد الأول حين يشرع في الانتقال ويمدُّه حتى ينتصب قائمًا. هذا مذهبنا ومذهب العلماء كافة. إلا ما رُوي عن عمر بن عبد العزيز ﵁ وبه قال مالك أنه لا يكبِّر للقيام من الركعتين حتى يستوي قائمًا، ودليل الجمهور ظاهر الحديث.`,
        o: `عمر بن عبد العزيز ومالك: لا يكبِّر للقيام من الركعتين حتى يستوي قائمًا. الجمهور: يكبّر حين يشرع في الانتقال. (والألباني: يكبّر وهو جالس ثم يرفع.)`,
        s: `الصحيح أنه حين يقوم. وأما كلام الشيخ الألباني فهو بخلاف ذلك كله وهو أن يكبر وهو جالس ثم يرفع، فهذا لا يعرف عمّن تقدم من أقوال العلماء. وهذا الكلام واضح جداً وهو خلاف لبعض الأفاضل المعاصرين – الشيخ الألباني رحمه الله – فإنه يقول يكبر ثم يشرع في الركوع، وقد ذكر روايات صحيحة في أنه يكبر ثم يركع ولكنها لا تدل على ما ذهب إليه من أنه يكبر ثم يشرع في الركوع، فليست تدل على أنه يشرع في القيام وإنما يكبر ثم يسجد أي يستتم ساجداً فهي موافقة للرواية المصرحة بالفعل أثناء الانتقال يكبر ثم يهوي ويكبر أثناء الرأس يكبر، وليس كما يفعل الكثير من أنه يكبر إذا استتم قائماً، بل هو يكبر حين يرفع رأسه من السجود أي قبل جلسة الاستراحة، فيكبر أثناء القيام وليس وهو جالس بعد التشهد الأوسط كما يفعل أكثر الإخوة أنه يكبر وهو جالس. ولكن الحديث صريح في أنه يكبر حين يقوم كما ذكرنا، فهو يكبر حين يهوي أي أثناء النزول، ويكبر حين يرفع، (كبر ثم سجد) هذا تفسير. لذا (كبر ثم سجد) هذا هو تفسيرها أنه كبر ثم شرع في السجود وليس كبر ثم شرع في الركوع، فقد كبر وهو يقوم فهو كبر ثم استتم قائماً، فالروايات التي فيها (ثم) ليست مخالفة للروايات التي فيها (حين) بل هي تفسير لها، وهذا أفضل مما يحدثه التكبير قبل الحركة في صلاة الجماعة من مساواة المأمومين بالإمام وخصوصاً المأمومين الذين لا يرون الإمام؛ فإنهم سوف يساوونه لأن المأموم سوف يبدأ ينحني مع سماع صوت الإمام وسيترتب على ذلك أن يساويه في الحركة غالباً؛ ولا كما يفعل كثير من الناس فبعض الناس يربطها بمكان [الميكروفون] فلو كان في الأرض، فلا يقول [الله أكبر] إلا عندما يصل إلى الأرض، وهذا عند الإمام أحمد في وجه أنه لو فعله عامداً فالصلاة باطلة لأن عنده أنه لابد وأن يقارن ولو حرف في التكبير الحركة نفسها، فهي تسمى تكبيرات الانتقال، فلو أن الانتقال كله خلا من التكبير، فيكون قد ترك هذا الواجب عامداً، ولكن الصحيح عدم بطلان الصلاة لأنه على الأقل متأول أو جاهل؛ ولذا فالصحيح أن يقول أثناء الانتقال، فلا ينتظر حتى يتم الحركة، فكثير من الأئمة حتى لا يسبقه الناس، فلا يكبر حتى تصل جبهته إلى الأرض، فتكون قد فاتته السنة في موضع التكبير لأن موضع التكبير كما قلنا (يقول سمع الله لمن حمده حين يرفع صلبه من الركوع) ثم (يكبر حين يهوي ساجداً) (ثم يكبر حين يرفع رأسه) ولذا فالسنة أنه يكبر حين يفعل ذلك. وأما «بسطه عليها»: هذه ليس عليها دليل ومعناها: أن الحركة من أولها إلى آخرها يكون فيها تكبير حتى يأتي فيها السجود وهو سيفسر ذلك، ولكن الحديث قال أنه يكبر حين يفعل ذلك ولا يلزم أن يبسط عليها التكبير. وقد صحح قبل ذلك أن التكبير ليس فيه مد بل مد طبيعي فهو ليس موضع مد، فمن أين أتى أنه يكبر في السجود تكبيراً ممدوداً يحتاج إلى أكثر من ست حركات لكي يبسط التكبير على السجود وخصوصاً إذا كان إنسان يشق عليه السجود كمن يجد وجع في قدمه فيأخذ وقتاً لكي يسجد فهذا ربما يحتاج إلى أكثر من ست حركات، فكونه يكلف بمد التكبير فهذا لا دليل عليه. تقول بل يكبر أثناء الانتقال في أي جزء من أجزائها حين يفعل هذه الحركة والله أعلم. وهو الاقتران وليس البسط، وهو الاقتران بين الفعل والقول.`,
        f: [] },
      { q: `هل يجمع المأموم والمنفرد بين «سمع الله لمن حمده» و«ربنا لك الحمد»؟`, p: `54–55`,
        n: `وفي هذا الحديث دلالة لمذهب الشافعي ﷺ وطائفة أنه يُستحب لكل مصلٍّ من إمام ومأموم ومنفرد أن يجمع بين سمع الله لمن حمده وربنا لك الحمد فيقول: سمع الله لمن حمده في حال ارتفاعه، وربنا لك الحمد في حال استوائه وانتصابه في الاعتدال؛ لأنه ثبت أن رسول الله ﷺ فعلهما جميعًا، وقال ﷺ: «صلّوا كما رأيتموني أصلّي» وسيأتي بسط الكلام في هذه المسألة وفروعها وشرح ألفاظها ومعانيها حيث ذكر مسلم رحمه الله تعالى بعد هذا إن شاء الله تعالى.`,
        o: `مسألة المأموم فيها منازعة (سيأتي تفصيلها).`,
        s: `حيث أنه كان إماماً أو منفرداً ﷺ ولم يثبت أنه صلى مأموماً وفعلها، فنحن موافقون على أن ذلك لكل مصل من إمام أو منفرد أما مأموم ففيها منازعة وسيأتي تفصيل ذلك. إلا ما استثناه الدليل وقد استثناه قوله ﷺ: (وَإِذَا قَالَ سَمِعَ اللَّهُ لِمَنْ حَمِدَهُ. فَقُولُوا اللَّهُمَّ رَبَّنَا لَكَ الْحَمْدُ.).`,
        f: [] },
      { q: `رفع اليدين عند القيام من التشهد الأول: متى يكون؟ (وما نقله ابن حجر من الاتفاق)`, p: `55`,
        n: `قوله: (لقد ذكّرني هذا صلاة محمد ﷺ) فيه إشارة إلى ما قدمناه أنه كان هجر استعمال التكبير في الانتقالات. والله أعلم.`,
        o: `نقل ابن حجر الاتفاق على أنه إذا استتم قائمًا لم يشرع له رفع اليدين.`,
        s: `هناك أيضاً مسألة يحدث فيها خلط وهي: أن كثيراً من الناس لا يرفع يده في القيام من الثنتين إلا إذا وقف واستتم قائماً، مع أن ابن حجر نقل الاتفاق على أنه إذا استتم قائماً لم يشرع له رفع اليدين، فيكون ميعاد رفع اليدين قد فات، رغم وجود خلاف في التكبير ومع ذلك قالوا بعدم رفع اليدين إذا استوى قائماً، فأصبح لا يقول أحد برفع اليدين إذا استوى قائماً، وإنما يرفع يديه حين يقوم مع التكبير والله أعلم. فهذه الصورة التي نقل الاتفاق فيها ابن حجر لم ترد عن النبي ﷺ، فبعد أن يبدأ يقوم سواء معتمداً على يديه أو ركبتيه وبعد أن يرفع يديه من الأرض وركبته ترتفع من الأرض فيقوم برفع يديه قبل أن يستتم قائماً ويقول الله أكبر وهو يقوم (حين يقوم من الثنتين).`,
        f: [`(ص54) «الاقتران بين الفعل والقول»: وهو الاقتران وليس البسط.`] },
    ],
  },
  {
    title: `باب وجوب قراءة الفاتحة في كل ركعة وأنه إذا لم يحسن الفاتحة ولا أمكنه تعلمها قرأ ما تيسر له من غيرها (ص56–99)`,
    items: [
      { q: `حكم قراءة الفاتحة في الصلاة: هل هي ركن؟ ومعنى النفي في «لا صلاة لمن لم يقرأ بفاتحة الكتاب» (وقول أبي حنيفة: آية من القرآن)`, p: `60`,
        n: `وأما الأحكام: ففيه وجوب قراءة الفاتحة وأنها متعينة لا يجزي غيرها إلا لعاجز عنها، وهذا مذهب مالك والشافعي وجمهور العلماء من الصحابة والتابعين فمن بعدهم. وقال أبو حنيفة ﷺ وطائفة قليلة: لا تجب الفاتحة بل الواجب آية من القرآن لقوله ﷺ: «اقرأ ما تيسر». ودليل الجمهور قوله ﷺ: «لا صلاة إلا بأم القرآن». فإن قالوا: المراد لا صلاة كاملة، قلنا هذا خلاف ظاهر اللفظ، ومما يؤيده حديث أبي هريرة ﷺ قال: قال رسول الله ﷺ: «لا يجزئ صلاة لا يُقرأ فيها بفاتحة الكتاب» رواه أبو بكر بن خزيمة في صحيحه بإسناد صحيح، وكذا رواه أبو حاتم بن حبان. وأما حديث «اقرأ ما تيسر» فمحمول على الفاتحة فإنها متيسرة، أو على ما زاد على الفاتحة بعدها، أو على من عجز عن الفاتحة.`,
        o: `أبو حنيفة وطائفة قليلة: لا تجب الفاتحة بل الواجب آية من القرآن.`,
        s: `لأن ظاهر اللفظ إذا لم يمكن حمل الكلام على الحقيقة الكاملة لأن الرجل صلى ولكن لم يقرأ الفاتحة، فهناك صلاة فلا يمكن نفي الذات فيحمل على أقرب نفي له وهو نفي الحقيقة الشرعية، فنقول لا صلاة شرعية، وهذا هو الصحيح الذي لا شك فيه، وأن النفي هنا ليس لنفي الكمال بل لنفي الصحة، لأن النفي إذا لم يمكن توجيهه إلى نفي الذات حُمل على أقرب المجازات إليه وهو نفي الصحة أو نقول نفي الحقيقة الشرعية وهذا أحسن وهو حمله على ظاهره بأنه (ليس هناك صلاة شرعية). وهذا لفظ صريح في عدم الإجزاء (يعني حديث أبي هريرة «لا يجزئ صلاة»).`,
        f: [`(ص59) سُميت الفاتحة «أم القرآن»: ومعنى آخر أظهر: فإنها سُميت أم القرآن لأن معاني القرآن جُمعت فيها من [التوحيد والإيمان بالنبوة والبعث والقيامة والولاء والبراء والقدر وأصول الإيمان كلها التي يدور عليها معاني القرآن كلها] جمعت في الفاتحة ولذلك سميت أيضاً بالقرآن العظيم قال الله ﷻ: (وَلَقَدْ آتَيْنَاكَ سَبْعًا مِّنَ الْمَثَانِي وَالْقُرْآنَ الْعَظِيمَ) قال ﷺ هي فاتحة الكتاب فعَنْ أَبِي هُرَيْرَةَ ﷺ قَالَ: قَالَ رَسُولُ اللَّهِ ﷺ: «أُمُّ الْقُرْآنِ هِيَ السَّبْعُ الْمَثَانِي وَالْقُرْآنُ الْعَظِيمُ». البخاري.`, `(ص59) لم يذكر النووي فائدة ذكر (محمود بن الربيع) في المتن: [مَحْمُودَ بْنَ الرَّبِيعِ الَّذِي مَجَّ رَسُولُ اللَّهِ ﷺ فِي وَجْهِهِ مِنْ بِئْرِهِمْ أَخْبَرَهُ أَنَّ عُبَادَةَ بْنَ الصَّامِتِ أَخْبَرَهُ] فثبتت بذلك صحبته ﷺ، وهو دليل على أنه عقل هذا الفعل تبركاً بالنبي ﷺ فقد بخ في وجهه بعض الماء، وهذه من رواية الصحابة بعضهم عن بعض، فإن مَحْمُودَ بْنَ الرَّبِيعِ من صغار الصحابة ﷺ.`, `(ص60) رواية ابن حبان في حديث المسيء صلاته صرح بفاتحة الكتاب: «... إِذَا قُمْتَ فَتَوَجَّهْتَ إِلَى الْقِبْلَةِ فَكَبِّرْ ثُمَّ اقْرَأْ بِأُمِّ الْقُرْآنِ ثُمَّ اقْرَأْ بِمَا شِئْتَ...» (حب ١٧٨٧، وقال الألباني: حسن صحيح، الإرواء ١/ ٣٢١ – ٣٢٢، صحيح أبي داود ٧٤٧). (وفي ص61–64 جمع الشيخ/المحقق روايات حديث المسيء صلاته من الجامع الصحيح للسنن والمسانيد مع تخريجها وشرح ألفاظها من عون المعبود وتحفة الأحوذي.)`] },
      { q: `الجواب عن حديث «اقرأ ما تيسر» عند من لا يوجب الفاتحة: على أي شيء يُحمل؟ (وهل الزيادة على الفاتحة واجبة؟)`, p: `60–61`,
        n: `وأما حديث (اقرأ ما تيسر) فمحمول على الفاتحة فإنها متيسرة، أو على ما زاد على الفاتحة بعدها، أو على من عجز عن الفاتحة.`,
        o: NO_O,
        s: `وهذا يدل على أنها المقصودة بما تيسر لسهولة حفظها وكثرة من يحفظها من المسلمين. ولكن لو حُمل على هذا المحمل [ما زاد على الفاتحة] فسيصبح دليلاً على وجوب الزيادة، والصحيح عدم وجوب الزيادة: فمفهوم (مَنْ صَلَّى صَلاَةً لَمْ يَقْرَأْ فِيهَا بِأُمِّ الْقُرْآنِ فَهِيَ خِدَاجٌ) أنه إذا قرأ فيها بأم القرآن فليست خداج فهي تامة وتكون الصلاة صحيحة، ويكون قول النبي ﷺ: «لاَ صَلاَةَ لِمَنْ لَمْ يَقْرَأْ بِأُمِّ الْقُرْآنِ فَصَاعِداً» فتكون «فصاعداً» زيادة على أم الكتاب، وقول أبو هريرة: (فَقَالَ لَهُ رَجُلٌ إِنْ لَمْ أَزِدْ عَلَى أُمِّ الْقُرْآنِ فَقَالَ إِنْ زِدْتَ عَلَيْهَا فَهُوَ خَيْرٌ وَإِنِ انْتَهَيْتَ إِلَيْهَا أَجْزَأَتْ عَنْكَ.)؛ فالصحيح أن قوله [يحمل على ما زاد] ليس بظاهر. وحمله على من عجز عن الفاتحة هذا صحيح من جهة المعنى (أنه يقرأ ما تيسر إذا لم يتيسر له الفاتحة)، ولكن أحسن الوجوه والصحيح أن حديث: (ثم اقرأ بما تيسر معك من القرآن) المقصود به الفاتحة.`,
        f: [] },
      { q: `قراءة الفاتحة للمأموم: هل «اقرأ بها في نفسك» تدل على قراءة السر؟ وهل يُكتفى بتدبر القلب؟`, p: `65`,
        n: `وقوله ﷺ: (لا صلاة لمن لم يقرأ بفاتحة الكتاب) فيه دليل لمذهب الشافعي رحمه الله تعالى ومن وافقه أن قراءة الفاتحة واجبة على الإمام والمأموم والمنفرد، ومما يؤيد وجوبها على المأموم قول أبي هريرة: (اقرأ بها في نفسك) فمعناه اقرأها سرًّا بحيث تُسمع نفسك، وأما ما حمله عليه بعض المالكية وغيرهم أن المراد تدبُّر ذلك وتذكُّره فلا يُقبل لأن القراءة لا تُطلق إلا على حركة اللسان بحيث يُسمع نفسه، ولهذا اتفقوا على أن الجنب لو تدبّر القرآن بقلبه من غير حركة لسانه لا يكون قارئًا مرتكبًا لقراءة الجنب المحرَّمة.`,
        o: `بعض المالكية وغيرهم: المراد تدبر ذلك وتذكره بالقلب.`,
        s: `(اللسان) وبالتأكيد الشفتين وخروج نفس ولذا تسمى (مخارج الحروف) فلابد أن يكون أثناء النطق هناك هواء يخرج من فمه أثناء القراءة ولا يكتفي بالوقوف متدبراً الآيات بدون أن يقرأها، فإذا فعل ذلك كانت الصلاة باطلة، وكثير من الناس تفعل ذلك وكذلك في التسبيح والتكبير، فيظل سنوات يصلي صلاة باطلة لاعتقاده أنه يكفي في القراءة إمرار الآية على قلبه أو يمر التكبير أو الذكر على قلبه، ولكن لابد أن يحرك بها لسانه وكما قلنا بحيث يسمع نفسه. (أي عند الجمهور) ولكن الصحيح أن قراءة الجنب ليست محرمة لأنه لم يدل عليها دليل.`,
        f: [] },
      { q: `وجوب الفاتحة في كل ركعة، وحكم القراءة في الركعتين الأخيرتين، ومن قال لا تجب قراءة أصلًا`, p: `65–66`,
        n: `وحكى القاضي عياض عن علي بن أبي طالب ﷺ، وربيعة ومحمد بن أبي صفرة من أصحاب مالك أنه لا تجب قراءة أصلًا وهي رواية شاذة عن مالك، وقال الثوري والأوزاعي وأبو حنيفة ﷺ: لا تجب القراءة في الركعتين الأخيرتين بل هو بالخيار إن شاء قرأ، وإن شاء سبّح، وإن شاء سكت، والصحيح الذي عليه جمهور العلماء من السلف والخلف وجوب الفاتحة في كل ركعة لقوله ﷺ للأعرابي «ثم افعل ذلك في صلاتك كلها».`,
        o: `علي وربيعة وبعض أصحاب مالك (رواية شاذة): لا تجب قراءة أصلًا. الثوري والأوزاعي وأبو حنيفة: لا تجب في الأخيرتين بل هو مخير (قرأ أو سبّح أو سكت).`,
        s: `(أي لا مأموم ولا إمام ولا منفرد فيقف ويركع ويسجد دون قراءة ولا ذكر، بخلاف مذهب أبي حنيفة فإنه يجزئ آية من القرآن.)`,
        f: [`(ص66) مذاهب العلماء في القراءة خلف الإمام: فالإمام الشافعي مذهبه أن الفاتحة واجبة على الإمام والمأموم والمنفرد. أما مذاهب العلماء الآخرين في مسألة عدم وجوب القراءة مطلقاً أو وجوب غير الفاتحة: أما بالنسبة للقراءة خلف الإمام اختلف العلماء على مذاهب: منهم من قال (لا يجوز القراءة خلف الإمام في السرية ولا في الجهرية) وهو قول أبي حنيفة رحمه الله. وقول مالك وأحمد (يجب على المأموم قراءة الفاتحة في السرية دون الجهرية). وقول الشافعي رحمه الله: (يجب قراءة المأموم للفاتحة في السرية والجهرية) وهو الصحيح، فعَنْ عُبَادَةَ بْنِ الصَّامِتِ: «صَلَّى رَسُولُ اللَّهِ ﷺ الصُّبْحَ فَثَقُلَتْ عَلَيْهِ الْقِرَاءَةُ فَلَمَّا انْصَرَفَ قَالَ: إِنِّي أَرَاكُمْ تَقْرَءُونَ مِنْ وَرَاءِ إِمَامِكُمْ؟ قَالَ: قُلْنَا: أَجَلْ وَاللَّهِ يَا رَسُولَ اللَّهِ، قَالَ: فَلاَ تَفْعَلُوا إِلاَّ بِأُمِّ الْقُرْآنِ فَإِنَّهُ لاَ صَلاَةَ لِمَنْ لَمْ يَقْرَأْ بِهَا». رواه الدارقطني وقال: هذا إسناد حسن. وفي رواية أبي داود ٨٢٤ [قال الألباني]: ضعيف.`] },
      { q: `قراءة المأموم الفاتحة خلف الإمام في الجهرية والسرية: الراجح، ودلالة العموم والسبب في حديث عبادة، وأقوال الصحابة`, p: `66–67`,
        n: NO_N,
        o: `الشافعي: تجب على المأموم في السرية والجهرية. مالك وأحمد: تجب على المأموم في السرية دون الجهرية. أبو حنيفة: لا يجوز للمأموم القراءة خلف الإمام لا في السرية ولا في الجهرية. (ويُحتج بمذهب ابن مسعود وعبد الله بن الزبير أنهما لا يقرآن خلف الإمام.)`,
        s: `هذا الحديث العام ورد على موضع خاص وهو القراءة خلف الإمام وهذا خطاب للصحابة والذين يقولون بأن حديث (مَنْ صَلَّى صَلاَةً لَمْ يَقْرَأْ فِيهَا بِأُمِّ الْقُرْآنِ فَهِيَ خِدَاجٌ) خاص بالإمام والمنفرد فبعيد لأن أكثر الصلوات المفروضة إنما تكون للمأمومين، والإمام هنا هو النبي ﷺ وحده، والكلام هنا على الصلاة المفروضة في المقام الأول، والأولى أنه يتكلم عن الواجبات وتركها يبطل الصلاة، وهو يُعلمهم أولى الأحكام بذلك الصلاة الواجبة، فعامة المسلمين هم مأمومين فكيف يُحمل الحديث على واحد وهو النبي ﷺ؟ ثم إنه كما ذكرنا قد خاطبهم النبي ﷺ في صلاة جهر فيها بالقراءة فقال: «فَلاَ تَفْعَلُوا إِلاَّ بِأُمِّ الْقُرْآنِ ، فَإِنَّهُ لاَ صَلاَةَ لِمَنْ لَمْ يَقْرَأْ بِهَا» فقوله (فلا تفعلوا) أي لا تقرأوا خلفي بالسورة (إلا بأم القرآن) وهذا نص في موطن النزاع، لأن [ورود العام على سبب يجعل ذلك السبب قطعي الدخول في العموم] بمعنى أنه لا يخصص منه لأنه قد ورد من أجله، كما في حديث: (هو الطهور ماؤه الحل ميتته) ورد على سؤال عن ماء البحر فجوابهم بلفظ عام يشمل الوضوء والغسل – من نجاسات وغير ذلك – فقد ورد على الوضوء فلا يمكن بأي حال من الأحوال أن يخرج من العموم لأن لو خُصص منه فما فائدة الجواب لو أمكن التخصيص؛ فهذا الحديث ورد في صلاة المأموم خلف الإمام في صلاة جهرية وهو حديث عبادة ورد في المأموم وفي صلاة جهرية، فمن يقول المأموم لا يقرأ فقد خالف الحديث وخالف عموم الأحاديث فيحملها على غير الأغلب الأعم. فهذا الحديث حمله على ما حمله عليه الحنفية من أن المأموم لا يقرأ نهائياً كلام ضعيف؛ وقول المالكية والحنابلة في مسألة الجهر والسر غير ظاهر لما ذكرنا من حديث عبادة بن الصامت الذي رواه الدارقطني بإسناد صحيح وقال رجاله كلهم ثقات، فإنه كما ذكرنا ورد على المأموم ويؤيده الآثار عن الصحابة، فأبو هريرة صريح في أنه قال بعد قوله ﷺ: [مَنْ صَلَّى صَلاَةً لَمْ يَقْرَأْ فِيهَا بِأُمِّ الْقُرْآنِ فَهِيَ خِدَاجٌ – ثَلاَثًا – غَيْرُ تَمَامٍ]. فَقِيلَ لأَبِي هُرَيْرَةَ إِنَّا نَكُونُ وَرَاءَ الإِمَامِ. فَقَالَ اقْرَأْ بِهَا فِي نَفْسِكَ] أي في سرك فقال: (اقرأ بها) إذاً فقد أمر بالقراءة خلف الإمام، وكذا عبادة بن الصامت ﷺ يرى القراءة خلف الإمام، وهو قول عمر ﷺ فعَنْ يَزِيدَ بْنِ شَرِيكٍ، قَالَ: سَأَلْتُ عُمَرَ بْنَ الْخَطَّابِ: أَقْرَأُ خَلْفَ الإِمَامِ قَالَ: نَعَمْ، قُلْتُ: وَإِنْ قَرَأْتَ يَا أَمِيرَ الْمُؤْمِنِينَ قَالَ: وَإِنْ قَرَأْتُ، فهذا مذهب عمر ﷺ لأنه سوف يحتج البعض بمذهب ابن مسعود وعبد الله ابن الزبير أنهم لا يقرأون خلف الإمام، فهذا قول ابن مسعود ﷺ وهو قول عمر وأعلم منه عمر ﷺ، وإذا كان عبد الله ابن الزبير لا يرى القراءة خلف الإمام هو وابن مسعود وغيرهم من الصحابة فهي مسألة مشهورة والصحيح أنه قد ثبت النص بذلك وقال به طوائف من الصحابة ويكفي قول عمر ﷺ وهو قول عائشة رضي الله عنها كما رواه عبد الرزاق بإسناد صحيح، وهو قول عبد الله ابن عمرو بن العاص وجماعات من الصحابة، وبذلك فالمأموم يقرأ بفاتحة الكتاب خلف الإمام في الجهرية.`,
        f: [] },
      { q: `متى يقرأ المأموم الفاتحة في الجهرية؟ (وجواب إلزام ابن تيمية بالسكتة، ومعنى «وإذا قرئ القرآن فاستمعوا»)`, p: `67–68`,
        n: NO_N,
        o: `ابن تيمية: لا يثبت وجود سكتة مشروعة ولا واجبة، فبنى مذهبه على عدم وجوب القراءة في الجهرية (وقوله تعالى: ﴿وَإِذَا قُرِئَ الْقُرْآنُ فَاسْتَمِعُوا لَهُ وَأَنصِتُوا﴾، وحديث «مَنْ كَانَ لَهُ إِمَامٌ فَقِرَاءَةُ الإِمَامِ لَهُ قِرَاءَةٌ»).`,
        s: `متى يقرأ المأموم؟ يقرأ على ظاهر حديث عبادة بن الصامت أنه مع الإمام بأن قال ﷺ: «ألا أراكم تقرؤون مع إمامكم؟ فنوزع فعلاً» لما وجدهم يقرأون معه بالسورة، وقال: «إني أقول: ما لي أنازع؟!» وقال: «قد علمت أن بعضكم خالجنيها». وهذه المخالجة سوف لا تحدث إلا عندما يقرأ مع قراءته، فقال لهم في حديث عبادة: (فَلاَ تَفْعَلُوا إِلاَّ بِأُمِّ الْقُرْآنِ) فهو سوف لا ينازع الإمام بأن يقرأ بها بصوت ولكن يقرأ بها في نفسه ولكن مع قراءة الإمام وهو يقول الحمد. وهذا المخرج الذي شيخ الإسلام ابن تيمية يلزم من يقول بالقراءة خلف الإمام أن لا مخرج منه إلا أن يقول بالسكت، بل سوف لا نقول بالسكتة ولا نقول بمشروعية السكتة الطويلة. فيقول ابن تيمية إذاً متى يقرأ؟ لأنه لا يوجد سكتة مشروعة، وقد بنى شيخ الإسلام ابن تيمية مذهبه على عدم وجوب القراءة في الجهرية على أنه لا يثبت وجود سكتة طويلة لا مشروعة ولا واجبة، فمتى يقرأ المأموم؟ فيقول لا يقرأ {وَإِذَا قُرِئَ الْقُرْآنُ فَاسْتَمِعُوا لَهُ وَأَنصِتُوا} ونقول: عام وقراءة الفاتحة خاصة، وكذلك حديث: «مَنْ كَانَ لَهُ إِمَامٌ فَقِرَاءَةُ الإِمَامِ لَهُ قِرَاءَةٌ» عام وقراءة الفاتحة خاص فيكون هذا محمولاً على ما سوى الفاتحة، ثم إن القراءة مع القراءة في الفاتحة لا تنافي الإنصات بل تعين على التدبر فإنه يقرأ نفس الكلمات بعينها أثناء قراءة الإمام والله أعلى وأعلم. كما قال أبو هريرة ﷺ: (اقرأ بها في نفسك) وذلك خلف الإمام ولو كان مسبوقاً والإمام قد دخل في السورة فليقرأ بفاتحة الكتاب أيضاً حتى ولو كان الإمام قد سبقه في شيء من القراءة.`,
        f: [] },
      { q: `من أدرك الإمام راكعًا: هل تُحسب له الركعة؟ (حديث أبي بكرة، وحديث «من أدرك الركوع فقد أدرك الركعة»، ومذهب البخاري)`, p: `68–69`,
        n: NO_N,
        o: `الجمهور والأئمة الأربعة: من أدرك الركوع فقد أدرك الركعة. الإمام البخاري ومذهب ابن خزيمة والضبعي وطوائف من محدثي الشافعية والظاهرية: لا تُحسب إذا لم يقرأ الفاتحة (وهو قول أبي هريرة وجماعة، واختاره السبكي من المتأخرين). عبد الله بن الزبير وابن مسعود وغيرهما: الاعتداد بالركوع دون الصف، وهم الذين يرون سقوط الفاتحة عن المسبوق.`,
        s: `الإمام البخاري ومذهب ابن خزيمة من أهل الحديث ومذهب الظاهرية خلافاً للجمهور القائلين والأئمة الأربعة منهم بأن من أدرك الركوع فقد أدرك الركعة، والصحيح في هذه المسألة ما ذهب إليه أبو هريرة ﷺ. وإنما يدركه قائماً ليقرأ الفاتحة كما قالت عائشة رضي الله عنها عنها: (لا تركع قبل أن تقرأ بفاتحة الكتاب)، ويدخل في عموم [من صلى صلاة لم يقرأ فيها بفاتحة الكتاب فهي خداج]، و(من صلاة) والركعة تسمى صلاة، فقد دخلت هذه الركعة من المسبوق الذي أدرك الركوع في عموم (لا صلاة) فهي نكرة في سياق النفي، فكل صلاة وكل ركعة – فما زاد – ليس فيها فاتحة الكتاب فهي ليست بصلاة صحيحة، وهذه ركعة ليس فيها فاتحة للمسبوق الذي أدرك الإمام راكعاً، فهي داخلة في العموم، وقد قال البخاري: [وهو مذهب كل من يقول بوجوب القراءة خلف الإمام]. وأما حديث: [من أدرك الركوع فقد أدرك الركعة] فهو حديث ضعيف مرسل عن رجل من التابعين مجهول والشيخ الألباني إنما حسنه بالآثار الموقوفة عن الصحابة، فنقول: إنها هي موقوفة على من يقول بعدم وجوب القراءة خلف الإمام خاصة أثر عبد الله بن الزبير الذي يصحح أن السنة أن يدب راكعاً دون الصف ثم يمشي إلى الصف وهذا خلاف ما نص عليه النبي ﷺ حيث قال لأبي بكرة لما انتهى إلى النبي ﷺ وهو راكع فركع قبل أن يصل إلى الصف فذكر ذلك للنبي ﷺ فقال: [زَادَكَ اللَّهُ حِرْصًا، وَلاَ تَعُدْ] البخاري. وعَنْ سَعْدِ بْنِ أَبِي وَقَّاصٍ ﷺ قَالَ: قَالَ رَسُولُ اللَّهِ ﷺ: " إِذَا أَتَيْتَ الصَّلاَةَ فَأْتِهَا بِوَقَارٍ وَسَكِينَةٍ، فَصَلِّ مَا أَدْرَكْتَ، وَاقْضِ مَا فَاتَكَ " ((طس) ١٣٣٥ ، انظر صحيح الجامع: ٢٧٢ ، الصحيحة: ١١٩٨) [وَقَالَ أَبُو قَتَادَةَ وَأَنَسٌ وَأَبُو هُرَيْرَةَ ﷺ، عَنِ النَّبِيِّ ﷺ: «إِذَا أُقِيمَتِ الصَّلاَةُ فَمَا أَدْرَكْتُمْ، فَصَلُّوا وَمَا فَاتَكُمْ فَأَتِمُّوا» فَمَنْ فَاتَهُ فَرْضُ القِرَاءَةِ وَالقِيَامِ فَعَلَيْهِ إِتْمَامُهُ كَمَا أَمَرَ النَّبِيُّ ﷺ]. وعَنْ أَبِي بَكْرَةَ ﷺ أَنَّ النَّبِيَّ ﷺ صَلَّى صَلاَةَ الصُّبْحِ فَسَمِعَ نَفَسًا شَدِيدًا أَوْ بَهَرًا مِنْ خَلْفِهِ، فَلَمَّا قَضَى رَسُولُ اللَّهِ ﷺ قَالَ لأَبِي بَكْرَةَ: «أَنْتَ صَاحِبُ هَذَا النَّفَسِ؟» قَالَ: نَعَمْ، جَعَلَنِي اللَّهُ فِدَاكَ، خَشِيتُ أَنْ تَفُوتَنِي رَكْعَةٌ مَعَكَ فَأَسْرَعْتُ الْمَشْيَ، فَقَالَ رَسُولُ اللَّهِ ﷺ: «زَادَكَ اللَّهُ حِرْصًا وَلاَ تَعُدْ صَلِّ مَا أَدْرَكْتَ وَاقْضِ مَا سَبَقَ» القراءة خلف الإمام للبخاري. فأمره بالقضاء، فإذا كان لم يسبقه شيء، ما كان يأمره بالقضاء، فأمره بالقضاء بعد أن ركع معه ظانّاً أنه لم تفته الركعة أو يكون مقصود أبي بكرة (خَشِيتُ أَنْ تَفُوتَنِي رَكْعَةٌ مَعَكَ) أي الركوع معك فهو شديد الحرص على أن يدرك كل جزء من الصلاة مع النبي ﷺ، وقد نهاه النبي ﷺ عن أن يعود، فليس لأحد أن يعود إلى شيء فعل خلاف نسك الصلاة المعتاد وقع في حديث أبي بكرة فهو يشمل كل ما ذُكر من احتمالات من أنه – مثل بنفسه في مشيه راكعاً لأنها كمشية البهائم – من أنه قد ركع ابتداءً ومن أنه ركع دون الصف ومن أنه احتسبها ركعة، فإذا قيل: لماذا لم يأمره بالإعادة؟ نقول قد أمره بالإعادة: "صَلِّ مَا أَدْرَكْتَ وَاقْضِ مَا سَبَقَ" من الذي يستطيع أن ينقل أن أبي بكرة لم يأت بالركعة ولم يقضيها بعد ما أمره النبي ﷺ؟! ويمكن أن يقال: (لم يأمره بالقضاء لأنه كان مجتهداً ومن تغير اجتهاده لم يؤمر بإعادة ما مضى من صلاته؛ [ووقائع الأحوال إذا تطرق إليها الاحتمال سقط بها الاستدلال ولم يبق فيها إلا الإجمال])، فنتمسك بعموم قوله ﷺ: (لا صلاة لمن لا يقرأ بفاتحة الكتاب) فهذه صلاة فكيف تُحسب صلاة وليس فيها فاتحة الكتاب، وعموم (صَلِّ مَا أَدْرَكْتَ وَاقْضِ مَا سَبَقَكَ) فقد فاته القيام وهو ركن وقد فاته قراءة الفاتحة وهي ركن كما في حديث المسيء صلاته. والمسألة فيها اجتهاد فالأئمة الأربعة فصلاته التي مضت صحيحة لأنه المجتهد إذا تغير اجتهاده لم يؤمر بالإعادة، وكذا من يقلد مجتهداً اجتهاداً سائغاً فلم يزل الخلاف فيها قديماً من عصر الصحابة والخلاف موجود حتى مسألة القراءة خلف الإمام؛ فهناك من الصحابة كابن مسعود ﷺ لا يقول بالقراءة خلف الإمام، فالمسألة خلاف سائغ فهي مسألة اجتهادية بها فيها مسألة القراءة خلف الإمام ولا إنكار فيها على المخالف، فلا ينكر هذا على هذا ولا ينكر هذا على هذا.`,
        f: [`(ص68–69) [استدراك: قال الحافظ في الفتح: واستدل به على أن من أدرك الإمام راكعاً لم تحسب له تلك الركعة لأنه فاته الوقوف والقراءة فيه وهو قول أبي هريرة وجماعة بل حكاه البخاري في القراءة خلف الإمام عن كل من ذهب إلى وجوب القراءة خلف الإمام واختاره ابن خزيمة والضبعي وغيرهما من محدثي الشافعية وقواه الشيخ تقي الدين السبكي من المتأخرين. والله أعلم.]`, `(ص69–80) بعد ذلك فصل بعنوان «استدراك: باب وجوب القراءة للإمام والمأموم وأدنى ما يجزي من القراءة» وفيه نقول متصلة عن البخاري (كتاب القراءة خلف الإمام) مع الأدلة والمناظرة بين القائلين بوجوب القراءة والقائلين بالإنصات، وهي نقول من كتب وليست من كلام الشيخ، فلم تُلخَّص إلا تعقيباته أدناه.`] },
      { q: `تعقيب الشيخ على الشيخ الألباني في دعوى نسخ القراءة خلف الإمام في الجهرية بحديث «فانتهى الناس عن القراءة»، وهل عدم الوجوب في الجهرية قول الجمهور؟`, p: `80–81`,
        n: NO_N,
        o: `الألباني (صفة الصلاة): نُسخت القراءة وراء الإمام في الجهرية بحديث «فانتهى الناس عن القراءة» (من قول أبي هريرة أو الزهري)، وأن «ثم نهاهم ﷺ عن القراءة كلها في الجهرية». الجمهور (أبو حنيفة ومالك وأحمد): عدم وجوب القراءة خلف الإمام في الجهرية. البخاري: لا تُحسب الركعة حتى يقرأ فيها بفاتحة الكتاب.`,
        s: `هذا الكلام من الشيخ الألباني فيما أعلم لم يُسبق إليه، أولاً هو صحح الحديث وهو حديث الدارقطني وهو حديث عبادة وذكره البخاري في [جزء القراءة] وحسنه الترمذي وقد احتج به وهو حديث: (لا تفعلوا؛ إلا [أن يقرأ أحدكم] بـ: {فاتحة الكتاب}؛ فإنه لا صلاة لمن لم يقرأ بها) وهو نص كما ذكرنا في موطن النزاع. فالمشكلة أن الشيخ الألباني قد أتى بأشياء من عنده وأدخلها بين الروايتين وهي كلمة [ثم نهاهم ﷺ عن القراءة كلها في الجهرية] فالحديث ليس فيه ذلك، فإن حديث أبي هريرة ﷺ موافق لحديث عبادة بن الصامت ﷺ، ولا يوجد تاريخ ثابت لا في هذا الحديث ولا في هذا حديث، فلجأ الشيخ إلى النسخ وهو قول كما ذكرت لم يسبق إليه من أحد صحح حديث عبادة بن الصامت وصححه الدارقطني وصححه البخاري واحتج به في جزء القراءة على وجوب القراءة خلف الإمام وعلى عدم إدراك الركعة إلا بالفاتحة، وحسنه الترمذي كما ذكرنا وقد ذكره الشيخ صحيحاً له؛ فنقول: الجمع مقدم على الترجيح والجمع هو الظاهر أصلاً لأن النسخ هو من مسألة الترجيح والنسخ لا يُلجأ إليه إلا مع عدم إمكان الجمع والجمع ممكن لإمكان حمل (فانتهى الناس عن القراءة) أي عن قراءة السورة، فعَنْ عِمْرَانَ بْنِ حُصَيْنٍ قَالَ صَلَّى بِنَا رَسُولُ اللَّهِ ﷺ صَلاَةَ الظُّهْرِ – أَوِ الْعَصْرِ – فَقَالَ: «أَيُّكُمْ قَرَأَ خَلْفِى بِسَبِّحِ اسْمَ رَبِّكَ الأَعْلَى». فَقَالَ رَجُلٌ: أَنَا وَلَمْ أُرِدْ بِهَا إِلاَّ الْخَيْرَ. قَالَ: «قَدْ عَلِمْتُ أَنَّ بَعْضَكُمْ خَالَجَنِيهَا». أي السورة، ويؤيد هذا أن أبا هريرة ﷺ بعد وفاة النبي ﷺ يفتي ويقول (اقرأ بها في نفسك) فإذا كان أبو هريرة يفتي بذلك ويقول: (لا يجزيك إلا أن تقرأ بفاتحة الكتاب) فكيف يُحمل كلامه (فانتهى الناس عن القراءة) أي على قراءة الفاتحة حتى يقول الألباني: [نَسْخُ القراءة وراءَ الإمام في الجهرية] بالفاتحة، فإن أبا هريرة نفسه الذي يقول: (فانتهى الناس عن القراءة) الذي هو خبره إن صح أنه أبو هريرة لوجود نزاع طويل في هذه المسألة وأن القائل (فانتهى الناس عن القراءة) هو الزهري، بل على فرض أن أبا هريرة هو القائل فكيف تحمل قول أبو هريرة على خلاف قوله لأنه قال: (فانتهى الناس عن القراءة) وهو الذي قال – في الفاتحة – [اقْرَأْ بِهَا فِي نَفْسِكَ] ومن هنا فتحمل (فانتهى الناس عن القراءة) على قراءة السورة، وهذا عام ولفظ عام وقراءة الفاتحة خاصة ولا يوجد عندنا تاريخ ويمكن الجمع فكيف نلجأ إلى النسخ؟ فإنه يلجأ إلى النسخ في حالة عدم إمكان الجمع ومع العلم بالتاريخ؛ فنتيجة أن الشيخ الألباني يربط بين الأحاديث أحياناً بألفاظ خارجة عن لفظ الحديث ويجعلها روايات كأن هذه رواية حصلت بعد هذه ولا يوجد تاريخ عنده، فكلمة (ثم نهاهم) ليست ثابتة، وحديث أبي هريرة محمول على قراءة السورة وليس قراءة الفاتحة فهو موافق لحديث عبادة بن الصامت وليس مخالفاً له حتى يُحمل على النسخ. هذه المسألة [القراءة خلف الإمام] وهذا هو المذهب الصحيح فيها إن شاء الله تبارك وتعالى، وسبق أن ذكرنا حديث أبي بكرة لأنها واقعة عين محتملة، فأحسن وجوه الاحتمال فيها أن النبي ﷺ أمره بالقضاء حيث قال: (زَادَكَ اللَّهُ حِرْصًا وَلاَ تَعُدْ صَلِّ مَا أَدْرَكْتَ وَاقْضِ مَا سَبَقَ) والله أعلى وأعلم. أما بالنسبة أنه هل هو قول الجمهور أم لا؟ فلا، بل قول الشافعية، وأما قول الجمهور هو عدم وجوب القراءة خلف الإمام في الجهرية فهو قول أبي حنيفة ومالك وأحمد، ولكن السنة مقدمة، ولو قلنا أكثر الصحابة المنقول عنهم وجوب القراءة لكان هو الصواب، الذين رأوا الاعتداد بالركوع دون الصف، الذين رأوا الاعتداد بالركوع هم الذين يرون عدم وجوب القراءة خلف الإمام منهم ابن مسعود ﷺ وعبد الله بن الزبير، ولكن المعروف أنه يقول بوجوب القراءة خلف الإمام وعدم لزوم الفاتحة للمسبوق ومع ذلك يقول بوجوب القراءة خلف الإمام الشافعي رحمه الله، لأن عنده المسبوق يدرك الركعة بالركوع، أما من سبقه من العلماء فالإمام البخاري يقول: قول من يقول بوجوب القراءة خلف الإمام بعدم نفاذات الركعة حتى يقرأ فيها بفاتحة الكتاب.`,
        f: [`(ص80) [(٦) الحاصل: أن طرق الحديث بعضها صحيحة أو حسنة، وبعضها ضعيفة ينجبر ضعفها بغيرها من الطرق الكثيرة، فالقول بأنه حديث غير ثابت أو غير محتج به ونحو ذلك غير معتد به. وللحديث شواهد كثيرة عن ابن عمر، وأبي سعيد، وأبي هريرة، وابن عباس، وأنس، أخرجها الزيلعي في «نصب الراية» (٢/ ١٠ – ١٢) والحافظ ابن حجر في «الدراية» (٩٣).] — هامش منقول من تحقيق الكتاب المنقول، وليس من كلام الشيخ.`] },
      { q: `المسألة فيها اجتهاد: لا يُنكر فيها على المخالف، ومن قرأ الفاتحة ولم يلحق الركوع: متى يركع المأموم؟ (إذا تأخر عن الإمام بعذر بقدر ركنين)`, p: `81`,
        n: NO_N,
        o: `الحنابلة: يُعفى من تأخر عن الإمام لعذر بمقدار ركنين. (الأئمة الأربعة: صلاة من أدرك الإمام راكعًا واحتسبها ركعة تصح اجتهادًا.)`,
        s: `المسألة فيها اجتهاد فالأئمة الأربعة فصلاته التي مضت صحيحة لأن المجتهد إذا تغير اجتهاده لم يؤمر بالإعادة وكذا من يقلد مجتهداً اجتهاداً سائغاً فلم يزل الخلاف فيها قديماً من عصر الصحابة والخلاف موجود حتى مسألة القراءة خلف الإمام؛ فهناك من الصحابة كابن مسعود ﷺ لا يقول بالقراءة خلف الإمام، فالمسألة خلاف سائغ فهي مسألة اجتهادية بها فيها مسألة القراءة خلف الإمام، ولا إنكار فيها على المخالف، فلا ينكر هذا على هذا ولا ينكر هذا على هذا. فالمسألة عندي أن الذي يصحح حديث عبادة بن الصامت ﷺ وهو حديث حسن وهو حديث إسناده رجاله كلهم ثقات، لكن هناك بعض العلماء تكلم فيه والصحيح أنه حديث صحيح وبالتالي الذي يصحح الحديث لا ينبغي أن يقول بخلافه وقد يُلجأ إلى النسخ ولذلك نقول المسألة فيها اجتهاد. فحديث عبادة بن الصامت ﷺ نص في موطن النزاع. فلا تركع حتى تقرأ الفاتحة، ولو تأخر عمداً عن الركوع يكون معذوراً، فيقرأ الفاتحة ويكملها ويركع، وسوف يدرك الركوع لو قرأها هذاً (سرداً)، وهناك وجه آخر أنه يقطع الفاتحة ويركع ولكن الأظهر أنه إذا شرع فيها فليتمها ولو تأخر عن الإمام بقدر ركنين صحت قياساً على ... (نقط ناقصة في التفريغ)، فمن تأخر عن الإمام لعذر بمقدار ركنين فأقل – ولكن هي ثلاثة أركان في الحقيقة وليست أثنين – صحت صلاته، الحنابلة يقولون بمقدار ركنين.`,
        f: [] },
      { q: `معنى «من أدرك الركعة فقد أدرك الصلاة» و«فمن أدرك الركوع فقد أدرك الركعة» (توجيه الحديث)، وهل يصح تقييد الحديث المرسل بآثار موقوفة؟`, p: `82`,
        n: NO_N,
        o: NO_O,
        s: `لا يصح تقييد الحديث المرسل بآثار موقوفة في مسألة اختلف فيها الصحابة ﷺ، وأصل الحديث ثابت وقد صححه البخاري والذي بين أن هذا وجه فيه والذي هو (من أدرك الركعة فقد أدرك الصلاة) فتحمل الركعة على مفهومها الشرعي التي هي الركعة الكاملة والحديث في مسلم: (من أدرك ركعة من الصلاة فقد أدرك الصلاة) فلكي يدرك حكم الصلاة كالظهر مثلاً كمسافر متى يصليها أربعة وذلك إذا أدرك ركعة منها، حكم الإمام تلزم متابعته في الصلاة إذا أدرك منها ركعة، وكأن يدرك من الجمعة التشهد الأخير فقد لزمته ظهراً وإذا أدرك ركعة فقد أدرك الصلاة فيضيف إليها أخرى، وكذا المسافر إذا أدرك الإمام في التشهد الأخير صلى ركعتين وإذا أدركه في الركعة الأخيرة صلى أربعاً، وهكذا المرأة إنما تجب عليها صلاة الظهر والعصر إذا أدركت قدر خمس ركعات [أربع ركعات الظهر وركعة من العصر] وتكمل الثلاثة مع غروب الشمس، وهكذا في سائر الأحكام. (من أدرك الركعة فقد أدرك الصلاة) هذا هو أصل الحديث (فمن أدرك الركوع فقد أدرك الركعة) – توجيه الحديث – فحمل الركعة على الانحناء خلاف الظاهر الشرعي لأنه يصح كظاهر لغوي ولكن الحقيقة الشرعية مقدمة على الحقيقة اللغوية، فكلمة (الركعة) تطلق على مجموع الركعة والله أعلى وأعلم.`,
        f: [] },
      { q: `هل البسملة آية من الفاتحة؟ ومعنى حديث «قسمت الصلاة بيني وبين عبدي نصفين» وعدّ آيات الفاتحة`, p: `82–85`,
        n: `قوله ﷺ: (قسمت الصلاة بيني وبين عبدي نصفين) الحديث. قال العلماء: المراد بالصلاة هنا الفاتحة سُميت بذلك لأنها لا تصح الصلاة إلا بها كقوله ﷺ: «الحج عرفة»، ففيه دليل على وجوبها بعينها في الصلاة. قال العلماء: والمراد قسمتها من جهة المعنى لأن نصفها الأول تحميد لله تعالى وتمجيد وثناء عليه وتفويض إليه، والنصف الثاني سؤال وطلب وتضرع وافتقار. واحتج القائلون بأن البسملة ليست من الفاتحة بهذا الحديث، وهو من أوضح ما احتجوا به، قالوا: لأنها سبع آيات بالإجماع، فثلاث في أولها ثناء أولها الحمد لله، وثلاث دعاء أولها اهدنا الصراط المستقيم، والسابعة متوسطة وهي إياك نعبد وإياك نستعين. قالوا: ولأنه سبحانه وتعالى قال: قسمت الصلاة بيني وبين عبدي نصفين فإذا قال العبد: (الحمد لله رب العالمين) فلم يذكر البسملة، ولو كانت منها لذكرها. وأجاب أصحابنا وغيرهم ممن يقول إن البسملة آية من الفاتحة بأجوبة: أحدها أن التنصيف عائد إلى جملة الصلاة لا إلى الفاتحة، هذا حقيقة اللفظ. والثاني أن التنصيف عائد إلى ما يختص بالفاتحة من الآيات الكاملة. والثالث معناه فإذا انتهى العبد في قراءته إلى الحمد لله رب العالمين. وفي هذه الرواية دليل على أن [اهدنا وما بعده إلى آخر السورة] ثلاث آيات لا آيتان، وفي المسألة خلاف مبني على أن البسملة من الفاتحة أم لا؟ فمذهبنا ومذهب الأكثرين أنها من الفاتحة وأنها آية، واهدنا وما بعده آيتان. ومذهب مالك وغيره ممن يقول إنها ليست من الفاتحة يقول: اهدنا وما بعده ثلاث آيات. وللأكثرين أن يقولوا: قوله (هؤلاء) المراد به الكلمات لا الآيات، بدليل رواية مسلم: فهذا لعبدي. وهذا من أحسن الجواب لأن الجمع محمول على الاثنين، لأن هذا مجاز عند الأكثرين فيحتاج إلى دليل على صرفه عن الحقيقة إلى المجاز، والله أعلم.`,
        o: `مالك وغيره: البسملة ليست من الفاتحة فآيات «اهدنا...» ثلاث. الشافعية والأكثرون: البسملة آية من الفاتحة و«اهدنا...» آيتان.`,
        s: `هذا غير ظاهر؛ لأن التنصيف للفاتحة، ولكن التنصيف لا يلزم منه العد فلا يلزم منه عدد الآيات ولا يلزم منه عدد الحروف ولذا لا يلزم أن تقول ثلاثة وثلاثة وواحدة متوسطة. (وهذا كلام وجيه) فإن [بسم الله الرحمن الرحيم] ليست مختصة بالفاتحة لأنها آية من كل سورة. وهذا كلام حسن أيضاً، وطالما أنه قد صح الحديث عن أبي هريرة ﷺ قال: قال رسول الله ﷺ: «إِذَا قَرَأْتُمْ: {الْحَمْدُ لِلَّهِ}، فَاقْرَءُوا: {بِسْمِ اللَّهِ الرَّحْمَنِ الرَّحِيمِ} إِنَّهَا أُمُّ الْقُرْآنِ، وَأُمُّ الْكِتَابِ، وَالسَّبْعُ الْمَثَانِي، وَ{بِسْمِ اللَّهِ الرَّحْمَنِ الرَّحِيمِ} إِحْدَى آيَاتِهَا» ((قط) ج١ص٣١٢ح٣٦، (هق) ٢٢١٩، (فر) ١٠٤٣، انظر صحيح الجامع: ٧٢٩، الصحيحة: ١١٨٣)، فليس هناك وجه إذاً للاستدلال بالكلام المحتمل. (أن المراد بـ«هؤلاء» الكلمات لا الآيات، وهذا من أحسن الجواب لأن الجمع أقله ثلاثة فإن الجمع أقله ثلاثة.) وهذا بناء على من لا يعد [بسم الله الرحمن الرحيم] آية من الفاتحة وهم كالآتي: [اهدنا الصراط المستقيم (١) صراط الذين أنعمت عليهم (٢) غير المغضوب عليهم ولا الضالين (٣)] فهؤلاء الثلاث آيات عند من لا يعدها كذلك وهي قراءة ورش عن نافع بل هي قراءة أهل المدينة، فهي عند نافع كل القراءات عنه يعدها سبع آيات أولهم (الحمد لله رب العالمين)، أما العراقيين – منهم حفص عن عاصم – عنه يعد [بسم الله الرحمن الرحيم] آية، وعلى طريقة عد المصاحف عندنا ذلك آيتان. ولا يترتب على هذا جواز الوقف على (عليهم) أم لا، فيجوز الوقف عليها على كلا الوجهين، حتى عند من يعدها جزءاً من الآية الأخيرة لأن العبرة باكتمال المعنى، فيجوز الوقف على جملة تامة، فيجوز الوقف على (عليهم) حتى ولو قلنا أنها آية كاملة (صِرَاطَ الَّذِينَ أَنْعَمْتَ عَلَيْهِمْ غَيْرِ المَغْضُوبِ عَلَيْهِمْ وَلاَ الضَّالِّينَ).`,
        f: [`(ص83) «الرحمن الرحيم»: لأن الرحمن صفة ذاتية والرحيم هو الاسم الدال على الصفة الفعلية.`, `(ص84) فليس هناك يوم القيامة (لا المِلك ولا المُلك) لأحد لا دعوى ولا مجاز ولا حقيقة، في الدنيا كان هناك مُلك مجازي وكان هناك أدعياء مُلك يقول أنا أملك، ويوم القيامة لا ادعاء ولا مجاز ولا مُلك حقيقة بالأولى. (فهذا لعبدي) أي الذي سأله، (فهؤلاء لعبدي) أي الدعوات.`, `(ص85) «فإن الجمع أقله ثلاثة».`] },
      { q: `الجهر والإسرار بالقراءة: في العيد والاستسقاء ونوافل الليل والنهار والكسوف والجنازة`, p: `85–86`,
        n: `ومعناه: ما جهر بالقراءة جهرنا به، وما أسرّ أسررنا به. وقد اجتمعت الأمة على الجهر بالقراءة في ركعتي الصبح والجمعة والأوليين من المغرب والعشاء، وعلى الإسرار في الظهر والعصر وثالثة المغرب والأخريين من العشاء. واختلفوا في العيد والاستسقاء، ومذهبنا الجهر فيهما. وفي نوافل الليل قيل: يجهر فيها، وقيل: بين الجهر والإسرار. ونوافل النهار يُسرّ بها. والكسوف يُسرّ بها نهارًا ويجهر ليلًا. والجنازة يُسرّ بها ليلًا ونهارًا، وقيل: يجهر ليلًا.`,
        o: `نوافل الليل: قيل يجهر وقيل بين الجهر والإسرار. الجنازة: يُسر بها، وقيل يجهر ليلًا. الكسوف عند الشافعية: يسر نهارًا ويجهر ليلًا.`,
        s: `وهذا هو الأظهر والله أعلم لصحة الحديث في صحيح مسلم وغيره عن النعمان بن بشير قال: كان رسول الله ﷺ يقرأ في العيدين وفي الجمعة بـ(سبح اسم ربك الأعلى) و(هل أتاك حديث الغاشية). وعن أبي واقد الليثي قال سألني عمر بن الخطاب عما قرأ به رسول الله ﷺ في يوم العيد فقلت بـ(اقتربت الساعة وانشق القمر) و(ق والقرآن المجيد). فدل ذلك على أن الصحابة سمعوا من الرسول ﷺ هذه السور. (نوافل الليل:) كلٌ قد ثبت وقد فعله النبي ﷺ أسر وجهر، لكن لو صلوا جماعة فينبغي أن يجهر. (الكسوف:) بل الظاهر أنه يجهر في صلاة الكسوف لصحة الحديث كما سيأتي في باب الكسوف عن عائشة أن النبي ﷺ جهر في صلاة الخسوف بقراءته فصلى أربع ركعات في ركعتين وأربع سجدات. صحيح مسلم. وعن عائشة أن النبي ﷺ "جهر بالقراءة في صلاة الكسوف" [قال الألباني]: صحيح – "صحيح أبي داود" (١٠٧٤): ق. فقد كانت في صلاة الكسوف وهي نهار. (الجنازة:) وهذا هو الصحيح؛ فيجهر أحياناً ليعلم.`,
        f: [] },
      { q: `قضاء الصلاة الجهرية والسرية: هل يجهر في القضاء؟`, p: `86`,
        n: `ولو فاته صلاة ليل كالعشاء فقضاها في ليلة أخرى جهر، وإن قضاها نهارًا فوجهان: الأصح يسرّ، والثاني يجهر. وإن فاتته نهارية كالظهر فقضاها نهارًا أسرّ، إن قضاها ليلًا فوجهان: الأصح يجهر، والثاني يسرّ.`,
        o: `وجهان: في قضاء الليلية نهارًا (الأصح يسر، والثاني يجهر)، وفي قضاء النهارية ليلًا (الأصح يجهر، والثاني يسر).`,
        s: `بل يقضيها كما وجبت عليه لأن النبي ﷺ صلى صلاة الصبح بعد أن طلعت الشمس، وهذا في النهار الذي يسر به صلاها جهراً، فعَنْ عَمْرِو بْنِ أُمَيَّةَ الضَّمْرِيِّ ﷺ، قَالَ: كُنَّا مَعَ رَسُولِ اللَّهِ ﷺ فِي بَعْضِ أَسْفَارِهِ فَنَامَ، عَنِ الصُّبْحِ حَتَّى طَلَعَتِ الشَّمْسُ فَاسْتَيْقَظَ رَسُولُ اللَّهِ ﷺ فَقَالَ: "تَنَحَّوْا عَنْ هَذَا الْمَكَانِ"، قَالَ: "ثُمَّ أَمَرَ بِلاَلاً فَأَذَّنَ، ثُمَّ تَوَضَّئُوا وَصَلَّوْا رَكْعَتَيِ الْفَجْرِ، ثُمَّ أَمَرَ بِلاَلاً فَأَقَامَ الصَّلاَةَ فَصَلَّى بِهِمْ صَلاَةَ الصُّبْحِ"، (د) ٤٤٤ [قال الألباني]: صحيح. فالصحيح أنه يصليها كما وجبت عليه فيجهر في الأوليين ويسر في الثانيتين؛ فالمقصود من قوله (وَإِنْ قَضَاهَا نَهَارًا فَوَجْهَانِ: الأَصَحّ يُسِرّ) أي في الأوليين، (وَالثَّانِي يَجْهَر) أي في الأوليين، والصحيح الثاني وهو أنه يجهر في الأوليين. (النهارية قضاها ليلاً:) الصحيح أنه يقضيها حيث وجبت عليه فيسر.`,
        f: [] },
      { q: `إذا ترك الجهر أو الإسرار سهوًا: هل يسجد للسهو؟`, p: `86`,
        n: `وحيث قلنا يجهر أو يسر فهو سنة، فلو تركه صحت صلاته، ولا يسجد للسهو عندنا.`,
        o: NO_O,
        s: `لا يسجد للسهو [وجوباً] أما لو قلنا [استحباباً] فنعم. سنة في كل الصلوات حيث قلنا: فلو واحد نسي فجهر في موضع سر أو أسر في موضع جهر، فنقول يستحب أن يسجد للسهو وصلاته صحيحة وصلاة من خلفه صحيحة.`,
        f: [] },
      { q: `قراءة السورة بعد الفاتحة: حكمها (سنة أم واجبة)`, p: `87`,
        n: `قوله: (ومن قرأ بأم الكتاب أجزأت عنه ومن زاد فهو أفضل) فيه دليل لوجوب الفاتحة وأنه لا يُجزي غيرها. وفيه استحباب السورة بعدها، وهذا مجمع عليه في الصبح والجمعة والأوليين من كل الصلوات، وهو سنة عند جميع العلماء. وحكى القاضي عياض رحمه الله تعالى عن بعض أصحاب مالك وجوب السورة وهو شاذ مردود.`,
        o: `بعض أصحاب مالك: تجب السورة (شاذ).`,
        s: `الإجماع على الاستحباب وهو زيادة السورة. (وهو شاذ مردود:) لأنه ﷺ قال: [لاَ صَلاَةَ لِمَنْ لَمْ يَقْرَأْ بِفَاتِحَةِ الْكِتَابِ فَصَاعِدًا]. قال الشيخ الألباني: صحيح. عن النبي ﷺ قال: «مَنْ صَلَّى صَلاَةً لَمْ يَقْرَأْ فِيهَا بِأُمِّ الْقُرْآنِ فَهِيَ خِدَاجٌ – ثَلاَثًا – غَيْرُ تَمَامٍ». صحيح مسلم. إذاً فمن صلى صلاة قرأ فيها بفاتحة الكتاب فهي ليست خداج فهي تامة.`,
        f: [] },
      { q: `قراءة السورة في الركعتين الثالثة والرابعة`, p: `87`,
        n: `وأما السورة في الثالثة والرابعة فاختلف العلماء هل تُستحب أم لا؟ وكره ذلك مالك رحمه الله تعالى، واستحبه الشافعي ﷺ في قوله الجديد دون القديم، والقديم هنا أصح. وقال آخرون: هو مخيّر إن شاء قرأ وإن شاء سبّح، وهذا ضعيف.`,
        o: `مالك: يكره. الشافعي (الجديد): يستحب، وفي القديم لا يستحب (وهو الأصح هنا). وقيل: مخيّر.`,
        s: `الصحيح أنه مستحب أن يقرأ أحياناً، فعن أبي سعيد الخدري فَعَنْ أَبِي سَعِيدٍ الْخُدْرِيِّ قَالَ: كُنَّا نَحْزِرُ قِيَامَ رَسُولِ اللَّهِ ﷺ فِي الظُّهْرِ وَالْعَصْرِ فَحَزَرْنَا قِيَامَهُ فِي الرَّكْعَتَيْنِ الأُولَيَيْنِ مِنَ الظُّهْرِ قَدْرَ قِرَاءَةِ الم تَنْزِيلُ السَّجْدَةِ وَحَزَرْنَا قِيَامَهُ فِي الأُخْرَيَيْنِ قَدْرَ النِّصْفِ مِنْ ذَلِكَ وَحَزَرْنَا قِيَامَهُ فِي الرَّكْعَتَيْنِ الأُولَيَيْنِ مِنَ الْعَصْرِ عَلَى قَدْرِ قِيَامِهِ فِي الأُخْرَيَيْنِ مِنَ الظُّهْرِ وَفِي الأُخْرَيَيْنِ مِنَ الْعَصْرِ عَلَى النِّصْفِ مِنْ ذَلِكَ. وَلَمْ يَذْكُرْ أَبُو بَكْرٍ فِي رِوَايَتِهِ الم تَنْزِيلُ وَقَالَ قَدْرَ ثَلاَثِينَ آيَةً. صحيح مسلم. وهذا يقتضي قراءة شيء من القرآن أحياناً، وفي بعض الروايات أنه قرأ فيها بفاتحة الكتاب ويفهم منها أنه لم يزد على ذلك. عن عَبْدِ اللَّهِ بْنِ أَبِي قَتَادَةَ عَنْ أَبِيهِ أَنَّ النَّبِيَّ ﷺ كَانَ يَقْرَأُ فِي الرَّكْعَتَيْنِ الأُولَيَيْنِ مِنَ الظُّهْرِ وَالْعَصْرِ بِفَاتِحَةِ الْكِتَابِ وَسُورَةٍ وَيُسْمِعُنَا الآيَةَ أَحْيَانًا وَيَقْرَأُ فِي الرَّكْعَتَيْنِ الأُخْرَيَيْنِ بِفَاتِحَةِ الْكِتَابِ. فالجمع بين الروايات بأنه [وَحَزَرْنَا قِيَامَهُ فِي الأُخْرَيَيْنِ قَدْرَ النِّصْفِ] من الأوليين من الظهر، وأحياناً كان يقرأ بالفاتحة فقط، فالجمع بينهما بهذه الطريقة أولى؛ وهناك جمع آخر بين هذه الروايات أنه ﷺ كان يُطول الفاتحة في الأخريين بحيث تكون قدر النصف من الأوليين ولكن هذا خلاف الظاهر، فأحسن الوجوه حملها على التخيير.`,
        f: [`(ص87) الإجماع على الاستحباب وهو زيادة السورة.`] },
      { q: `السورة في صلاة النافلة والجنازة، والسورة المستحبة في كل صلاة (طوال المفصل وأوساطه وقصاره)`, p: `88–89`,
        n: `وتُستحب السورة في صلاة النافلة ولا تُستحب في الجنازة على الأصح لأنها مبنية على التخفيف، ولا يُزاد على الفاتحة إلا التأمين عقبها. ويُستحب أن تكون السورة في الصبح والأوليين من الظهر من طوال المفصّل، وفي العصر والعشاء من أوساطه، وفي المغرب من قصاره.`,
        o: `الجنازة: لا تُستحب السورة على الأصح (وقيل تستحب).`,
        s: `(في الجنازة:) أي في صلاة الجنازة يزيد التأمين فقط ولا يقرأ سورة. (في المغرب من قصاره:) وذلك أحياناً، وقد ثبت في البخاري (باب القراءة في المغرب) عن ابن عباس عن أم الفضل أنها سمعته يقرأ {والمرسلات عرفاً} فقالت: «لقد ذكرتني بقراءتك هذه السورة إنها لآخر ما سمعت من رسول الله ﷺ يقرأ بها في المغرب»، وقال زيد بن ثابت: «مالك تقرأ في المغرب بقصار وقد سمعت النبي ﷺ يقرأ بطول الطوليين؟» وسمعت رسول الله ﷺ قرأ في المغرب بالطور. [قلت: يا أبا عبد الله ما أطول الطوليين؟ قال: "الأعراف" (س) ٩٩٠]، وعن عائشة "أن رسول الله ﷺ قرأ في صلاة المغرب بسورة الأعراف فرّقها في ركعتين" (س) ٩٩١ [قال الألباني]: صحيح. فالطور من طوال المفصل، والمفصل: [من (ق) إلى آخر المصحف]، وطوال المفصل: [من (ق) إلى (النبأ)]، وأواسط المفصل: [من (النبأ) إلى (الضحى)]، وقصار المفصل: [من (ألم نشرح) إلى آخره]. فقرأ النبي ﷺ قصار المفصل [حديث أبي هريرة]: عن أبي هريرة قال: "ما صليت وراء أحد أشبه صلاة برسول الله ﷺ من فلان – قال سليمان بن يسار – كان يطيل الركعتين الأوليين من الظهر ويخفف الأخريين ويخفف العصر ويقرأ في المغرب بقصار المفصل ويقرأ في العشاء بوسط المفصل [بالشمس وضحاها وأشباهها] ويقرأ في الصبح بطول المفصل [بسورتين طويلتين]" (س) ٩٨٢ [قال الألباني]: صحيح. قال الضحاك: وحدثني من سمع أنس بن مالك يقول: ما رأيت أحداً أشبه صلاة بصلاة رسول الله ﷺ من هذا الفتى، يعني عمر بن عبد العزيز. قال الضحاك: «فصليت خلف عمر بن عبد العزيز وكان يصنع مثل ما قال سليمان بن يسار» (حم) ٨٣٦٦. وطوال المفصل كالمرسلات والطور، والأعراف أطول الطوليين، وهو دليل على جواز الإطالة في المغرب أحياناً. ونقول أحياناً يقرأ في العشاء بقصار المفصل ففي صحيح مسلم عن عدي قال: سمعت البراء يحدث عن النبي ﷺ أنه كان في سفر فصلى العشاء الآخرة فقرأ في إحدى الركعتين بالتين والزيتون. ولكن الأغلب الأعم القراءة بأواسط المفصل. وأحياناً في الصبح بأواسط المفصل لأنه قد ثبت ذلك فعن عمرو بن حريث، قال: سمعت النبي ﷺ يقرأ في الفجر إذا الشمس كورت. سنن النسائي. قال الشيخ الألباني: صحيح. وقرأ في الظهر (الليل إذا يغشى) ففي صحيح مسلم عن جابر بن سمرة قال كان النبي ﷺ يقرأ في الظهر بـ(الليل إذا يغشى) وفي العصر نحو ذلك وفي الصبح أطول من ذلك. فدل ذلك على جواز (أي مشروعية ذلك) القراءة في الظهر أيضاً بأواسط المفصل، لكن الأعم أن: الصبح والأوليين من الظهر [بطوال المفصل أو قدرها] والعصر والعشاء [بأوساطه] والمغرب [بالقصار وأحياناً بالطوال].`,
        f: [] },
      { q: `تطويل الأولى على الثانية في القراءة، وتقصير الرابعة على الثالثة، وسجود السهو لمن ترك السورة`, p: `89`,
        n: `واختلفوا في تطويل القراءة في الأولى على الثانية: والأشهر عندنا أنه لا يُستحب بل يسوّي بينهما، والأصح أن يطوّل الأولى للحديث الصحيح: (وكان يطوّل في الأولى ما لا يطوّل في الثانية) ومن قال بالقراءة في الأخريين من الرباعية يقول: هي أخف من الأوليين، واختلفوا في تقصير الرابعة على الثالثة. وحيث شرعت السورة فمن تركها فاتته الفضيلة، ولا يسجد للسهو.`,
        o: `الأشهر عند الشافعية عدم تطويل الأولى على الثانية والأصح تطويلها. واختلفوا في تقصير الرابعة على الثالثة.`,
        s: `(في قوله «ومن قال بالقراءة في الأخريين»:) بمعنى أنه إذا قرأ السورة. (وحيث شرعت السورة فمن تركها فاتته الفضيلة ولا يسجد للسهو:) سجود السهو هنا يُستحب ولا يجب.`,
        f: [],
      },
      { q: `قراءة سورة قصيرة كاملة أفضل أم قراءة قدرها من طويلة؟`, p: `90`,
        n: `وقراءة سورة قصيرة أفضل من قراءة قدرها من طويلة.`,
        o: NO_O,
        s: `السورة الكاملة أفضل لقول الصحابي: [كُنْتُ فِي سُورَةٍ أَقْرَؤُهَا فَلَمْ أُحِبَّ أَنْ أَقْطَعَهَا]، (د) ١٩٨ [قال الألباني]: حسن. [فَلَمْ أُحِبَّ أَنْ أَقْطَعَهَا حَتَّى أُنْفِذَهَا] [قال الألباني]: حسن – "صحيح أبي داود" (١٩٣).`,
        f: [] },
      { q: `القراءة على ترتيب المصحف وعكسه`, p: `90`,
        n: `ويقرأ على ترتيب المصحف، ويُكره عكسه، ولا تبطل به الصلاة.`,
        o: NO_O,
        s: `بل لا دليل على كراهية عكسه، فلا يكره القراءة على خلاف ترتيب المصحف ففي صحيح مسلم عن حذيفة قال: [صَلَّيْتُ مَعَ النَّبِيِّ ﷺ ذَاتَ لَيْلَةٍ فَافْتَتَحَ الْبَقَرَةَ فَقُلْتُ يَرْكَعُ عِنْدَ الْمِائَةِ. ثُمَّ مَضَى فَقُلْتُ يُصَلِّى بِهَا فِي رَكْعَةٍ فَمَضَى فَقُلْتُ يَرْكَعُ بِهَا. ثُمَّ افْتَتَحَ النِّسَاءَ فَقَرَأَهَا ثُمَّ افْتَتَحَ آلَ عِمْرَانَ فَقَرَأَهَا يَقْرَأُ مُتَرَسِّلاً]، وقرأ ﷺ في النظائر سوراً على خلاف الترتيب، والصحيح أن الترتيب ليس توقيفياً، بل هو اجتهاد أجمع عليه الصحابة في كتابة المصاحف، فيلزم في كتابة المصحف هذا الترتيب لكن لا يلزم في التلاوة، فلو خالف في التلاوة لم يكن هناك حرج. لكن الممنوع مخالفة ترتيب الآيات، فهذا لا يجوز.`,
        f: [] },
      { q: `القراءة بالقراءات السبع وحكم القراءة بالشاذ`, p: `90`,
        n: `ويجوز القراءة بالقراءات السبع، ولا يجوز بالشواذ.`,
        o: NO_O,
        s: `لا يجوز القراءة بما خالف رسم المصحف، وأما تحديده بالسبع فلا يلزم؛ فالصحيح جواز قراءة كل ما ثبت سنده ووافق رسم المصحف وصح وجهه اللغوي؛ أما ما خالف رسم المصحف أو لم يثبت سنده فلا يجوز القراءة به.`,
        f: [] },
      { q: `اللحن في الفاتحة: متى تبطل الصلاة به؟`, p: `90`,
        n: `وإذا لحن في الفاتحة لحنًا يُخلّ المعنى كضم تاء (أنعمتَ) أو كسرها أو كسر كاف (إياكِ) بطلت صلاته. وإن لم يُخلّ المعنى كفتح الباء من (المغضوب عليهم) ونحوه كُره ولم تبطل صلاته.`,
        o: NO_O,
        s: `لأنه بذلك لم يقرأ الفاتحة، ومثل ذلك لو أنه ترك حرفاً من الفاتحة وهو قادر عليه، فيغير المخارج بحيث يخرج حرف آخر فالصلاة تبطل بذلك طالما أنه قادر على ذلك؛ أما لو كان غير قادر وعاجز فيُعلم، وإلى أن يُعلم فصلاته صحيحة. ولكن لا يجوز تعمد ذلك بل يحرم تعمد ذلك.`,
        f: [] },
      { q: `ترتيب الفاتحة وموالاتها، ووجوب قراءتها بالعربية، وإسماع النفس، والأخرس`, p: `91`,
        n: `ويجب ترتيب قراءة الفاتحة وموالاتها، ويجب قراءتها بالعربية ويحرم بالعجمية، ولا تصح الصلاة بها سواء عرف العربية أم لا. ويُشترط في القراءة وفي كل الأذكار إسماع نفسه، والأخرس ومن في معناه يحرّك لسانه وشفتيه بحسب الإمكان ويجزئه.`,
        o: NO_O,
        s: `فلا يجوز قراءة معانيها بالأعجمية فهو بذلك لم يقرأ الفاتحة، فيلزم قراءتها بالعربية. (إسماع نفسه) أي لو كان منفرداً، وكما قلنا أن ذلك يتحقق بخروج هواء.`,
        f: [] },
      { q: `الأركان والواجبات من حديث المسيء صلاته: ضابط التفريق، وتعقيب على كلام النووي في المجمع عليه والمختلف فيه`, p: `91–93`,
        n: `قوله: (دخل رجل فصلى ثم جاء فسلم على رسول الله ﷺ ...) هذا الحديث مشتمل على فوائد كثيرة: وليُعلم أولًا أنه محمول على بيان الواجبات دون السنن. فإن قيل: لم يُذكر فيه كل الواجبات فقد بقي واجبات مجمع عليها ومختلف فيها: فمن المجمع عليه: [النية، والقعود في التشهد الأخير، وترتيب أركان الصلاة]. ومن المختلف فيه: [التشهد الأخير والصلاة على النبي ﷺ والسلام]. وهذه الثلاثة واجبة عند الشافعي رحمه الله تعالى، وقال بوجوب السلام الجمهور، وأوجب التشهد كثيرون، وأوجب الصلاة على النبي ﷺ مع الشافعي الشعبي وأحمد بن حنبل وأصحابهما. وأوجب جماعة من أصحاب الشافعي نية الخروج من الصلاة، وأوجب أحمد رحمه الله تعالى التشهد الأول، وكذلك التسبيح وتكبيرات الانتقال...`,
        o: `الشافعي: التشهد الأخير والصلاة على النبي ﷺ والسلام واجبة. الجمهور: السلام. كثيرون: التشهد. الشعبي وأحمد: الصلاة على النبي ﷺ. جماعة من الشافعية: نية الخروج. أحمد: التشهد الأول والتسبيح وتكبيرات الانتقال.`,
        s: `هذا الكلام فيه نظر، فإن هذه الأشياء قد ذكرت في الحديث فإنه قال: [إذا قمت إلى الصلاة فكبّر] فهذا متضمن النية ومتضمن القيام الذي لم يذكره وأيضاً القعود في التشهد الأخير مذكور في رواية البخاري حيث قال: [ثُمَّ اسْجُدْ حَتَّى تَطْمَئِنَّ سَاجِدًا ثُمَّ ارْفَعْ حَتَّى تَطْمَئِنَّ جَالِسًا ثُمَّ اسْجُدْ حَتَّى تَطْمَئِنَّ سَاجِدًا ثُمَّ ارْفَعْ حَتَّى تَطْمَئِنَّ جَالِسًا ثُمَّ افْعَلْ ذَلِكَ فِي صَلاَتِكَ كُلِّهَا] فدل ذلك على وجود جلسة بعد السجدة الثانية في كل ركعة وهي ليست واجبة بالإجماع في الأولى والثالثة، والإجماع صارف لها من الوجوب والركنية إلى الاستحباب وبالاتفاق هي واجبة وليست ركناً في الأوسط وبقي التشهد الأخير فهذه جلسة التشهد الأخير ليس مذكور في هذا الحديث بل هو مذكور، فنحن ننازع أن الجلوس للتشهد الأخير ليس مذكور في حديث المسيء صلاته. وأما ترتيب أركان الصلاة فالحديث نص في ترتيب أركان الصلاة بتكرار كلمة (ثم) فكيف نقول أن الترتيب ليس موجوداً؟ فثم صريحة على النص على الترتيب فترتيب أركان الصلاة من القيام والركوع والسجود هذا أمر مذكور في الحديث؛ فكلام الإمام النووي من بقاء واجبات مجمع عليها ومختلف فيها لم تذكر فيه، فيه نظر، بناء على أن الواجبات عنده هي الأركان. وحديث المسيء صلاته أصل في بيان الأركان ليس الواجبات، فنقسم الصلاة إلى أركان وواجبات ومستحبات وهو مذهب الحنابلة، وأن الأركان لا تصح الصلاة إلا بها، فإذا تركت عمداً أو نسياناً أو جهلاً فلا تصح الصلاة إلا بها، والواجبات يجب أن يؤديها الإنسان وإذا نسيها سجد للسهو ويجبر تركها وإذا تركها جاهلاً صحت صلاته حتى يتعلمها وإذا تركها عامداً فكما ذكرنا فمذهب الإمام أحمد بطلان الصلاة طالما تعمد الترك، ومستحبات يستحب أن يأتي بها ولا تبطل صلاته بتركها عمداً أو سهواً. والأقرب أن يستحب سجود السهو إذا تركها سهواً (فهل في الجماعة ومنفرداً) وليس في كل الأمور. (توضيح)`,
        f: [] },
      { q: `التشهد الأخير والصلاة على النبي ﷺ والسلام والتشهد الأول وتسبيح الركوع والسجود وتكبيرات الانتقال: هل هي أركان أم واجبات؟`, p: `92–93`,
        n: NO_N,
        o: `الشافعي: واجبة (بمعنى الركن). أحمد: التشهد الأول والتسبيح وتكبيرات الانتقال واجبة وليست أركانًا. الحنفية: الطمأنينة ليست ركنًا.`,
        s: `الإمام أحمد لا يقول بوجوبها [الصلاة على النبي ﷺ] كما عند الشافعي لأن الشافعي يجعلها فقط واجبات وسنن، والواجبات عند الشافعي تشمل الواجبات والأركان، والإمام أحمد يقول بوجوب الصلاة على النبي ﷺ وهي ليست ركناً، والصحيح أن التشهد الأخير ليس بركن لأن التشهد لم يذكر في حديث المسيء صلاته، وهناك وجه عند الحنابلة أن التشهد واجب وليس بركن، والصحيح أن التشهد واجب وليس بركن. وفائدة ذلك: أنه لو قرأ أحد الفاتحة في التشهد الأخير وهو سرحان وسلم وانصرف وتذكر في اليوم الثاني؛ فالذي يقول أن التشهد ركن يقول عليه أن يُعيد الصلاة مرةً أخرى، ومن يقول التشهد واجب يقول لو تذكر بعد ما انصرف من الصلاة يسجد للسهو ولو تذكر بعد ذلك في اليوم الثاني صحت صلاته، لأنه لا يشرع سجود السهو بعد طول الفصل فصلاته صحيحة. والصحيح أن السلام واجب أيضاً وذلك على مذهب أحمد وليس ركناً لأنه أيضاً غير موجود في حديث المسيء صلاته. والتشهد الأول أوجبه على مذهبه وطريقته أنه واجب وليس بركن وهذا هو الصحيح، ولا نعلم أحداً من أهل العلم يقول بركنية التشهد الأول ولا الجلوس له، بل أحمد بن حنبل يقول بوجوب التشهد الأول والجلوس له، وهذا هو الصحيح لعدم ذكرها في حديث المسيء صلاته. وتسبيحة الركوع وتسبيحة السجود و(رب اغفر لي) بين السجدتين و(سمع الله لمن حمده) و(ربنا ولك الحمد) كل ذلك الإمام أحمد يقول بوجوبها مع تكبيرات الانتقال، وهذا هو الصحيح، أن كل هذه واجبات وليست أركاناً، ولذلك نقول مرة أخرى هذه القاعدة: أن حديث المسيء صلاته أصل في بيان الأركان وما لم يُذكر فيه فليس بركن، وما دل دليل على وجوبه من كونه من أمر النبي ﷺ أو فعله وقد قال: (صلوا كما رأيتموني أصلي) فهو فعل مقترن بقول فهذا من الواجبات ما لم يصرفه صارف من كتاب أو سنة أو إجماع مثل: رواية البخاري التي فيها جلسة الاستراحة فالإجماع صارف هذه الجلسة من الركنية (ظاهر حديث المسيء صلاته) إلى الاستحباب، وكذلك أشياء كثيرة فإذا صرفها صارف فهي ليست من الواجبات؛ ولذلك نقول حديث المسيء صلاته بجمع طرقه لبيان الأركان، والواجبات مأخوذة من مصدرين [أقوال النبي ﷺ (أفعلوا كذا)، فعله ﷺ مع قوله: (صلوا كما رأيتموني أصلي)]؛ أما المستحبات فما سوى ذلك أو ما دل عليه دليل من الأدلة السابقة. (الطمأنينة في الركوع والسجود والاعتدال ركن، فمن لم يطمئن بطلت صلاته حتى ولو كان حنفي المذهب...) لأننا قلنا أن هذا الرجل كان جاهلاً ومع ذلك النبي ﷺ قال له: (ارْجِعْ فَصَلِّ فَإِنَّكَ لَمْ تُصَلِّ) فهو معذور ومع ذلك لم تصح صلاته.`,
        f: [`(ص92) هذا الكلام فيه نظر: فإن هذه الأشياء قد ذكرت في الحديث ... (انظر مسألة الأركان والواجبات قبله).`, `(ص93) أوجبه على مذهبه وطريقته أنه واجب وليس بركن. (تعليقًا على قول النووي «وأوجب أحمد رحمه الله التشهد الأول».)`] },
      { q: `لماذا لم يعلّم النبي ﷺ المسيء صلاته الواجبات المجمع عليها والمختلف فيها؟ (والجواب بأنها كانت معلومة عنده)`, p: `94`,
        n: `فالجواب: أن الواجبات الثلاثة المجمع عليها كانت معلومة عند السائل فلم يحتج إلى بيانها، وكذا المختلف فيه عند من يوجبه يحمله على أنه كان معلومًا عنده.`,
        o: NO_O,
        s: `فيه نظر، لأن النبي ﷺ علمه القيام ولا شك أنه قد صلى قائماً على الأقل، فلا شك أن هناك أشياء كانت معلومة عنده، و أشياء لم تكن معلومة خطأً ظاهر في الصلاة – فعلمه الجميع – فالرجل جاء فصلى فقد كان متوضئاً ومع ذلك ذكرها النبي ﷺ؛ ولذلك هذا الجواب ليس جواباً صحيحاً؛ فمسألة أنها كانت معلومة، فلتأتي بالدليل على أنها كانت معلومة عنده، فقد علمه ﷺ الذي يعرفه والذي لا يعرفه، فعلمه ما أتى به وما لم يأتِ به، فقد استقبال القبلة على الأقل ذكرها النبي ﷺ، وبهذا يتضح أن هذا الجواب غير صحيح، والذي يحتاج أن يأتي بالدليل على أن هذه الواجبات كانت معلومة، فإذا كان الرجل كان لا يعرف الركوع والسجود والطمأنينة فيهم فكيف تدعي أنه كان يعرف التشهد؟ فإنه بالأولى ألا يعرفه، ولو كان يعرفه فإنه كان ينبغي أن يذكر له كما ذُكر له الركوع والسجود، فهذا الجواب ضعيف جداً. (وجه آخر:) لا، بل لا وجه للجمع بأننا نلتزم بأن نقول هذه أركان ولم يعلمه النبي ﷺ الواجبات لأن صلاته تصح بدونها، ولو علمه كل الواجبات لكثرة عليه فعجز، فتركه ليعلمها بعد ذلك بالتدريج، فرجل لا يعرف كيف يصلي مثل رجل حديث عهد بصلاة والتزام ماذا أعلمه؟ أُعلمه الأركان أُعلمه حديث المسيء صلاته التي لا تصح صلاته إلا بها ثم أُعلمه الواجبات على مهل، لأنه لو صلى بأركان الصلاة فقط صحت صلاته.`,
        f: [] },
      { q: `هل إقامة الصلاة واجبة؟ (من قوله «إذا قمت إلى الصلاة» في حديث المسيء صلاته)`, p: `94`,
        n: `وفي هذا الحديث: دليل على أن إقامة الصلاة ليست واجبة.`,
        o: NO_O,
        s: `هذا الكلام لابد من تقييده، وهو أنها ليست واجبة للمنفرد لأن هذا الرجل كان منفرداً. ونحن نقول هي ليست شرطاً في صحة الصلاة لأنه لم يدل دليل على شرطيتها، خلافاً لمن قال بوجوبها وشرطيتها هي والأذان؛ فالصحيح أن الأذان واجب والإقامة واجبة للجماعات وليست شرطاً في صحة الصلاة، فتصح الصلاة بدونها، ولكن إذا كانوا متمكنين من الأذان والإقامة وجبت عليهم لصحة الأمر بالأذان والإقامة كما سبق في باب الأذان.`,
        f: [] },
      { q: `اشتراط الطهارة من الحدث ومن النجس للصلاة: حكم من صلى بنجاسة جاهلًا أو ناسيًا، وهل الطهارة شرط أم ركن؟`, p: `95`,
        n: `وفيه وجوب الطهارة (من قوله في الرواية الأخرى: «فأسبغ الوضوء»).`,
        o: NO_O,
        s: `بل الحديث دليل على شرطية الطهارة من الحدث، أما الطهارة من النجس فليست في الحديث ففيه (فأسبغ الوضوء) فهو دليل على شرطية الطهارة لأنها خارجة عن ماهية الصلاة فهي مثل الركن بالضبط بمعنى أنه لو صلى (ناسياً أنه لم يتوضأ) أو (جاهلاً أنه جنب) فقد بطلت صلاته لأن الطهارة من الحدث الأصغر والأكبر شرط في صحة الصلاة، فتبطل الصلاة ولو تركها سهواً؛ أو أنه قد كان جاهلاً ولا يعرف فأيضاً صلاته باطلة، بخلاف إزالة النجس فالصحيح الذي دلت عليه الأدلة وجوب ذلك لا شرطيته؛ والفرق بينها أنه لو صلى بنجاسة غير عالم بوجودها وصلى على غير طهارة غير عالم بوجودها لم يكن يعرف أنه جنب فلما رأى ملابسه علم أنه قد كان جنباً فصلاته باطلة لتركه للغسل، لكن لو أنه اغتسل ثم اكتشف وجود نجاسة في ثوبه فصلاته صحيحة؛ فلو قلنا إزالة النجس شرط في صحة الصلاة سنقول له بإعادة الصلاة حتى ولو كان جاهلاً بوجودها ثم علم بعد انتهائه من الصلاة، والدليل على أنها ليست شرطاً حديث أبي سعيد الخدري ﷺ: صَلَّى بِنَا رَسُولُ اللَّهِ ﷺ فَلَمَّا خَلَعَ نَعْلَيْهِ فَوَضَعَهُمَا عَنْ يَسَارِهِ فَخَلَعَ الْقَوْمُ نِعَالَهُمْ، فَلَمَّا قَضَى صَلاَتَهُ قَالَ: "مَا لَكُمْ خَلَعْتُمْ نِعَالَكُمْ؟" قَالُوا: رَأَيْنَاكَ خَلَعْتَ فَخَلَعْنَا، قَالَ: "إِنِّي لَمْ أَخْلَعْهُمَا مِنْ بَأْسٍ وَلَكِنْ جِبْرِيلَ أَخْبَرَنِي أَنَّ فِيهِمَا قَذَرًا، فَإِذَا أَتَى أَحَدُكُمُ الْمَسْجِدَ فَلْيَنْظُرْ فِي نَعْلَيْهِ فَإِنْ كَانَ فِيهِمَا أَذًى فَلْيَمْسَحْهُ". (حب) ٢١٨٥ [قال الألباني]: صحيح – "صحيح أبي داود" (٦٥٧). فصلى ﷺ في النعل ونزعه أثناء الصلاة فجزء من الصلاة وقع كتكبيرة الإحرام وأول جزء من الصلاة حتى أتاه جبريل وفي نعله نجاسة ولم يعده ﷺ فدل ذلك على صحة هذا الجزء من الصلاة، ولذا لو أنه اكتشف بعد انتهائها تكون الصلاة صحيحة أيضاً.`,
        f: [] },
      { q: `استقبال القبلة: هل هو شرط؟ وحكم من صلى إلى غير القبلة باجتهاد أو بغير اجتهاد`, p: `95–96`,
        n: `(وفيه) استقبال القبلة.`,
        o: NO_O,
        s: `وهذا هو الصحيح فاستقبال القبلة شرط في صحة الصلاة إلا من خفيت عليه، فاستقبال القبلة فرضه في حقه الاجتهاد فيها، والفرق هو أنه لو صلى إلى غير القبلة مجتهداً ثم تبين خلاف ذلك صحت صلاته، ولو قلنا استقبال القبلة شرط مطلقاً فيجب عليه أن يعيد الصلاة مثل الطهارة وكأركان الصلاة المذكورة في هذا الحديث، فحتى لو صلاها باجتهاد إلى غير القبلة سوف لا يكون معذوراً، لكن لو قلنا لو خفيت عليه فرضه الاجتهاد، بدليل حديث أهل قباء فقد صلوا إلى غير القبلة ركعة حتى بلغهم نسخ القبلة، فكانت القبلة مشروعة في ذلك الوقت إلى الكعبة ومع ذلك جاء الخبر وقد صلوا ركعة إلى بيت المقدس وركعة إلى الكعبة وصحت صلاتهم؛ فالصحيح أن من خفيت عليه القبلة شرطه الاجتهاد فإذا اجتهد وصلى صحت صلاته على أي حال، وأما إذا صلى بغير اجتهاد ووقعت إلى غير القبلة فصلاته باطلة، وكذا لو صلى ساهياً أو بغير سؤال كأن دخل المسجد فانكسف أن يسأل الناس في مسجد ليس فيه محراب فصلى إلى غير القبلة فصلاته باطلة لأن فرضه الاجتهاد، ولو أنه قام من نومه في غير وعيه ونسي أو أنه دخل المسجد وتهيأ له أن القبلة في هذا الاتجاه من غير سؤال ولا اجتهاد أو أنه اعتاد في مسجده أن يصلي في هذا الاتجاه ثم يأتي أحد الناس ويقيمه تجاه القبلة فلا تصح صلاته لأنه كبر في غير القبلة واتجه إلى القبلة من غير اجتهاد فصلاته باطلة فنقول له اخرج من الصلاة وأعد الصلاة، والميل اليسير هو الذي يمكن تصويبه لأن الفرض أن يكون جهة القبلة وليس عين الكعبة، فلا تقيمه فالصلاة باطلة وعليه أن يعيد التكبيرة مرة أخرى؛ فعليه أن يجتهد سواء عن طريق الشمس والشرق والغرب أو بالبوصلة فلابد وأن يجتهد هو يعلم هو في أي بلد ويعلم في أي اتجاه تكون القبلة ينظر إلى الشمس يرى أين الشرق وأين الغرب، ينظر إلى القمر والنجوم، يسأل واحد مجتهد.`,
        f: [] },
      { q: `حكم التعوذ ودعاء الاستفتاح ورفع اليدين ووضع اليمنى على اليسرى وتكبيرات الانتقال وتسبيحات الركوع والسجود: هل هي واجبة؟`, p: `96–97`,
        n: `وفيه أن التعوذ ودعاء الافتتاح ورفع اليدين في تكبيرة الإحرام، ووضع اليد اليمنى على اليسرى، وتكبيرات الانتقالات وتسبيحات الركوع والسجود، وهيئات الجلوس، ووضع اليد على الفخذ، وغير ذلك مما لم يذكره في الحديث ليس بواجب إلا ما ذكرناه من المجمع عليه والمختلف فيه.`,
        o: `بعض التابعين: يجب التعوذ لقوله تعالى ﴿فإذا قرأت القرآن فاستعذ بالله﴾. أحمد: تجب تكبيرات الانتقال وتسبيحات الركوع والسجود.`,
        s: `الصحيح أن نقول أن هذه ليست بأركان: فأما الاستعاذة فقد قال بعض التابعين بوجوبها لأن الله قال: (فَإِذَا قَرَأْتَ الْقُرْآنَ فَاسْتَعِذْ بِاللَّهِ مِنَ الشَّيْطَانِ الرَّجِيمِ) فهذا أمر ولا وجوب خارج الصلاة، فتعين الوجوب في الصلاة، والمشروع أن تكون قبل القراءة في الركعة الأولى في الفاتحة، وهذا عندي ظاهر أن التعوذ قبل القراءة دليله قوي. وأما دعاء الاستفتاح: فالظاهر عدم وجوبه لأن النبي ﷺ إنما علمه أبو هريرة لما سأله، فعن أبي هريرة قال كان رسول الله ﷺ إذا كبّر في الصلاة سكت هُنيَّة قبل أن يقرأ فقلت يا رسول الله بأبي أنت وأمي أرأيت سكوتك بين التكبير والقراءة ما تقول قال: «أقول: اللهم باعد بيني وبين خطاياي كما باعدت بين المشرق والمغرب اللهم نقني من خطاياي كما ينقى الثوب الأبيض من الدنس اللهم اغسلني من خطاياي بالثلج والماء والبرد». صحيح مسلم. فعلمه إياه فدل ذلك على أنه كان قد تركهم مدةً دون أن يعلمهم دعاء الاستفتاح وتأخير البيان عن وقت الحاجة لا يجوز، فجميعهم لم يعلمهم فدل ذلك على أن دعاء الاستفتاح ليس بواجب وهو قول عامة أهل العلم وشذ من أوجبه وهم قلة قليلة جداً. ورفع اليدين في تكبيرة الإحرام: أيضاً قول جمهور أهل العلم وعامة العلماء على استحباب ذلك. ووضع اليمنى على اليسرى: كذلك. وتكبيرات الانتقال: قد علمتم أن أحمد يقول بوجوبها وهو الصحيح. تسبيحات الركوع والسجود: الراجح وجوب تسبيحة واحدة وليست ركناً كما ذكرنا.`,
        f: [`(ص96) تكبيرة الإحرام ركن من أركان الصلاة، وأما القراءة فقد رجحنا أن المقصود من (ما تيسر معك من القرآن) أنه الفاتحة بدليل رواية أبي داود وابن حبان (واقرأ بفاتحة الكتاب) وهي ركن من أركان الصلاة في كل ركعة لا تصح إلا بها.`] },
      { q: `وجوب الاعتدال من الركوع والطمأنينة في الركوع والسجود والاعتدال والجلوس بين السجدتين`, p: `97–98`,
        n: `وفيه دليل على وجوب الاعتدال عن الركوع، والجلوس بين السجدتين. ووجوب الطمأنينة في الركوع والسجود، والجلوس بين السجدتين، وهذا مذهبنا ومذهب الجمهور، ولم يوجبها أبو حنيفة رحمه الله تعالى، وطائفة يسيرة، وهذا الحديث حجة عليهم وليس عنه جواب صحيح. وأما الاعتدال: فالمشهور من مذهبنا ومذاهب العلماء يجب الطمأنينة فيه، كما يجب في الجلوس بين السجدتين. وتوقف في إيجابها بعض أصحابنا. واحتج هذا القائل بقوله ﷺ في هذا الحديث: (ثم ارفع حتى تعتدل قائمًا) فاكتفى بالاعتدال ولم يذكر الطمأنينة كما ذكرها في الجلوس بين السجدتين، وفي الركوع والسجود.`,
        o: `أبو حنيفة وطائفة يسيرة: لا يوجبون الطمأنينة. وبعض الشافعية: توقف في إيجاب الطمأنينة في الاعتدال.`,
        s: `(وهذا مذهبنا:) وهذا هو الصحيح بالتأكيد لأنها ركن – ومذهبهم أي الشافعية – أنه واجب بمعنى الركنية. (ولم يوجبها أبو حنيفة:) لم يوجب الاعتدال من الركوع ولم يوجب الجلوس بين السجدتين ولا الطمأنينة. (وهذا نص الحديث:) [ثُمَّ ارْكَعْ حَتَّى تَطْمَئِنَّ رَاكِعًا، ثُمَّ ارْفَعْ حَتَّى تَطْمَئِنَّ قَائِمًا] سنن ابن ماجة قال الألباني: صحيح. فيجب أن يطمئن كما يجب في الجلوس بين السجدتين قال: [ثُمَّ اسْجُدْ حَتَّى تَطْمَئِنَّ سَاجِدًا ثُمَّ ارْفَعْ حَتَّى تَطْمَئِنَّ جَالِسًا ثُمَّ اسْجُدْ حَتَّى تَطْمَئِنَّ سَاجِدًا ثُمَّ ارْفَعْ حَتَّى تَطْمَئِنَّ جَالِسًا] البخاري. (واحتج هذا القائل:) لقوله: [ثُمَّ ارْفَعْ حَتَّى تَعْتَدِلَ قَائِمًا] ولكن في الحقيقة: (تَعْتَدِلَ قَائِمًا) دليل على وجود الطمأنينة، فلا يثبت أنه قائم حتى يستقر. (ليس بظاهر كما ذكرنا لأن معنى (تعتدل قائماً) فيه معنى الطمأنينة.)`,
        f: [] },
      { q: `وجوب القراءة في الركعات كلها، وسؤال المفتي ما لم يسأل عنه (للنصيحة)، والرفق بالمتعلم، وتغيير المنكر بالتعليم`, p: `98`,
        n: `وفيه وجوب القراءة في الركعات كلها وهو مذهبنا ومذهب الجمهور كما سبق. وفيه أن المفتي إذا سُئل عن شيء وكان هناك شيء آخر يحتاج إليه السائل ولم يسأل عنه يُستحب له أن يذكره له ويكون هذا من النصيحة لا من الكلام فيما لا يعني، وموضع الدلالة أنه قال: علمني يا رسول الله أي علمني الصلاة فعلمه الصلاة واستقبال القبلة والوضوء وليسا من الصلاة لكنهما شرطان لها. وفيه الرفق بالمتعلم والجاهل وملاطفته وإيضاح المسألة وتلخيص المقاصد، والاقتصار في حقه على المهم دون المكملات التي لا يحتمل حاله حفظها والقيام بها. وفيه استحباب السلام عند اللقاء ووجوب رده وأنه يستحب تكراره إذا تكرر اللقاء وإن قرب العهد وأنه يجب رده في كل مرة وأن صيغة الجواب [وعليكم السلام] أو وعليك بالواو وهذه الواو مستحبة عند الجمهور وأوجبها بعض أصحابنا. وليس بشيء بل الصواب أنها سنة.`,
        o: `بعض أصحاب الشافعي: الواو في «وعليكم السلام» واجبة. الجمهور: مستحبة.`,
        s: `(كما سبق وقلنا يجب قراءة الفاتحة.) (فإن تغيير المنكر يبدأ بالتعليم لا يبدأ باليد مباشرة فضلاً عن الزجر، فيبدأ بالتعليم للجاهل.)`,
        f: [`(ص98) لقوله: [ثُمَّ ارْفَعْ حَتَّى تَعْتَدِلَ قَائِمًا] ولكن في الحقيقة: (تَعْتَدِلَ قَائِمًا) دليل على وجود الطمأنينة، فلا يثبت أنه قائم حتى يستقر.`] },
      { q: `من أخلّ ببعض واجبات الصلاة (الأركان): هل تصح صلاته؟ ولماذا لم يأمره النبي ﷺ بالإعادة إلا بعد أن أعاد؟ وما معنى «لم تصل»؟`, p: `99`,
        n: `وفيه أن من أخلّ ببعض واجبات الصلاة لا تصح صلاته، ولا يُسمى مصليًا بل يقال: لم تُصل. فإن قيل: كيف تركه مرارًا يصلي صلاة فاسدة؟ فالجواب أنه لم يؤذن له في صلاة فاسدة، ولا علم من حاله أنه يأتي بها في المرة الثانية والثالثة فاسدة، بل هو محتمل أن يأتي بها صحيحة وإنما لم يعلّمه أولًا ليكون أبلغ في تعريفه وتعريف غيره بصفة الصلاة المجزئة كما أمرهم بالإحرام بالحج ثم بفسخه إلى العمرة ليكون أبلغ في تقرير ذلك عندهم، والله أعلم. واعلم أنه وقع في إسناد هذا الحديث في مسلم عن يحيى بن سعيد عن عبيد الله قال: [حدثني سعيد بن أبي سعيد عن أبيه عن أبي هريرة]. قال الدارقطني في استدراكاته: خالف يحيى بن سعيد في هذا جميع أصحاب عبيد الله فكلهم رووه عن عبيد الله عن سعيد عن أبي هريرة ثم يذكروا أباه. قال الدارقطني: ويحيى حافظ فيعتمد ما رواه فحصل أن الحديث صحيح لا علة فيه، ولو كان الصحيح ما رواه الأكثرون لم يضر في صحة المتن، وقد سبق بيان مثل هذا مرات في أول الكتاب ومقصودي بذكر هذا ألا يغتر بذكر الدارقطني أو غيره له في الاستدراكات. والله أعلم.`,
        o: NO_O,
        s: `(أي الأركان.)`,
        f: [`(ص99) «واجبات الصلاة»: أي الأركان.`] },
    ],
  },
  {
    title: `باب نهي المأموم عن جهره بالقراءة خلف إمامه (ص100–)`,
    items: [
      { q: `ما يدل عليه نهي المأموم عن الجهر بالقراءة خلف إمامه (وحمل حديث «فانتهى الناس عن القراءة»)`, p: `100`,
        n: `(حديث عمران بن حصين: «أيكم قرأ خلفي بسبح اسم ربك الأعلى» فقال رجل: أنا ولم أرد بها إلا الخير. قال: «قد علمت أن بعضكم خالجنيها») وفي رواية: «قد ظننت أن بعضكم خالجنيها».`,
        o: NO_O,
        s: `(قد ظننت:) أي: (قد علمت). هذا الحديث يدل على نهي المأموم عن جهره بالقراءة خلف الإمام، فهو يدل على ما دل عليه حديث أبي هريرة ﷺ، أو أنه يبين ما قد يحتمله حديث أبي هريرة الذي مضى وهو قوله: (فَانْتَهَى النَّاسُ عَنِ الْقِرَاءَةِ مَعَ رَسُولِ اللَّهِ ﷺ) فمعناه انتهائهم عن القراءة الجهرية للسورة خلف رسول الله ﷺ أو قراءة السورة مطلقاً في الصلاة الجهرية، وليس فيها أنهم تركوا قراءة الفاتحة والله أعلى وأعلم، فهذا الحديث يبين ما قد يحتمله حديث أبي هريرة كما حمله البعض (فَانْتَهَى النَّاسُ عَنِ الْقِرَاءَةِ) على أنها انتهى الناس عن قراءة الفاتحة وليس كذلك فإنهم انتهوا عن قراءة السورة كما أُمر أبو هريرة وغيره بقراءة الفاتحة خلف الإمام. ولكن هذا الحديث يبين كما ذكرنا يدل على أن النبي ﷺ أنكر عليهم الجهر خلفه بالقراءة بالسورة.`,
        f: [`(ص100) «قد ظننت»: أي (قد علمت).`] },
      { q: `قراءة المأموم السورة في الصلاة السرية والجهرية، وحكم قراءته إذا كان بعيدًا عن الإمام لا يسمع قراءته`, p: `101`,
        n: `قوله: (صلى بنا رسول الله ﷺ صلاة الظهر أو العصر فقال أيكم قرأ خلفي سبح اسم ربك الأعلى فقال رجل: أنا ولم أرد بها إلا الخير قال: قد علمت أن بعضكم خالجنيها) وفي الروايتين الأخيرتين أنه [كان في صلاة الظهر بلا شك]. (خالجنيها) أي نازعنيها ومعنى هذا الكلام الإنكار عليه، والإنكار في جهره أو رفع صوته بحيث أسمع غيره لا عن أصل القراءة، بل فيه أنهم كانوا يقرؤون بالسورة في الصلاة السرية. وفيه إثبات قراءة السورة في الظهر للإمام وللمأموم، وهذا الحكم عندنا. ولنا وجه شاذ ضعيف أنه لا يقرأ المأموم السورة في السرية كما لا يقرؤها في الجهرية، وهذا غلط لأنه في الجهرية يؤمر بالإنصات، وهنا لا يسمع فلا معنى لسكوته من غير استماع. ولو كان في الجهرية بعيدًا عن الإمام لا يسمع قراءته فالأصح أنه يقرأ السورة لما ذكرناه. والله أعلم.`,
        o: `وجه شاذ ضعيف عند الشافعية: لا يقرأ المأموم السورة في السرية كما لا يقرؤها في الجهرية. (وهو مذهب أبي حنيفة في عدم القراءة خلف الإمام مطلقًا.)`,
        s: `(ولا معنى للنهي عن قراءة في الصلاة السرية وهو لا يسمع قراءة إمامه كما هو مذهب أبي حنيفة فإنه يرى عدم القراءة خلف الإمام في سرية ولا جهرية بل يظل المأموم صامتاً وهذا ليس بشيء، فإن المعنى في أمر المأموم بعدم القراءة هو الإنصات، فكيف وهو لا يسمع قراءة الإمام لأن الإمام يُسر؟ فالصحيح أن هذا الإنصات مأمور به في غير الفاتحة كما ذكرنا أو لا تنافي بين الأمر بالإنصات وقراءة المأموم مع قراءة إمامه فإنه لو قرأ نفس ما يقرؤه الإمام سراً لم ينازع الإمام ولم يكن ذلك منافياً للإنصات لقراءة إمامه والله أعلم.) (التفاتاً إلى المعنى، ولأنه لا ينازع الإمام مع بعده عنه هذا البعد وعدم سماعه لقراءته، كما لو صلى في مسجد كبير وطويل والكهرباء انقطعت والمأمومين لا يسمعون صوت الإمام وإنما ينقلون التكبير فقط، فلا يؤمرون بالسكوت بل يقرأون السورة كما يقرأون الفاتحة.)`,
        f: [] },
    ],
  },
  {
    title: `باب حجة من قال لا يجهر بالبسملة (ص102–106)`,
    items: [
      { q: `هل البسملة آية من الفاتحة؟ والجهر بها: مذاهب العلماء وحجة كل فريق`, p: `103–105`,
        n: `وفيه قول أنس: (صليت مع رسول الله ﷺ وأبي بكر وعمر وعثمان ﵃ فلم أسمع أحدًا منهم يقرأ بسم الله الرحمن الرحيم) وفي رواية (وكانوا يستفتحون بالحمد لله رب العالمين لا يذكرون بسم الله الرحمن الرحيم في أول قراءة ولا في آخرها). وقوله (يستفتحون بالحمد لله): هو برفع الدال على الحكاية. استدل بهذا الحديث: من لا يرى البسملة من الفاتحة، ومن يراها منها ويقول لا يجهر. ومذهب الشافعي رحمه الله تعالى وطوائف من السلف والخلف أن البسملة آية من الفاتحة، وأنه يجهر بها حيث يجهر بالفاتحة. واعتمد أصحابنا ومن قال بأنها آية من الفاتحة أنها كُتبت في المصحف بخط المصحف، وكان هذا باتفاق الصحابة وإجماعهم على أن لا يثبتوا فيه بخط القرآن غير القرآن وأجمع بعدهم المسلمون كلهم في كل الأعصار إلى يومنا وأجمعوا أنها ليست في أول براءة وأنها لا تكتب فيها وهذا يؤكد ما قلناه.`,
        o: `فريق: البسملة ليست من الفاتحة أو لا يلزم قراءتها سرًّا ولا جهرًا وتصح الصلاة بالحمد لله مباشرة. فريق آخر: هي من الفاتحة ولكن لا يجهر بها. الشافعي وطوائف: آية من الفاتحة ويجهر بها حيث يجهر بالفاتحة.`,
        s: `هذا الحديث استدل به فريقان: فريق يرى أن البسملة ليست من الفاتحة ولا يشرع قراءتها أو على الأقل لا يلزم قراءتها سراً ولا جهراً ولو بدأ بالحمد لله مباشرةً بدون البسملة فصلاته صحيحة. ويحتج بها فريق آخر يقول أن البسملة من الفاتحة ولكن لا يجهر بقراءتها. وبالتالي من لم يقرأها لم يقرأ الفاتحة، وبالتالي لو كان عالماً بهذا وبأدلة هذا ولم يفعل فصلاته غير صحيحة، ولكن من كان متأولاً مذهب من يقول بأنها ليست من الفاتحة فصلاته صحيحة للتأويل. وأما الترقيم الذي في المصاحف فهذا بناء على قراءة حفص، فإن عد الآيات ليس موجوداً في المصحف العثماني مثل الأرباع فهي ليست موجودة، فعد الآيات بناء على قراءة حفص وهي داخلة على أصل الرسم العثماني، الرسم العثماني متعلق بالمكتوب، لكن نقول الرسم العثماني أثبت الفاتحة بإجماع بل كل المصاحف فيها إثبات البسملة في الفاتحة بإجماع، فهي أحد الأدلة. واحتجوا بأدلة أخرى أقواها دليلاً: حديث أم سلمة: [حَدَّثَنَا عُمَرُ بْنُ هَارُونَ، عَنِ ابْنِ جُرَيْجٍ، عَنِ ابْنِ أَبِي مُلَيْكَةَ، عَنْ أُمِّ سَلَمَةَ، أَنَّ النَّبِيَّ ﷺ قَرَأَ فِي الصَّلاَةِ {بِسْمِ اللَّهِ الرَّحْمَنِ الرَّحِيمِ} فَعَدَّهَا آيَةً، وَ{الْحَمْدُ لِلَّهِ رَبِّ الْعَالَمِينَ} آيَتَيْنِ، وَ{إِيَّاكَ نَسْتَعِينُ} وَجَمَعَ خَمْسَ أَصَابِعِهِ.] صحيح ابن خزيمة. تعليق الذهبي في التلخيص: أجمعوا على ضعفه يعني عمر بن هارون وقال النسائي متروك، فهذا أصرح نص لكن الراجح فيه اختلاف في صحته. وحديث أبي هريرة: «إِذَا قَرَأْتُمْ: {الْحَمْدُ لِلَّهِ}، فَاقْرَءُوا: {بِسْمِ اللَّهِ الرَّحْمَنِ الرَّحِيمِ} إِنَّهَا أُمُّ الْقُرْآنِ، وَأُمُّ الْكِتَابِ، وَالسَّبْعُ الْمَثَانِي، وَ{بِسْمِ اللَّهِ الرَّحْمَنِ الرَّحِيمِ} إِحْدَى آيَاتِهَا». (قط) ج١ص٣١٢ح٣٦، انظر صحيح الجامع: ٧٢٩. فلا نزاع أن الفاتحة سبع آيات وقد صح الحديث في البخاري أنه قال عنها: [{الْحَمْدُ لِلَّهِ رَبِّ الْعَالَمِينَ} هِيَ السَّبْعُ الْمَثَانِي وَالْقُرْآنُ الْعَظِيمُ الَّذِي أُوتِيتُهُ.] إجماع أنها سبع آيات، ولكن طريقة العد كما قلنا فهو اجتهاد، فلو رأى أحد المصاحف المكتوبة على قراءة ورش فعند طريقة العد لا يكتب عند (بسم الله الرحمن الرحيم) رقم (١) ويضع بعد (صراط الذين أنعمت عليهم) رقم (٦) وعند (غير المغضوب عليهم ولا الضالين) رقم (٧)، أما المصاحف التي تكتب على طريقة حفص، يعد (صراط الذين أنعمت عليهم غير المغضوب عليهم ولا الضالين) آية واحدة رقم (٧)، فلا نزاع أنها سبع آيات فالذي يعد (بسم الله الرحمن الرحيم) يجعل الأخيرة (صراط الذين أنعمت عليهم غير المغضوب عليهم ولا الضالين) آية واحدة والذي لا يعدها آية من الفاتحة يجعل (صراط الذين أنعمت عليهم) آية و(غير المغضوب عليهم ولا الضالين) آية؛ لكن الصحيح أنها آية من الفاتحة والله أعلى وأعلم. للحديث الذي ذكرناه.`,
        f: [`(ص103) «يستفتحون بالحمد لله»: بمعنى أن (الحمد لله رب العالمين) الجملة كلها في موضع جر بالباء، ولهذا قال برفع الدال الحمدُ (بالحمدِ) ومع ذلك لأنه على الحكاية وهو حكاية ما يقرأ فهو يحكي قراءتهم وهو يقولون (الحمد لله).`, `(ص104) «فهي أحد الأدلة».`] },
      { q: `الجهر بالبسملة أو الإسرار بها: الجمع بين الأحاديث وهل هي آية مستقلة في أول كل سورة؟`, p: `105`,
        n: `(الحديث: «صليت خلف النبي ﷺ وأبي بكر وعمر وعثمان فكانوا يستفتحون بـ(الحمد لله رب العالمين) لا يذكرون (بسم الله الرحمن الرحيم) في أول قراءة ولا في آخرها».)`,
        o: `ابن القيم: يجهر بها أحيانًا ويسر بها غالبًا.`,
        s: `والجمع بين هذا وبين حديث أنس أنه يجهر بها أحياناً ويسر بها غالباً لأن أنس أكثر ما صلى مع النبي ﷺ لم يسمعه يجهر بـ(بسم الله الرحمن الرحيم) كما في رواية أخرى في هذا الحديث عن أنس قال: «صَلَّيْتُ خَلْفَ رَسُولِ اللَّهِ ﷺ وَخَلْفَ أَبِي بَكْرٍ، وَعُمَرَ، وَعُثْمَانَ فَكَانُوا لَا يَجْهَرُونَ بِـ{بِسْمِ اللَّهِ الرَّحْمَنِ الرَّحِيمِ} [الفاتحة: ١]» (مسند أحمد، قال الأرنؤوط: إسناده صحيح على شرط الشيخين. وأخرجه ابن خزيمة (٤٩٥) والدارقطني ١/٣١٥ من طريق وكيع بن الجراح بهذا الإسناد). أما الروايات التي معنا يقول أنس: [فَلَمْ أَسْمَعْ أَحَدًا مِنْهُمْ يَقْرَأُ (بِسْمِ اللَّهِ الرَّحْمَنِ الرَّحِيمِ).] فهذا لا ينافي قراءتها سراً، وقول أنس: [لاَ يَذْكُرُونَ بِسْمِ اللَّهِ الرَّحْمَنِ الرَّحِيمِ فِي أَوَّلِ قِرَاءَةٍ وَلاَ فِي آخِرِهَا.] فتصلح أن تقيد بـ(لا يذكرونها جهراً) وخصوصاً مع صحة الرواية في غير مسلم [فَكَانُوا لَا يَجْهَرُونَ بِـ{بِسْمِ اللَّهِ الرَّحْمَنِ الرَّحِيمِ}]، فالصحيح أنه يجهر بها أحياناً ويسر بها غالباً لأن هذا هدي النبي ﷺ وخلفائه الراشدين في أغلب الحالات. احتج من يقول بأنها ليست من الفاتحة بدليل آخر وهو حديث أبي هريرة الماضي مرفوعاً للنبي ﷺ فيما يرويه عن ربه: [قَسَمْتُ الصَّلاَةَ بَيْنِي وَبَيْنَ عَبْدِي نِصْفَيْنِ وَلِعَبْدِي مَا سَأَلَ فَإِذَا قَالَ الْعَبْدُ: (الْحَمْدُ لِلَّهِ رَبِّ الْعَالَمِينَ).] والصلاة المقصود بها الفاتحة، فتأويل هذا الحديث على أن آية (بسم الله الرحمن الرحيم) آية مستقلة والله أعلى وأعلم، فالصحيح أن البسملة آية مستقلة في أول كل سورة ولذا لم يذكرها في هذا الحديث. وسيذكر مسلم في الباب الآتي الدليل على أنها آية مستقلة في أول كل سورة.`,
        f: [`(ص105) إذاً ليس مقصود مسلم أن يروي الجزء الأول من الحديث على شرطه لأن [عَنْ عَبْدَةَ إِنَّ عُمَرَ بْنَ الْخَطَّابِ] فهذا مرسل وهو ليس على شرط مسلم ولكن مسلم ذكر الألفاظ التي ذكرت له تماماً للجزء الأخير من الحديث وهو قوله: [وَعَنْ قَتَادَةَ أَنَّهُ كَتَبَ يُخْبِرُهُ عَنْ أَنَسٍ أَنَّهُ حَدَّثَهُ قَالَ صَلَّيْتُ خَلْفَ النَّبِيِّ ﷺ]. فهذا هو المتصل.`] },
      { q: `الجهر بدعاء الاستفتاح للتعليم (أثر عمر ﵁ المرسل)، ومعنى «سبحانك اللهم وبحمدك»`, p: `105–106`,
        n: `قال أبو علي الغساني: هكذا وقع [عن عبدة أن عمر] وهو مرسل، يعني أن: عبدة وهو ابن أبي لبابة لم يسمع من عمر. قال: وقوله بعده [عن قتادة] يعني الأوزاعي عن قتادة عن أنس هذا هو المقصود من الباب وهو حديث متصل. هذا كلام الغساني. والمقصود أنه عطف قوله [وعن قتادة] على قوله [عن عبدة] وإنما فعل مسلم هذا لأنه سمعه هكذا فأداه كما سمعه، ومقصوده الثاني المتصل دون الأول المرسل. ولهذا نظائر كثيرة في صحيح مسلم وغيره ولا إنكار في هذا كله. وقوله (سبحانك اللهم وبحمدك): قال الخطابي: أخبرني ابن خلاد قال: سألت الزجاج عن الواو في قوله وبحمدك فقال: معناه سبحانك اللهم وبحمدك سبحتك. قال: والجد هنا العظمة. والله تعالى أعلم.`,
        o: NO_O,
        s: `(أي أنه سمع المرسل والمتصل والذي عنده علم سوف يعلم أن هذا مرسل ليس على شرط مسلم، ولكنه حديث ثابت عن عمر ﵁ من طرق أخرى [منها: في سنن الدارقطني: عَنِ الأَعْمَشِ، عَنْ إِبْرَاهِيمَ، عَنِ الأَسْوَدِ، قَالَ: كَانَ عُمَرُ ﵁ إِذَا افْتَتَحَ الصَّلاَةَ قَالَ: «سُبْحَانَكَ اللَّهُمَّ وَبِحَمْدِكَ وَتَبَارَكَ اسْمُكَ وَتَعَالَى جَدُّكَ وَلاَ إِلَهَ غَيْرُكَ». يُسْمِعُنَا ذَلِكَ وَيُعَلِّمُنَا، وَعَنِ الأَسْوَدِ قَالَ: سَمِعْتُ عُمَرَ ﵁ افْتَتَحَ الصَّلاَةَ فَكَبَّرَ ثُمَّ قَالَ: سُبْحَانَكَ اللَّهُمَّ وَبِحَمْدِكَ ، وَتَبَارَكَ اسْمُكَ ، وَتَعَالَى جَدُّكَ ، وَلاَ إِلَهَ غَيْرُكَ، ثُمَّ تَعَوَّذَ.» (ش) ٢٤٥٦ ، (قط) ج١/ص٣٠١ ح١٧ ، (هق) ٢١٨٨ ، (م) ٥٢ – (٣٩٩)، وصححه الألباني في الإرواء: ٣٤٠]، فهذا المرسل متصل من طرق أخرى فيدل على استحباب الجهر أحياناً بدعاء الاستفتاح للتعليم، ويدل على أن عمر ﵁ كان يجهر به أحياناً للتعليم، ولكن أصله الإسرار لأن أبا هريرة قال سكوتك بين القراءة والتكبير ما تقول؟ فسماه سكوتاً، فدل ذلك على أن النبي ﷺ كان لا يجهر بدعاء الاستفتاح دائماً. قول ابن القيم في الجمع بين الأدلة في قضية البسملة هو ما ذكرناه وما رجحناه من أنها من الفاتحة يجهر بها أحياناً ويسر بها غالباً وهي آية مستقلة في أولها كما ذكرنا. وهذا من أحسن الوجوه (في معنى «سبحانك اللهم وبحمدك»: سبحتك بحمدك)، وهناك معاني أخرى منها: سُبْحَانَكَ اللَّهُمَّ (سبحانك) وَبِحَمْدِكَ (سبحتُك) أو (وأنا متلبس بحمدك) فهي أشمل، ولكن الحمد على التسبيح على العبادة أكمل أنواع العبادات وأعظم نعمة هي التوفيق للعبادة.`,
        f: [] },
    ],
  },
  {
    title: `باب حجة من قال البسملة آية من أول كل سورة سوى براءة (ص107–110)`,
    items: [
      { q: `هل البسملة آية من أول كل سورة؟ (دلالة حديث أنس في سورة الكوثر)، وفوائد الحديث`, p: `108–110`,
        n: `في هذا الحديث فوائد منها: أن البسملة من أوائل السور من القرآن وهو مقصود مسلم بإدخال الحديث هنا. وفيه جواز النوم في المسجد وجواز نوم الإنسان بحضرة أصحابه. وأنه إذا رأى التابع من متبوعه تبسمًا أو غيره مما يقتضي حدوث أمر يستحب له أن يسأل عن سببه. وفيه إثبات الحوض والإيمان به واجب وسيأتي بسطه حيث ذكر مسلم أحاديثه في آخر الكتاب إن شاء الله تعالى. وقوله: (لا تدري ما أحدثوا بعدك) تقدم شرحه في أول كتاب الطهارة والله أعلم.`,
        o: NO_O,
        s: `بل هو صريح في أنها آية في أول كل سورة؛ لماذا قلنا (في أول) ولم نقل (من أول)؟ لأنها تفرق في طريقة العد، ولكن حديث: (فإنها إحدى آياتها) صريح في أنها إحدى آيات الفاتحة، فإذا قلنا (من كل سورة) يكون العد في آيات كل سورة، وللعلم ليست هذه طريقة حفص، فطريقته عدها آية مستقلة، والدليل على أنها (في أول) وليست (من أول) كل سورة قول النبي ﷺ: "إِنَّ سُورَةً مِنَ الْقُرْآنِ ثَلاَثُونَ آيَةً شَفَعَتْ لِرَجُلٍ حَتَّى غُفِرَ لَهُ، وَهِيَ سُورَةُ تَبَارَكَ الَّذِي بِيَدِهِ الْمُلْكُ": "هَذَا حَدِيثٌ حَسَنٌ"، (ت) ٢٨٩١ [قال الألباني]: حسن. وهي باتفاق ثلاثون آية بدون البسملة فلو عدت البسملة فهي إحدى وثلاثون باتفاق، فدل ذلك على أنها آية مستقلة في أول كل سورة، وفي الحديث الصحيح الآخر أن النبي ﷺ: "كان لا يعرف فصل السورة حتى ينزل عليه {بسم الله الرحمن الرحيم}". قال الشيخ الألباني: (صحيح) صحيح أبي داود (٧٥٤) عن ابن عباس. إذاً كانت تنزل في أول كل سورة. إذا لم تكن القراءة من أول السورة، فلا بأس أن يقرأ {بسم الله الرحمن الرحيم} وقد قرأها طوائف من القراء، ولكن لا يلزم قراءتها، والأظهر والله أعلم أنه يستعيذ ولا يقرأ البسملة. (وفي ذلك:) خطر البدعة لأن الإحداث بعد النبي ﷺ من أسباب الردع عن حوض النبي ﷺ. وأما قوله (فَإِنَّهُ نَهْرٌ وَعَدَنِيهِ رَبِّي ﷻ عَلَيْهِ خَيْرٌ كَثِيرٌ هُوَ حَوْضٌ) في رواية الصحيح أنه نهر في الجنة وهو حوض لأنه يصب ميزابان من هذا النهر في حوض النبي ﷺ الذي في عرصات القيامة، وهذا يجمع ما بين الأمرين. وهو نهر وهو حوض لأنه شراب واحد، فشراب نهر الكوثر هو الذي يسقى الناس منه يوم القيامة، ومن شرب منه شربة لم يظمأ بعدها أبداً.`,
        f: [`(ص108) سبب نزول سورة الكوثر في العاص بن وائل: قال ابن كثير في تفسيره: [قال ابن عباس ومجاهد وسعيد بن جبير وقتادة: نزلت في العاص بن وائل. وقال محمد بن إسحاق عن يزيد بن رومان قال: كان العاص بن وائل إذا ذكر رسول الله ﷺ يقول: دعوه فإنه رجل أبتر لا عقب له، فإذا هلك انقطع ذكره. فأنزل الله هذه السورة.] وجاء في تفسير الطبري عن قتادة: (إِنَّ شَانِئَكَ هُوَ الأَبْتَرُ) قال: هو العاص بن وائل وهو أبتر ليس له عقب. قال قتادة: الأبتر: الحقير الدقيق الذليل. قال ذلك لأن النبي ﷺ لم يعش له ذكوراً فنزلت الآيات. فكل من يبغض النبي ﷺ لابد وأن ينقطع بفضل الله ﷻ. والعجيب أن اليهود يقولون هذا إلى الآن يقولون: (محمد مات خلف بنات) ولكن بفضل الله ﷻ هو أكثر الأنبياء أتباعاً ودينه أسرع الأديان انتشاراً وأظهر الأديان حجة بفضل الله ﷻ، وكل من يتعرض له ﷺ فلابد وأن يبتر. ابن تيمية يحكي أنهم في منازلتهم للتتار ولغيرهم فيكون بينهم صولات وجولات وتكون الحرب شديدة حتى يقع الكفار في سب النبي ﷺ ويغتاظ المسلمون فيستبشر خيراً لحصول الهزيمة مباشرةً عقب سبهم للنبي ﷺ وأنه يقع بهم من أنواع البلايا والمصائب بعدها مباشرةً. لابد وأن يغتاظ المسلمون من سب النبي ﷺ ولكن هو علامة على هلاك الكفرة وانقطاعهم.`, `(ص109) أو الصحيح أن يقال: أن النهر الذي في الجنة من الخير الكثير الذي وعده الله. (تعليقًا على قول النووي «والكوثر هنا نهر في الجنة كما فسره النبي ﷺ وهو في موضع آخر عبارة عن الخير الكثير».)`, `(ص109) لأنه ﷺ كان بين أظهرهم ونام.`] },
    ],
  },
  {
    title: `باب وضع يده اليمنى على اليسرى بعد تكبيرة الإحرام تحت صدره فوق سرته ووضعهما في السجود على الأرض حذو منكبيه (ص110–115)`,
    items: [
      { q: `موضع وضع اليد اليمنى على اليسرى في الصلاة: على الصدر أم تحت السرة أم فوقها؟ وكيفية الوضع (على الرسغ والساعد)، وقوله «حيال أذنيه»`, p: `110–112`,
        n: `وفيه استحباب رفع يديه عند الدخول في الصلاة وعند الركوع وعند الرفع منه. وفيه استحباب كشف اليدين عند الرفع ووضعهما على الأرض في السجود حذو منكبيه. واستحباب وضع اليمنى على اليسرى بعد تكبيرة الإحرام ويجعلهما تحت صدره فوق سرته، هذا مذهبنا المشهور وبه قال الجمهور. وقال أبو حنيفة وسفيان الثوري وإسحاق بن راهويه وأبو إسحاق المروزي من أصحابنا يجعلهما تحت سرته، وعن علي بن أبي طالب ﵁ روايتان كالمذهبين. وعن أحمد روايتان كالمذهبين ورواية ثالثة أنه مخيّر بينهما ولا ترجيح، وبهذا قال الأوزاعي وابن المنذر. وعن مالك رحمه الله روايتان: إحداهما يضعهما تحت صدره.`,
        o: `الشافعي والجمهور: تحت الصدر فوق السرة. أبو حنيفة والثوري وإسحاق وأبو إسحاق المروزي: تحت السرة. علي: روايتان كالمذهبين. أحمد: روايتان كالمذهبين وثالثة بالتخيير (وبه قال الأوزاعي وابن المنذر). مالك: روايتان، إحداهما تحت الصدر.`,
        s: `(قوله «وفيه استحباب رفع يديه»:) وقد ورد موضع رابع لرفع اليدين وهو عند القيام من الثنتين. (كشف اليدين:) لأنه أخرج يديه من الثوب فيستحب أن يكشفهما ويرفع يديه. (حذو منكبيه:) فقد قال: (سَجَدَ بَيْنَ كَفَّيْهِ) فيكون ما بين المنكبين لأن الكف عندما يكون جزء منه أمام الكتف (المنكب) والأصابع تكون بمحاذاة الرأس فبهذا يكون (سَجَدَ بَيْنَ كَفَّيْهِ) ويكون يديه على الأرض حذو منكبيه. (هذا مذهبنا المشهور وبه قال الجمهور:) قلنا أهل الحديث يقولون على الصدر وليس فوق السرة. (والتخيير:) والتخيير المقصود به ما بين فوق السرة وتحت السرة. (لا ترجيح:) هذا الكلام لما يثبت المعارض أولاً، فلما يثبت حديث تحت السرة أو فوق السرة لنستطيع معارضة الحديث الصحيح الذي فيه (على الصدر) حتى يمكن البحث في وجوه الجمع والترجيح، ولكن الصحيح أنه إذا لم يثبت فيكون الراجح هو قول واحد فقط والله أعلم. أما ما ذكره النووي رحمه الله من وضع اليد تحت الصدر وفوق السرة بهذه القيود من غير حديث صحيح، والأحاديث الواردة في فوق السرة ضعيفة، والصحيح كما في صحيح ابن خزيمة: نا أبو موسى، نا مُؤمَّل، نا سفيان، عن عاصم بن كليب، عن أبيه، عن وائل بن حجر قال: "صَلَّيْتُ مَعَ رَسُولِ اللَّهِ ﷺ، وَوَضَعَ يَدَهُ الْيُمْنَى عَلَى يَدِهِ الْيُسْرَى عَلَى صَدْرِهِ" (خز) ٤٧٩ قال الألباني: إسناده ضعيف لأن مؤملاً وهو ابن إسماعيل سيئ الحفظ لكن الحديث صحيح جاء من طرق أخرى بمعناه وفي الوضع على الصدر أحاديث تشهد له. وليس تحت الصدر وليس فوق السرة فهي الصدر، والسنة أن يضع اليمنى على ظاهر الكف اليسرى والرسغ والساعد، وإما أن يقبض على ساعده الأيسر بيده اليمنى، وإما أن يقبض فيمسك يده اليسرى بيده اليمنى، وهذا يجزئ وهذا يجزئ، حدثنا عاصم بن كليب: حدثني أبي، أن وائل بن حجر أخبره قال: "قلت لأنظرن إلى صلاة رسول الله ﷺ كيف يصلي، فنظرت إليه فقام فكبّر، ورفع يديه حتى حاذتا بأذنيه، ثم وضع يده اليمنى على كفه اليسرى والرسغ والساعد، فلما أراد أن يركع رفع يديه مثلها... ثم وضع كفه اليسرى على فخذه اليسرى وركبته اليسرى، وجعل حد مرفقه الأيمن على فخذه اليمنى، ثم قبض اثنتين من أصابعه وحلق حلقة، ثم رفع إصبعه فرأيته يحركها يدعو بها"، (س) ٨٨٩ [قال الألباني]: صحيح. أما مسألة أن يضعها على المرفق (ما يسمى عندنا الكوع) مثل البعض فهذا ليس من السنة، فالسنة أن يضع على الكف والرسغ والساعد، فكفه اليمين يكون على جزء من ظهر كفه اليسار وعلى الرسغ وأصابعه على الساعد.`,
        f: [`(ص111) التزاحم مشروط بأن يكون على السنة أن يكون الكتف في الكتف، وليس تزاحماً إلى أن يصل إلى الخروج عن الهيئة المشروعة، فالمتأخر وزاحمهم بهذه الطريقة أخطأ وتعدى لأن الأصل أن يكون الكتف في الكتف وليس الكتف أمام الكتف إلى أن يضم الناس يدها لدرجة كبيرة.`, `(ص111) «حِيَالَ أُذُنَيْهِ»: أمام أذنيه بمحاذاتها، «التَحَفَ بِثَوْبِهِ»: أي ضمه، «أَخْرَجَ يَدَيْهِ مِنَ الثَّوْبِ»: وهو مثل العباءة، «سَجَدَ بَيْنَ كَفَّيْهِ»: فرأسه (جبهته) تكون بين يديه (كفيه) ولا يلزم اللمس بل ليس من السنة الملامسة.`] },
      { q: `الجمع بين الإرسال والوضع: دليل استحباب وضع اليمنى على اليسرى، وهل يختلف بين القيام قبل الركوع وبعده؟`, p: `113–114`,
        n: `والثانية يرسلهما ولا يضع إحداهما على الأخرى. وهذه رواية جمهور أصحابه وهي الأشهر عندهم وهي مذهب الليث بن سعد. وعن مالك رحمه الله أيضًا استحباب الوضع في النفل والإرسال في الفرض، وهو الذي رجحه البصريون من أصحابه. وحجة الجمهور في استحباب وضع اليمين على الشمال: حديث وائل المذكور هنا وحديث أبي حازم عن سهل بن سعد ﵁ قال: [كان الناس يؤمرون أن يضع الرجل اليد اليمنى على ذراعيه في الصلاة] قال أبو حازم: ولا أعلمه إلا ينمي ذلك إلى النبي ﷺ. رواه البخاري وهذا حديث صحيح مرفوع كما سبق في مقدمة الكتاب. وعن هلب الطائي ﵁ قال: [كان رسول الله ﷺ يؤمنا فيأخذ شماله بيمينه] رواه الترمذي وقال حديث حسن. وفي المسألة أحاديث كثيرة. ودليل وضعها فوق السرة: حديث وائل بن حجر قال: [صليت مع رسول الله ﷺ ووضع يده اليمنى على يده اليسرى على صدره] رواه ابن خزيمة في صحيحه، وأما حديث علي ﵁ أنه قال: [من السنة في الصلاة وضع الأكف على الأكف تحت السرة] ضعيف متفق على تضعيفه رواه الدارقطني والبيهقي من رواية أبي شيبة عبد الرحمن بن إسحاق الواسطي وهو ضعيف بالاتفاق. قال العلماء: والحكمة في وضع إحداهما على الأخرى أنه أقرب إلى الخشوع ومنعهما من العبث. والله أعلم.`,
        o: `مالك: روايتان، إحداهما الإرسال (وهي رواية جمهور أصحابه وهي الأشهر عندهم، وبها قال الليث بن سعد)، ورجح البصريون من أصحابه استحباب الوضع في النفل والإرسال في الفرض.`,
        s: `(أبو عمر بن عبد البر: يضعف هذه الرواية فيقول «لا يزال مالك يقبض حتى مات».) (وضع النفل والإرسال في الفرض:) كل هذه أقوال ضعيفة لا دليل عليها. (حديث سهل:) فهذا ظاهر جداً (في الصلاة) أي في كل قيام في الصلاة يفعل ذلك وهي حجة من يقول: أنه يضع يده على صدره بعد الرفع من الركوع أيضاً لأنه في الصلاة فهو عام يشمل كل أحوال الصلاة إلا ما ورد دليل يخصصه، ففي الركوع فقد كان يضع يديه على ركبتيه وفي السجود يضعهما على الأرض وفي الجلوس يضعهما على فخذيه وركبتيه فثبت بذلك كل أوضاع الصلاة إلا هذا الموطن فمن أين أتيتم بالإرسال؟ فالذين يقولون بإرسال اليدين عند الرفع من الركوع يقولون أن هذا هو الأصل، فأين الدليل أن هذا هو الأصل؟ الناس عندما تقف الأصل أنهم يضعون أيديهم حيث شاءوا، ولو سلمنا ذلك، فنقول والأصل في الصلاة حديث سهل بن سعد: [كان الناس يؤمرون أن يضع الرجل اليد اليمنى على ذراعيه في الصلاة] أي اليسرى، فالصحيح مذهب استحباب وضع اليمنى على اليسرى على الصدر قبل الركوع وبعده لأنه لا دليل على التفرقة بين القيامين. (حديث علي:) فينبغي علينا العمل بالحديث الصحيح ونتعجب كيف قال كثير من العلماء بهذا مع ضعفه. (الحكمة:) وهذه الحكمة دليل على القياس الصحيح بقياس ما بعد الركوع على ما قبل الركوع لأن الخشوع مطلوب فيهما، ودليل آخر أن النبي ﷺ في الحديث: (ثم قال: سمع الله لمن حمده – ورفع يديه – واعتدل حتى يرجع كل عظم في موضعه معتدلاً، ثم أهوى إلى الأرض ساجداً ثم قال: الله أكبر) ((ت) ٣٠٤، (خ) ٨٢٨)، وأما رواية البخاري: (وإذا ركع أمكن يديه من ركبتيه ثم هصر ظهره فإذا رفع رأسه استوى حتى يعود كل فقار مكانه) لا تخصصها لأن هذا عام وقد ذكر بعض أفراده، وذكر بعض أفراد العام لا يخصصه لأنه موافق له في الحكم، فكل فقار داخل في عموم كلمة (كل عظم) فهذه عظام ترجع إلى موضعها قبل الركوع والله أعلى وأعلم. فأصح القولين إن شاء الله قول من يقول بمشروعية وضع اليد اليمنى على اليسرى بعد الرفع من الركوع، والمسألة فيها اجتهاد سائغ ولا ينكر فيها على المخالف.`,
        f: [] },
    ],
  },
  {
    title: `باب التشهد في الصلاة (ص115–131)`,
    items: [
      { q: `اختلاف العلماء في الأفضل من صيغ التشهد (ابن مسعود، ابن عباس، عمر، أبو موسى الأشعري) وحكمة قوله «يعلمنا التشهد كما يعلمنا السورة»`, p: `115، 117–118`,
        n: `فيه: تشهد ابن مسعود، وتشهد ابن عباس، وتشهد أبي موسى الأشعري ﵃. واتفق العلماء على جوازها كلها، واختلفوا في الأفضل منها: فمذهب الشافعي رحمه الله تعالى وبعض أصحاب مالك: أن تشهد ابن عباس أفضل لزيادة لفظة المباركات فيه وهي موافقة لقول الله ﷻ: (تحية من عند الله مباركة طيبة) ولأنه أكده بقوله: (يعلمنا التشهد كما يعلمنا السورة من القرآن). وقال أبو حنيفة وأحمد ﵄ وجمهور الفقهاء وأهل الحديث: تشهد ابن مسعود أفضل لأنه عند المحدثين أشد صحة، وإن كان الجميع صحيحًا. وقال مالك رحمه الله تعالى: تشهد عمر بن الخطاب ﵁ الموقوف عليه أفضل لأنه علّمه الناس على المنبر ولم ينازعه أحد فدل على تفضيله، وهو التحيات لله الزاكيات لله الطيبات الصلوات لله سلام عليك أيها النبي إلى آخره.`,
        o: `الشافعي وبعض أصحاب مالك: تشهد ابن عباس أفضل. أبو حنيفة وأحمد والجمهور وأهل الحديث: تشهد ابن مسعود. مالك: تشهد عمر الموقوف عليه.`,
        s: `(واتفق العلماء على جوازها كلها:) فاختيار أي نوع من أنواع التشهد هو من باب الواجب المخير، فيسعه أي نوع منها. (الأفضل:) فأي واحد منها أجزأ والخلاف في الأفضل. فألفاظ تشهد ابن مسعود لم يختلف فيها، وأما تشهد ابن عباس فطرقه المختلفة اختلفت بخلاف تشهد ابن مسعود بالحرف لم تختلف. ولذلك مذهب جمهور المحدثين أولى، ثم إن زيادة لفظ البركة ليس دليلاً على الأفضلية لأن (والصلوات الطيبات) دخل فيها البركة. وليس هذا دليلاً على الأفضلية لأن عمر ﷺ قد يعلمه الناس لأنه جائز من الجائزات، أو أنه اختار قولاً من الأقوال الجائزة فلا ينازع في ذلك. والصحيح هو قول أكثر المحدثين مع إثبات جواز أي تشهد منها وأنه من الواجب المخير كما ذكرنا.`,
        f: [`(ص115) «التشهد كفي بين كفيه» وذلك من أجل أن يُحفظه.`] },
      { q: `حكم التشهد: هل هو واجب أم سنة؟ التشهد الأول والأخير`, p: `118`,
        n: `واختلفوا في التشهد هل هو واجب أم سنة؟ فقال الشافعي رحمه الله تعالى وطائفة: التشهد الأول سنة والأخير واجب. وقال جمهور المحدثين: هما واجبان. وقال أحمد ﵁: الأول واجب والثاني فرض.`,
        o: `الشافعي وطائفة: الأول سنة والأخير واجب (بمعنى ركن). جمهور المحدثين: هما واجبان. أحمد: الأول واجب والثاني فرض (ركن).`,
        s: `(واجب عند الشافعي بمعنى أنه ركن.) (اصطلاح الإمام أحمد وأصحابه أن الثاني «ركن» وليس «فرض».)`,
        f: [] },
      { q: `القعود للتشهد الأخير: هل هو ركن؟ والتشهد الأول والأخير: واجب أم ركن؟ ومن قام عن التشهد الأول ناسيًا أو قام إلى خامسة`, p: `119`,
        n: `وقال أبو حنيفة ومالك ﵄ وجمهور الفقهاء: هما سنتان. وعن مالك رحمه الله رواية بوجوب الأخير. وقد وافق من لم يوجب التشهد على وجوب القعود بقدره في آخر الصلاة.`,
        o: `أبو حنيفة ومالك والجمهور: التشهدان سنتان. مالك (رواية): الأخير واجب. وافق من لم يوجب التشهد على وجوب القعود بقدره في آخر الصلاة.`,
        s: `وهذا هو الصحيح أن التشهدان كلاهما واجب والقعود للتشهد الأخير ركن، فأما الوجوب فلأن النبي ﷺ فرضه عليهم فلان وفلان: (عَنِ ابْنِ مَسْعُودٍ قَالَ: كُنَّا نَقُولُ فِي الصَّلاَةِ: قَبْلَ أَنْ يُفْرَضَ التَّشَهُّدُ: السَّلاَمُ عَلَى اللهِ، السَّلاَمُ عَلَى جِبْرِيلَ، وَمِيكَائِيلَ، فَقَالَ رَسُولُ اللهِ ﷺ: لاَ تَقُولُوا هَكَذَا، فَإِنَّ اللهَ هُوَ السَّلاَمُ، وَلَكِنْ قُولُوا: التَّحِيَّاتُ لِلَّهِ وَالصَّلَوَاتُ، وَالطَّيِّبَاتُ، السَّلاَمُ عَلَيْكَ أَيُّهَا النَّبِيُّ وَرَحْمَةُ اللهِ وَبَرَكَاتُهُ، السَّلاَمُ عَلَيْنَا وَعَلَى عِبَادِ اللهِ الصَّالِحِينَ، أَشْهَدُ أَنْ لاَ إِلَهَ إِلاَّ اللهُ، وَأَشْهَدُ أَنَّ مُحَمَّدًا عَبْدُهُ وَرَسُولُهُ.) سنن النسائي، قال الألباني: صحيح. والأمر الثاني: أن النبي ﷺ قال: (صلوا كما رأيتموني أصلي)؛ وأما كونه ليس بركن فلأن النبي ﷺ لم يعلمه للمسيء صلاته واجتزئ ﷺ بسجود السهو عن التشهد الأول، فلم يرجع إليه ولو كان ركناً لرجع إليه، ولا ينفي كونه ليس بركن الوجوب، فيمكن أن يكون واجباً وليس بركن، واجباً من الأمر به وبالفعل ولفظ (قَبْلَ أَنْ يُفْرَضَ التَّشَهُّدُ) وليس بركن لأن النبي ﷺ تركه ولم يعلمه للمسيء صلاته، فإذا كان جاهلاً لم يجب عليه أو كان عاجزاً عن تعلمه حتى يتعلمه أو نسيه فقرأ الفاتحة موضعه كما يقع في كثير من الأحيان فتطول الصلاة في التراويح والناس لا تدري وهم نائمون فيقولون التسبيح أو الفاتحة يقولون رب اغفر لي بدل التشهد ويسلم فيكون قد فاته التشهد ولكنه قعد له قدر التشهد، والقعود له ركن مأخوذ من رواية في المسيء صلاته وهي الرواية التي ذكرها البخاري في صحيحه قال: [ثُمَّ اسْجُدْ حَتَّى تَطْمَئِنَّ سَاجِدًا ثُمَّ ارْفَعْ حَتَّى تَطْمَئِنَّ جَالِسًا ثُمَّ اسْجُدْ حَتَّى تَطْمَئِنَّ سَاجِدًا ثُمَّ ارْفَعْ حَتَّى تَطْمَئِنَّ جَالِسًا ثُمَّ افْعَلْ ذَلِكَ فِي صَلاَتِكَ كُلِّهَا] وقال أبو أسامة في الأخير [حتى تستوي قائماً]. ولا نزاع في عدم وجوب جلسة الاستراحة ولا نزاع في عدم ركنية التشهد الأول ولا الجلوس له، فالأقوال كلها إذا تتبعناها نجد أن هناك بعض العلماء يقول بالوجوب وليس هناك أحد يقول بالركنية بمعنى أنه لو قام إلى الثالثة لزمه أن يرجع أو أنه تبطل صلاته بترك التشهد الأوسط، ولا يقول بذلك أحداً من أهل العلم فيما نعلم، وهذا الإجماع صارف لحديث البخاري الذي ذكرناه في الجلسة التي بعد كل ركعة، فهو صارف من الركنية إلى الاستحباب في جلسة الاستراحة في الأولى والثالثة، ومن الركنية إلى الوجوب في الركعة الثانية، ويبقى الحديث على محمله في جلسة التشهد الأخير فهو ركن من أركان الصلاة لابد أن يجلس، ولذا لو قام إلى الخامسة فلا يكملها إذا تذكر أو ذُكر فليجلس فوراً لأنه قام إلى ركن وترك واجباً فلا يرجع إلى الواجب فقد فات محله، إنما محله إذا رفع رأسه من السجدة ولم يصل إلى القيام ولم يتلبس بالركن من الركعة الثالثة، أما إذا قام من التشهد الأخير إلى الخامسة فهذا القيام ليس بواجب ولا بمستحب ولا بجائز والجلوس للتشهد الأخير ركن، فوجب أن يترك هذا الذي ليس بجائز ولا بمستحب ولا بواجب إلى ما هو ركن، وهذا هو الفرق فيما إذا قام إلى الخامسة وبين ما إذا قام إلى الثالثة ناسياً التشهد الأوسط، فإنه إذا قام إلى الثالثة يستكمل صلاته ويسجد للسهو بدلاً من التشهد الأوسط ويجزئ عنه، وأما إذا قام إلى الخامسة فيجب عليه الرجوع فوراً بمجرد أن يتذكر أو يعلم. والله أعلى وأعلم.`,
        f: [`(ص119) التي في قوله: (أَشْهَدُ أَنْ لاَ إِلَهَ إِلاَّ اللَّهُ وَأَشْهَدُ أَنَّ مُحَمَّدًا عَبْدُهُ وَرَسُولُهُ) وهذا هو أصل التشهد، والذي قبله كالمقدمة له، ولكن كل كلماته بأي صيغة وردت واجبة.`] },
      { q: `معنى «إن الله هو السلام»، ومعنى «التحيات»، وسبب تسمية التشهد`, p: `120`,
        n: `وأما ألفاظ الباب ففيه: لفظة التشهد: سُمّيت بذلك للنطق بالشهادة بالوحدانية والرسالة. وأما قوله ﷺ: (إن الله هو السلام): فمعناه أن السلام اسم من أسماء الله تعالى ومعناه السالم من النقائص وسمات الحدوث ومن الشريك والند، وقيل المسلِّم أولياءه وقيل المسلَّم عليهم وقيل غير ذلك. وأما التحيات: فجمع تحية وهي الملك وقيل البقاء وقيل العظمة وقيل الحياة وإنما قيل التحيات بالجمع لأن ملوك العرب كان كل واحد منهم تحيِّيه أصحابه بتحية مخصوصة فقيل جميع تحياتهم لله تعالى وهو المستحق لذلك حقيقة.`,
        o: `السلام: السالم من النقائص (الأشهر)، أو المسلِّم أولياءه، أو المسلَّم عليهم. التحيات: الملك أو البقاء أو العظمة أو الحياة.`,
        s: `الأشهر الأول أن الله هو السلام أي الذي سلم من كل نقص وعيب وند وشريك ﷻ، فإذا قلنا (السلام على الله) فأصل كلمة السلام أنك تُسلم على الشخص وتنبهه أنه سوف يسلم منك وأنك لن تصل إليه بأذى وهذا لا يتصور في حق الله لأن الله هو السلام فلن يضره العباد ولن ينفعوه فلا يتصور أن يسلم العباد على الله ﷻ لأنه لا يتصور أن يضروه ﷻ فيخبروه بأنه منهم في أمان وسلام لأنهم مهما فعلوا فلن يُنقصوه ﷻ شيئاً ولن يضروه ﷻ شيئاً ولذلك لا يتصور أن يسلموا على الله، لأنهم مهما صنعوا فلن يضروا الله شيئاً؛ أما البشر قد يصل منك إليهم ضرر أو إيذاء بقدرة الله ﷻ وتقديره، فلذا شُرع أن تسلم على المسلمين فتقول السلام عليكم أنتم مني في سلام، لن يصيبكم مني أذىً ولا ضرر. (التحيات:) فالتحيات هي أنواع التعظيم وإثبات الملك والبقاء والعظمة لله ﷻ وكلها معاني متلازمة وصحيحة والله ﷻ أحق بها.`,
        f: [] },
      { q: `معنى «المباركات والزاكيات» و«الصلوات» و«الطيبات»، وحذف الواو، ومعنى «السلام عليك أيها النبي» و«السلام عليكم»`, p: `121`,
        n: `والمباركات والزاكيات: في حديث عمر ﵁ بمعنى واحد والبركة كثرة الخير وقيل النماء وكذا الزكاة أصلها النماء والصلوات هي الصلوات المعروفة وقيل الدعوات والتضرع وقيل الرحمة: أي الله المتفضل بها. والطيبات: أي الكلمات الطيبات. وقوله في حديث ابن عباس (التحيات المباركات الصلوات الطيبات): تقديره والمباركات والصلوات والطيبات، كما في حديث ابن مسعود وغيره ولكن حُذفت الواو اختصارًا وهو جائز معروف في اللغة. ومعنى الحديث أن التحيات وما بعدها مستحقة لله تعالى ولا تصلح حقيقتها لغيره. وقوله (السلام عليك أيها النبي ورحمة الله وبركاته السلام علينا وعلى عباد الله الصالحين) وقوله في آخر الصلاة (السلام عليكم): فقيل معناه: التعويذ بالله والتحصين به سبحانه وتعالى فإن السلام اسم له سبحانه وتعالى تقديره [الله عليكم حفيظ وكفيل] كما يقال الله معك أي بالحفظ والمعونة واللطف، وقيل معناه: السلامة والنجاة لكم، ويكون مصدرًا كاللذاذة واللذاذ كما قال الله تعالى: (فسلام لك من أصحاب اليمين).`,
        o: `السلام: التعويذ بالله والتحصين به (الله عليكم حفيظ وكفيل)، أو السلامة والنجاة لكم (مصدر).`,
        s: `وهذا هو الأقرب (أي القول بأن معناه السلامة والنجاة) لأن أصل السلام: السلامة من النقص.`,
        f: [`(ص121) وبهذا يؤكد العبد عندما يقول (والصلوات الطيبات) أنه يصلي لله ﷻ مخلصاً، وقيل الصلوات أي الرحمة.`, `(ص121) «حذفت الواو»: وهو أن يعطف بدون أداة العطف.`] },
      { q: `إثبات الألف واللام وحذفهما في «السلام عليك» وفي سلام التحليل في آخر الصلاة`, p: `122`,
        n: `واعلم أن السلام الذي في قوله: (السلام عليك أيها النبي) (السلام علينا وعلى عباد الله الصالحين) يجوز فيه حذف الألف واللام فيقال [سلام عليك أيها النبي وسلام علينا] ولا خلاف في جواز الأمرين هنا ولكن الألف واللام أفضل وهو الموجود في روايات صحيحي البخاري ومسلم. وأما الذي في آخر الصلاة وهو سلام التحليل، فاختلف أصحابنا فيه: فمنهم من جوّز الأمرين فيه هكذا ويقول الألف واللام أفضل. ومنهم من أوجب الألف واللام لأنه لم يُنقل إلا بالألف واللام ولأنه تقدم ذكره في التشهد فينبغي أن يعيده بالألف واللام ليعود التعريف إلى سابق كلامه كما يقول جاءني رجل فأكرمت الرجل.`,
        o: `بعض الشافعية: يوجب الألف واللام في سلام التحليل. ومنهم من جوّز الأمرين والألف واللام أفضل.`,
        s: `(ليعود التعريف إلى سابق كلامه:) ليكون نفس الرجل الأول؛ والأظهر والله أعلم قول من يجوز الأمرين والألف واللام أفضل لأنها الواردة، ولكن قول النبي ﷺ: (وتحليلها التسليم) فأي نوع من أنواع التسليم جاز وقد قال الله ﷻ: (قالوا سلاماً) فدل ذلك على أن سلام من غير ألف ولام تحية معتبرة فطالما ذكرها فقد تحلل من صلاته، ولكن الأفضل أن يقول ما ورد وأن يقول بالألف واللام في الأولى والثانية.`,
        f: [`(ص122) فمن صيغ العموم الألف واللام التي يراد بها الجنس، فيكون كل عبد لذلك أكده بقوله: (كُلَّ عَبْدٍ لِلَّهِ صَالِحٍ).`] },
      { q: `الدعاء بعد التشهد الأخير وقبل السلام: هل هو مستحب؟ وهل يجوز الدعاء بما شاء من أمر الدنيا والآخرة؟ وما حكم التعوذ من الأربع؟`, p: `123`,
        n: `قوله ﷺ: (ثم يتخير من المسألة ما شاء): فيه استحباب الدعاء في آخر الصلاة قبل السلام. وفيه أنه يجوز الدعاء بما شاء من أمور الآخرة والدنيا ما لم يكن إثمًا: وهذا مذهبنا ومذهب الجمهور؛ وقال أبو حنيفة رحمه الله تعالى لا يجوز إلا بالدعوات الواردة في القرآن والسنة.`,
        o: `أبو حنيفة: لا يجوز إلا بالدعوات الواردة في القرآن والسنة. وقال بعض الظاهرية وكثير من التابعين ومن السلف بوجوب التعوذ من الأربع وهو مذهب طاووس.`,
        s: `لقوله: (ثُمَّ يَتَخَيَّرُ مِنَ الْمَسْأَلَةِ مَا شَاءَ) فردها إلى مشيئته وهي عامة، والألف واللام (المسألة) عامة، فيتخير ما شاء. والصحيح مذهب الجمهور ولكن الأفضل ما ورد في الكتاب والسنة. وقال بعض الظاهرية بوجوبه (التعوذ من الأربع) وقال كثير من التابعين ومن السلف بوجوب التعوذ من الأربع وهو مذهب طاووس وهو قول قوي من جهة الدليل.`,
        f: [] },
      { q: `الصلاة على النبي ﷺ في التشهد الأخير: واجبة أم ركن؟ والصلاة عليه في التشهد الأول`, p: `123–124`,
        n: `واستدل به جمهور العلماء على أن الصلاة على النبي ﷺ في التشهد الأخير ليست واجبة. ومذهب الشافعي وأحمد وإسحاق وبعض أصحاب مالك رحمه الله تعالى وجوبها في التشهد الأخير فمن تركها بطلت صلاته، وقد جاء في رواية من هذا الحديث في غير مسلم زيادة [فإذا فعلت ذلك فقد تمت صلاتك] ولكن هذه الزيادة ليست صحيحة عن النبي ﷺ.`,
        o: `الجمهور: ليست واجبة. الشافعي وأحمد وإسحاق وبعض المالكية: واجبة في التشهد الأخير ومن تركها بطلت صلاته.`,
        s: `الصحيح أنها مذهب أحمد وأنها واجبة وإنما يبطل صلاة من تركها عمداً وليست ركناً عند أحمد ولا إسحاق، فالصحيح أن الصلاة على النبي ﷺ واجبة وليست بركن لورود الأمر بها (صَلُّوا عَلَيْهِ وَسَلِّمُوا تَسْلِيمًا) وقول النبي ﷺ: (فَكَيْفَ الصَّلاَةُ عَلَيْكَ؟) قَالَ: «قُولُوا: اللَّهُمَّ صَلِّ عَلَى مُحَمَّدٍ» المعجم الأوسط وصححه ابن خزيمة. فهذا الأمر للوجوب وإنما عدم ذكره في هذا الحديث وفي حديث المسيء صلاته دليل على عدم الركنية لا على عدم الوجوب.`,
        f: [`(ص124) ولذلك نقول الصحيح أن هذه الرواية فيها سكوت عن الصلاة على النبي ﷺ وليس فيها إسقاطها بالكلية أو عدم وجوبها فالصحيح أنها واجبة وليست بركن وظاهر الأدلة وجوبها عند ذكر النبي ﷺ في التشهدين، لكن قلة من أهل العلم توجب الصلاة على النبي ﷺ بعد التشهد الأول وإن كان هو أقوى من جهة الدليل أن يقول: اللهم صل على محمد وعلى آل محمد في التشهد الأول كما يقوله في التشهد الأخير، ولو قام الإمام مسرعاً يجزئه أن يقول: اللهم صل على محمد وعلى آل محمد فقط، بل هذا الذي يجزئه أيضاً في التشهد الأخير ولكن الأفضل أن يصلي على النبي ﷺ بما ورد باللفظ، لكن الوجوب في الأمر (صَلُّوا عَلَيْهِ وَسَلِّمُوا تَسْلِيمًا) يجزئ باللهم صل على محمد وعلى آل محمد.`, `(ص124) هناك قدر منها واجب وقدر منها مستحب كما سيأتي إن شاء الله. (تعليقًا على «أقيموا صفوفكم»).`] },
      { q: `حكم قول «السلام عليك أيها النبي» في التشهد بعد وفاة النبي ﷺ (وما يراه الألباني)`, p: `124–125`,
        n: NO_N,
        o: `الألباني: يقول في التشهد «السلام على النبي» بعد وفاته ﷺ وأن «السلام عليك أيها النبي» لم يكن واجبًا بعد وفاته.`,
        s: `الشيخ الألباني يقول في التشهد السلام على النبي ﷺ: الصحيح أن هذا جائز وهذا جائز، وليس أن هذا واجباً بعد وفاة النبي ﷺ، كل أهل العلم يقولون: (السلام عليك أيها النبي) والصحابة علموا الناس ذلك، وعمر بن الخطاب ﷺ علم الناس على المنبر أن يقولوا (السلام عليك أيها النبي) أو (سلامٌ عليك أيها النبي) كما قرأناها الآن ولأن غياب النبي ﷺ في حياته رغم بعدهم عنه كانوا يقولون (السلام عليك أيها النبي) ومثله بعد وفاته ﷺ، فالخطاب للنبي ﷺ على الغيب في حياته وبعد وفاته خصوصية بصيغة (السلام عليك أيها النبي) أما غيره من الناس فإنها يخاطبون عند قبورهم بالسلام فيقال (السلام عليكم دار قوم مؤمنين) والله أعلم. فالصحيح أن (السلام على النبي) وجهٌ جائز مشروع كما أن (السلام عليك أيها النبي) وجهٌ جائز مشروع، وليس أنه يلزم السلام على النبي فقط.`,
        f: [] },
      { q: `حكم صلاة الجماعة: فرض كفاية أم فرض عين أم سنة أم شرط؟ (مذاهب أربعة)`, p: `125–126`,
        n: `قوله ﷺ: (ثم ليؤمكم أحدكم) فيه الأمر بالجماعة في المكتوبات، ولا خلاف في ذلك ولكن اختلفوا في أنه أمر ندب أم إيجاب على أربعة مذاهب: ١. فالراجح في مذهبنا وهو نص الشافعي رحمه الله تعالى وقول أكثر أصحابنا أنها فرض كفاية إذا فعله من يحصل به إظهار هذا الشعار سقط الحرج عن الباقين وإن تركوه كلهم أثموا كلهم. ٢. وقالت طائفة من أصحابنا هي سنة. ٣. وقال ابن خزيمة من أصحابنا هي فرض عين لكن ليست بشرط فمن تركها وصلى منفردًا بلا عذر أثم وصحت صلاته. ٤. وقال بعض أهل الظاهر هي شرط لصحة الصلاة. وقال بكل قول من الثلاثة المتقدمة طوائف من العلماء وستأتي المسألة في بابها إن شاء الله تعالى.`,
        o: `الشافعي وأكثر أصحابه: فرض كفاية. طائفة من الشافعية: سنة. ابن خزيمة: فرض عين وليست بشرط. بعض أهل الظاهر: شرط لصحة الصلاة (وهو وجه عند الحنابلة، وترجيح ابن القيم).`,
        s: `ظاهر الحديث وهو حجة جمهور أهل الحديث على وجوب صلاة الجماعة لأنه أمر (ثم ليؤمكم أحدكم). وهذا ضعيف من جهة الدليل (أي القول بفرض الكفاية)، فيقال لهم: ألم يكن هذا الفرض الذي ذكرتموه فرض كفاية قائماً بالنبي ﷺ وخيرة أصحابه؟ فإذا لم يكن قائماً فبمن يقوم إذاً؟ ولو كان قائماً بهم فقد سقط الحرج عن من صلوا في البيوت ففي صحيح مسلم: عَنْ أَبِي هُرَيْرَةَ قَالَ: قَالَ رَسُولُ اللَّهِ ﷺ: « إِنَّ أَثْقَلَ صَلاَةٍ عَلَى الْمُنَافِقِينَ صَلاَةُ الْعِشَاءِ وَصَلاَةُ الْفَجْرِ وَلَوْ يَعْلَمُونَ مَا فِيهِمَا لأَتَوْهُمَا وَلَوْ حَبْوًا وَلَقَدْ هَمَمْتُ أَنْ آمُرَ بِالصَّلاَةِ فَتُقَامَ ثُمَّ آمُرَ رَجُلاً فَيُصَلِّيَ بِالنَّاسِ ثُمَّ أَنْطَلِقَ مَعِي بِرِجَالٍ مَعَهُمْ حُزَمٌ مِنْ حَطَبٍ إِلَى قَوْمٍ لاَ يَشْهَدُونَ الصَّلاَةَ فَأُحَرِّقَ عَلَيْهِمْ بُيُوتَهُمْ بِالنَّارِ ». وقال لابن أم مكتوم وهو أعمى وقد سقط عنه هذا الفرض لو كان فرض كفاية بقيام من يقوم به فَفِي صَحِيحِ مُسْلِمٍ عَنْ أَبِي هُرَيْرَةَ قَالَ أَتَى النَّبِيَّ ﷺ رَجُلٌ أَعْمَى فَقَالَ يَا رَسُولَ اللَّهِ إِنَّهُ لَيْسَ لِي قَائِدٌ يَقُودُنِي إِلَى الْمَسْجِدِ. فَسَأَلَ رَسُولَ اللَّهِ ﷺ أَنْ يُرَخِّصَ لَهُ فَيُصَلِّيَ فِي بَيْتِهِ فَرَخَّصَ لَهُ فَلَمَّا وَلَّى دَعَاهُ فَقَالَ: « هَلْ تَسْمَعُ النِّدَاءَ بِالصَّلاَةِ ». فَقَالَ نَعَمْ. قَالَ: « فَأَجِبْ ». فدل ذلك على أنه ليس فرض كفاية لأنه لو كان كذلك لسقط عن ابن أم مكتوم لأنه قد قام به النبي ﷺ وأصحابه. وهذا هو الصحيح، فإن صلاة الجماعة فرض على الرجال البالغين إذا لم يكن هناك عذر، وليست بشرط في صحة الصلاة. (قول بعض أهل الظاهر:) وهو قول لبعض أهل الحديث ووجه عند الحنابلة وهو ترجيح ابن القيم رحمه الله، والصحيح والله أعلى وأعلم أنها واجبة وليست بركن وليست بشرط في صحة الصلاة. (ما ذكرنا هو القول الثالث وأنها فرض عين على الرجال البالغين.)`,
        f: [`(ص125) ظاهر الحديث وهو حجة جمهور أهل الحديث على وجوب صلاة الجماعة لأنه أمر (ثم ليؤمكم أحدكم).`] },
      { q: `متى يكبّر المأموم تكبيرة الإحرام؟ (ومعنى «فإذا كبر فكبروا»، ومن كبّر قبل تمام تكبير الإمام)`, p: `126`,
        n: `قوله ﷺ: (فإذا كبّر فكبّروا) فيه أمر المأموم بأن يكون تكبيره عقب تكبير الإمام ويتضمن مسألتين: إحداهما: أنه لا يكبّر قبله ولا معه بل بعده فلو شرع المأموم في تكبيرة الإحرام ناويًا الاقتداء بالإمام وقد بقي للإمام منها حرف لم يصح إحرام المأموم بلا خلاف لأنه نوى الاقتداء بالإمام بمن لم يصر إمامًا بل بمن سيصير إمامًا إذا فرغ من التكبير. والثانية: أنه يُستحب كون تكبيرة المأموم عقب تكبيرة الإمام ولا يتأخر فلو تأخر جاز وفاته كمال فضيلة تعجيل التكبير.`,
        o: NO_O,
        s: `(قوله ﷺ: «فإذا كبروا فكبروا») فالفاء تقتضي التعقيب.`,
        f: [] },
      { q: `التأمين: متى يؤمّن المأموم؟ (مع تأمين الإمام لا بعده)`, p: `127`,
        n: `قوله ﷺ: (وإذا قال غير المغضوب عليهم ولا الضالين فقولوا آمين) فيه دلالة ظاهرة لما قاله أصحابنا وغيرهم أن تأمين المأموم يكون مع تأمين الإمام لا بعده فإذا قال الإمام [ولا الضالين] قال الإمام والمأموم معًا [آمين]. وتأولوا قوله ﷺ: (إذا أمّن الإمام فأمّنوا) قالوا معناه: إذا أراد التأمين، ليجمع بينه وبين هذا الحديث، وهو يريد التأمين في آخر قوله [ولا الضالين] فيعقب إرادته تأمينه وتأمينكم معًا. وفي آمين لغتان المد والقصر والمد أفصح والميم خفيفة فيها ومعناه استجب وسيأتي إن شاء الله تعالى تمام الكلام في التأمين وما يتعلق به في بابه حيث ذكره مسلم.`,
        o: NO_O,
        s: `(أي أمنوا مع تأمينه حيث أراد التأمين، وهذا هو الصحيح.)`,
        f: [] },
      { q: `متابعة الإمام في الركوع: متى يركع المأموم؟ ومعنى «فتلك بتلك»`, p: `127`,
        n: `قوله ﷺ: (وإذا كبر وركع فكبروا واركعوا فإن الإمام يركع قبلكم ويرفع قبلكم فقال رسول الله ﷺ فتلك بتلك) معناه: اجعلوا تكبيركم للركوع وركوعكم بعد تكبيره وركوعه وكذلك رفعكم من الركوع يكون بعد رفعه. ومعنى: (تلك بتلك) أن اللحظة التي سبقكم الإمام بها في تقدمه إلى الركوع تنجبر لكم بتأخيركم في الركوع بعد رفعه لحظة فتلك اللحظة بتلك اللحظة وصار قدر ركوعكم كقدر ركوعه وقال مثله في السجود.`,
        o: NO_O,
        s: `وهذا دليل على أن المأموم يبدأ الحركة بعد أن يُتم الإمام حركته، فعندما يستقر الإمام راكعاً يبدأ المأموم في الركوع فلا يساويه.`,
        f: [] },
      { q: `هل يجمع المأموم بين «سمع الله لمن حمده» و«ربنا لك الحمد»؟ وهل يُستحب للإمام الجهر بـ«سمع الله لمن حمده»؟`, p: `128`,
        n: `وقوله ﷺ: (وإذا قال سمع الله لمن حمده فقولوا اللهم ربنا لك الحمد يسمع الله لكم) فيه دلالة لما قاله أصحابنا وغيرهم أنه يُستحب للإمام الجهر بقوله [سمع الله لمن حمده] وحينئذٍ يسمعونه فيقولون. وفيه دلالة لمذهب من يقول لا يزيد المأموم على قوله [ربنا لك الحمد] ولا يقول معه [سمع الله لمن حمده]، ومذهبنا أنه يجمع بينهما الإمام والمأموم والمنفرد لأنه ثبت أنه ﷺ جمع بينهما وثبت أنه قال: (صلوا كما رأيتموني أصلي)، وسيأتي بسط الكلام فيه في بابه إن شاء الله تعالى.`,
        o: `أبو حنيفة وأحمد (في رواية) وغيرهما: المأموم يقول «ربنا لك الحمد» فقط ولا يقول «سمع الله لمن حمده». الشافعية: يجمع بينهما الإمام والمأموم والمنفرد.`,
        s: `وهذا هو الصحيح لظاهر هذا الحديث فإنه قال: (وَإِذَا قَالَ سَمِعَ اللَّهُ لِمَنْ حَمِدَهُ فَقُولُوا اللَّهُمَّ رَبَّنَا لَكَ الْحَمْدُ) وهناك رواية في الصحيح فيها الجمع بين اللهم وبين الواو خلافاً لابن القيم ففي صحيح البخاري عن أبي هريرة قال: [كَانَ النَّبِيُّ ﷺ إِذَا قَالَ سَمِعَ اللَّهُ لِمَنْ حَمِدَهُ قَالَ اللَّهُمَّ رَبَّنَا وَلَكَ الْحَمْدُ]. حيث قال في الزاد: ليس هناك رواية فيها الجمع بين اللهم وبين الواو، بل الصحيح أن أكملها أن يقول: اللهم ربنا ولك الحمد، وسيأتي الكلام عليها. فقد جمع بينهما كإمام أو كمنفرد، فأين المأموم؟! والحديث حجة إلا فيما استثناه الدليل وقد قال: «وَإِذَا قَرَأَ فَأَنْصِتُوا» وقد قلتم [لا يقرأ إلا الفاتحة] فقد أقررتم أن يترك المأموم بعض أقوال إمامه، فإذا كان هذا بيان موطن متى يقول المأموم [اللَّهُمَّ رَبَّنَا وَلَكَ الْحَمْدُ] لكي يتوافق قوله مع قول الملائكة، ففي صحيح مسلم عن أبي هريرة أن رسول الله ﷺ قال: «إِذَا قَالَ الإِمَامُ سَمِعَ اللَّهُ لِمَنْ حَمِدَهُ. فَقُولُوا اللَّهُمَّ رَبَّنَا لَكَ الْحَمْدُ. فَإِنَّهُ مَنْ وَافَقَ قَوْلُهُ قَوْلَ الْمَلاَئِكَةِ غُفِرَ لَهُ مَا تَقَدَّمَ مِنْ ذَنْبِهِ». فلو قال المأموم (سمع الله لمن حمده) لوقع (اللَّهُمَّ رَبَّنَا لَكَ الْحَمْدُ) من المأموم في وقت غير وقت الإمام فقد وقعت مختلفة ففي لحظة قول الإمام (اللَّهُمَّ رَبَّنَا لَكَ الْحَمْدُ) يقول المأموم (سَمِعَ اللَّهُ لِمَنْ حَمِدَهُ) ويقول (اللَّهُمَّ رَبَّنَا لَكَ الْحَمْدُ) بعده فتقع مختلفة فمن يوافق منهما قَوْلُهُ قَوْلَ الْمَلاَئِكَةِ؟، فإذا قلنا أن هذا مثل قول (ولا الضالين. آمين) فيقولوا آمين مع تأمين الإمام، فإذا يقولوا (اللَّهُمَّ رَبَّنَا لَكَ الْحَمْدُ) مع تحميد الإمام ليوافق قوله قول الملائكة ويكون المجموع الإمام والمأموم والملائكة يقولون (اللَّهُمَّ رَبَّنَا لَكَ الْحَمْدُ) في وقت واحد. والله أعلم.`,
        f: [`(ص128) فهذا هو الصحيح لظاهر هذا الحديث.`, `(ص128) فقد جمع بينهما كإمام أو كمنفرد، فأين المأموم؟!`] },
      { q: `«ربنا لك الحمد» و«ربنا ولك الحمد»: إثبات الواو وحذفها`, p: `129`,
        n: `قوله: (ربنا لك الحمد) هكذا هو هنا بلا واو وفي غير هذا الموضع (ربنا ولك الحمد) وقد جاءت الأحاديث الصحيحة بإثبات الواو وبحذفها وكلاهما جاءت به روايات كثيرة والمختار أنه على وجه الجواز وأن الأمرين جائزان ولا ترجيح لأحدهما على الآخر، ونقل القاضي عياض اختلافًا عن مالك رحمه الله تعالى وغيره في الأرجح منهما وعلى إثبات الواو يكون قوله [ربنا] متعلقًا بما قبله تقديره سمع الله لمن حمده يا ربنا فاستجب حمدنا ودعاءنا ولك الحمد على هدايتنا لذلك.`,
        o: `مالك وغيره: اختلاف في الأرجح (إثبات الواو أو حذفها). المختار عند النووي: جائزان ولا ترجيح.`,
        s: `ونحن نرجح إضافة الواو فيقول (اللَّهُمَّ رَبَّنَا وَلَكَ الْحَمْدُ) ففيه إثبات الربوبية وجملة أخرى وهي الحمد فهي أكمل معنى والله أعلم. وإن فعل أي الأمرين أو فعله لبيان الجواز أجزئ.`,
        f: [] },
      { q: `الاستدلال بقوله «وإذا كان عند القعدة فليكن من أول قول أحدكم التحيات» على أن لا تُقال البسملة في أول التشهد`, p: `129`,
        n: `قوله: (وإذا كان عند القعدة فليكن من أول قول أحدكم التحيات) استدل جماعة بهذا على أنه يقول في أول جلوسه التحيات ولا يقول بسم الله وليس هذا الاستدلال بواضح لأنه قال فليكن من أول ولم يقل فليكن أول والله أعلم.`,
        o: NO_O,
        s: `الصحيح أن هذا الاستدلال صحيح من جهة أن (بسم الله) لم ترد، فطالما أنها لم ترد في شيء من الروايات فلا يقول (بسم الله) في التحيات، وإنما يبدأ بلفظ التحيات.`,
        f: [] },
      { q: `قول مسلم «ليس كل شيء عندي صحيح وضعته ها هنا إنما وضعت ها هنا ما أجمعوا عليه» (معنى الإجماع عنده وهل استوعب الصحيح؟)`, p: `129–130`,
        n: `قوله: (وفي حديث جرير عن سليمان التيمي عن قتادة من الزيادة وإذا قرأ فأنصتوا) هكذا (قال أبو إسحاق: قال أبو بكر ابن أخت أبي النضر في هذا الحديث. فقال مسلم: تريد أحفظ من سليمان فقال له أبو بكر فحديث أبي هريرة فقال هو صحيح يعني وإذا قرأ فأنصتوا. فقال لم لم تضعه ها هنا؟ قال: ليس كل شيء عندي صحيح وضعته ها هنا إنما وضعت ها هنا ما أجمعوا عليه.)`,
        o: NO_O,
        s: `يريد مسلم أن يقول أن هذه الزيادة (وإذا قرأ فأنصتوا) ثابتة، وحديث (وإذا قرأ فأنصتوا) حديث أبي موسى الأشعري... فحديث أبو هريرة لم يخرجه مسلم في صحيحه ولكن أخرج رواية أبي موسى، ولكنه صحح رواية أبي هريرة. [قال: ليس كل شيء عندي صحيح وضعته ها هنا إنما وضعت ها هنا ما أجمعوا عليه]: فهذا كلام مسلم رحمه الله الذي جعل كتابه بهذه المنزلة، وهو أنه ليس كل شيء صححه فهو موجود في الصحيح، فهذا دليل على أنه لم يستوعب ولم يرد استيعاب الصحيح، وهذا رد على من يقول: أننا نعمل بما في الصحيحين فقط ولا نبحث عن غيرهما؛ فإن الإمام البخاري قد صحح أحاديث كثيرة نقلها الترمذي عنه وصحح هو أحاديث في جزء القراءة وفي غيره من كتبه، فصحح أحاديث لم يُخرجها في الصحيح، فدل ذلك على أنه لم يرد هو ولا مسلم أن يستوعبا الصحيح، بمعنى أنهم لم يقولوا أن الأحاديث الصحيحة هي التي في الكتابين فقط، بل فيها وفي غير هذين الكتابين ولكنهم وضعوا فيها أعلى درجات الصحة. ولكن كيف يجمع بين هذا وبين أن هناك أحاديث في مسلم لم يجمع عليها وقد استدركت عليه، ولكن معظم الأحاديث مجمعٌ عليها متلقاه بالقبول؟ والجواب: أن مذهب مسلم أن ما اجمعوا عليه يرى أنه لا ينبغي أن يختلف فيه، وبالتأكيد أنه اطلع على الخلاف في بعض الرواة وفي بعض الأحاديث ولكنه رأى أنه خلاف لا ينبغي أن يختلف. والله أعلم، وما لم يستدرك عليه هو فعلًا محل إجماع، هو البخاري. ولذلك نقول الذي يطعن في أحاديث البخاري ومسلم غير التي استدركت عليها مخالف للإجماع ومبتدع ضال، وذلك لأن مسلم نقل في صحيحه ما أجمعوا عليه، وسوف نستثني من عبارة مسلم فقط المستدركات التي استدركت على البخاري ومسلم، وفضلاً أن الأمة كلها تلقت أحاديثهما بالقبول، فهذا إجماع من يخالفه مطعون فيه.`,
        f: [`(ص130) (يريد مسلم أن يقول إن هذه الزيادة «وإذا قرأ فأنصتوا» ثابتة؛ حديث أبي موسى الأشعري.)`] },
      { q: `زيادة «وإذا قرأ فأنصتوا» في حديث التشهد: هل هي شاذة؟ وما معنى الشذوذ والمخالفة عند المحدثين؟ (وتفاوت درجة الاستدراك على الصحيحين)`, p: `131–132`,
        n: `واعلم أن هذه الزيادة وهي قوله: (وإذا قرأ فأنصتوا) مما اختلف الحفاظ في صحته فروى البيهقي في السنن الكبير عن أبي داود السجستاني أن هذه اللفظة ليست بمحفوظة وكذلك رواه عن يحيى بن معين وأبي حاتم الرازي والدارقطني والحافظ أبي علي النيسابوري شيخ الحاكم قال البيهقي: [قال أبو علي: الحافظ هذه اللفظة غير محفوظة قد خالف سليمان التيمي فيها جميع أصحاب قتادة واجتماع هؤلاء الحفاظ على تضعيفها مقدم على تصحيح مسلم لا سيما ولم يروها مسندة في صحيحه والله أعلم].`,
        o: `أبو داود وابن معين وأبو حاتم والدارقطني وأبو علي النيسابوري: اللفظة غير محفوظة (خالف سليمانُ التيمي جميعَ أصحاب قتادة). مسلم: صحيحة.`,
        s: `هذا الكلام فيه نظر، فإن من ضعفها قال لم يروها غير سليمان حتى ولو كان ذلك لا يستوجب التضعيف، وهذه اللفظة أولاً مروية من أكثر من وجه من حديث أبي هريرة ومن حديث أبي موسى فهذا شاهد له على الصحة، ثم ليس الشذوذ أن يروي الراوي ما لم يروِ غيره، وإنما أن يروي مخالفاً غيره وهذا هو الصحيح، وكثير من المتقدمين يجعل عدم رواية الحفاظ للفظة قادحاً في رواية أحدهم لها، والصحيح الذي عليه عامة علماء الحديث أن الشذوذ هو رواية الثقة مخالفاً لما رواه غيره وليس أنه يروي مالم يروِ غيره، والمخالفة تكون فهم لم يقولوا (وَإِذَا قَرَأَ فَأَنْصِتُوا) ولم يقولوا: وإذا قرأ فاقرأوا، فتكون المخالفة إذا قالوا: وإذا قرأ فاقرأوا، ولكن إذا سكتوا تماماً عنها فليس هذا بشذوذ، بمعنى أن لو أن الحفاظ قالوا أن الراوي قال [تسعة] وواحد قال [ثمانية] فهذا قادح وهذا يكون الشذوذ، ولكنهم لو لم يذكروا عدد وقالوا أن واحداً قال [تسعة] أو [ثمانية] فهذا لا يكون قادحاً والله أعلم. وكما قلنا أنها ليست علة وهي زيادة ثقة وزيادة الثقة مقبولة. وهذا موضع لا ينبغي أن يختلف فيه، وللعلم فإن عامة الأحاديث التي أخذت على البخاري ومسلم ليست على متونها وإنما على أسانيدها، والتي في متونها كلام يسيرٌ لا تتجاوز أصابع اليد الواحدة أو الاثنين على الأكثر في مسلم، فالذي استدركه الدارقطني مثلاً معظمه في الأسانيد مع إثبات صحة الحديث.`,
        f: [`(ص131) فضلاً أنه غير مخالف بل روى ما لم يرِ غيره فهي زيادة ثقة وزيادة الثقة مقبولة.`, `(ص131) فكما قلنا ينبغي أن تكون محل إجماع. (تعليقًا على جواب مسلم عن سؤال تضعيف الحديث.)`, `(ص132) وقول مسلم: [حدثنا إسحاق بن إبراهيم وابن أبي عمر عن عبد الرزاق عن معمر عن قتادة بهذا الإسناد وقال في الحديث: «فإن الله قضى على لسان نبيه ﷺ سمع الله لمن حمده»] وهي رواية أبي موسى: [وإذا قال سمع الله لمن حمده فقولوا اللهم ربنا لك الحمد يسمع الله لكم فإن الله تبارك وتعالى قال على لسان نبيه ﷺ سمع الله لمن حمده.] هل هناك اختلاف؟ لأن الله ﷻ قال ذلك وقوله قضاء.`] },
    ],
  },
  {
    title: `باب الصلاة على النبي ﷺ بعد التشهد (ص132–141)`,
    items: [
      { q: `حكم الصلاة على النبي ﷺ بعد التشهد الأخير: سنة أم واجبة؟ (وهل الواجب الصلاة على الآل؟)`, p: `134–135`,
        n: `اعلم أن العلماء اختلفوا في وجوب الصلاة على النبي ﷺ عقب التشهد الأخير في الصلاة: فذهب أبو حنيفة ومالك رحمهما الله تعالى والجماهير إلى أنها سنة لو تركت صحت الصلاة. وذهب الشافعي وأحمد رحمهما الله تعالى إلى أنها واجبة، لو تركت لم تصح الصلاة، وهو مروي عن عمر بن الخطاب وابنه عبد الله رضي الله عنهما وهو قول الشعبي. وقد نسب جماعة الشافعي رحمه الله تعالى في هذا إلى مخالفة الإجماع ولا يصح قولهم فإنه مذهب الشعبي كما ذكرنا وقد رواه عن البيهقي. وفي الاستدلال لوجوبها خفاء وأصحابنا يحتجون بحديث أبي مسعود الأنصاري ﵁ المذكور هنا أنهم قالوا كيف نصلي عليك يا رسول الله فقال: (قولوا اللهم صل على محمد.. إلى آخره)، قالوا: والأمر للوجوب وهذا القدر لا يظهر الاستدلال به إلا إذا ضُمّ إليه الرواية الأخرى: (كيف نصلي عليك إذا نحن صلينا عليك في صلاتنا)، فقال ﷺ: قولوا اللهم صل على محمد وعلى آل محمد.. إلى آخره) وهذه الزيادة صحيحة رواها الإمامان الحافظان أبو حاتم بن حبان البستي والحاكم أبو عبد الله في صحيحيهما قال الحاكم هي زيادة صحيحة، واحتج لها أبو حاتم وأبو عبد الله أيضًا في صحيحيهما بها رويا: عن فضالة بن عبيد ﵁ أن رسول الله ﷺ رأى رجلًا يصلي لم يحمد الله ولم يمجده ولم يصل على النبي ﷺ فقال النبي ﷺ: [عجّل هذا] ثم دعاه النبي ﷺ فقال: [إذا صلى أحدكم فليبدأ بحمد ربه والثناء عليه وليصل على النبي ﷺ وليدع ما شاء]. قال الحاكم هذا حديث صحيح على شرط مسلم وهذان الحديثان وإن اشتملا على ما لا يجب بالإجماع كالصلاة على الآل والذرية والدعاء فلا يمتنع الاحتجاج بها فإن الأمر للوجوب فإذا خرج بعض ما يتناوله الأمر عن الوجوب بدليل بقي الباقي على الوجوب. والله أعلم. والواجب عند أصحابنا: [اللهم صل على محمد] وما زاد عليه سنة. ولنا وجه شاذ أنه يجب الصلاة على الآل وليس بشيء والله أعلم.`,
        o: `أبو حنيفة ومالك والجماهير: سنة لو تركت صحت الصلاة. الشافعي وأحمد: واجبة لا تصح الصلاة بتركها (ومروي عن عمر وابنه وقول الشعبي). وجه شاذ عند الشافعية: يجب الصلاة على الآل. (الشوكاني وكثير من أئمة أهل البيت يرون وجوب الصلاة على الآل.)`,
        s: `(مذهب أحمد:) ولكن مذهب أحمد أنها واجبة وليست ركناً لو نسيها سجد للسهو وصحت صلاته ولو جهلها أو جهل وجوبها صحت صلاته، ولكن لو تركها عمداً مع العلم والقدرة بطلت صلاته، والشافعي يرى أنها واجبة مطلقاً فالواجب عند الشافعي هو الركن. (الاستدلال بالرواية:) أي الاستفادة في وجوبها في الصلاة من هذه الرواية، ويمكن أن يستدل بها على ما هي عليه، ف[أَمَرَنَا اللَّهُ تَعَالَى أَنْ نُصَلِّيَ عَلَيْكَ يَا رَسُولَ اللَّهِ فَكَيْفَ نُصَلِّي عَلَيْكَ؟] أي أمرنا عند ذكرك، كل ما ذكر، فلو كان واجباً كلها ذُكر فدخل في ذلك وجوبه في الصلاة، وهذا قول متجه رغم أنه خلاف عامة العلماء وهو أنه يجب الصلاة على النبي ﷺ كلما ذُكر كما في قوله ﷺ: (رَغِمَ أَنْفُ رَجُلٍ ذُكِرْتُ عِنْدَهُ فَلَمْ يُصَلِّ عَلَيَّ) حديث صحيح، و(رَغِمَ) أي ذل، ولا عقوبة إلا لترك واجب. (حديث فضالة:) حديث صحيح ويدل على مذهب الشافعي ويدل على مذهب أحمد تماماً، وهو أنه إذا تركها جاهلاً بوجوبها لم تبطل صلاته لأنه لم يأمره بالإعادة، وهو دليل أيضاً على أن التشهد من الواجبات وليس من الأركان لأن الحمد والثناء هنا إنما هو التشهد لقوله (التحيات لله). (الصارف:) فيجعل الصارف للأمر على آل النبي ﷺ الإجماع مع أن هذا الإجماع فيه نظر. (ولنا وجه شاذ:) ولا ندري ما الصارف إذا لم يثبت الإجماع، أين الإجماع على عدم وجوب الصلاة على الآل؟ ولكنه قولٌ نادر، وأما عدم وجوب الدعاء فقد قال طاووس بوجوب الاستعاذة من الأربع وهو قول قوي لظاهر الحديث، فأقل شيء أن يقول (اللَّهُمَّ صَلِّ عَلَى مُحَمَّدٍ وَعَلَى آلِ مُحَمَّدٍ) فهذا أحوط، وإن قال (اللَّهُمَّ صَلِّ عَلَى مُحَمَّدٍ) أجزئ عند جمهور أهل العلم، والشوكاني يرجح وجوب الصلاة على الآل، ومذهب كثير من أئمة أهل البيت وجوب الصلاة على الآل، فلا ندري ما وجه هذا النقل للإجماع مع العلم بوجود المخالف.`,
        f: [] },
      { q: `المراد بـ«آل النبي ﷺ» في الصلاة عليه: مذاهب العلماء`, p: `135–136`,
        n: `واختلف العلماء في آل النبي ﷺ على أقوال: أظهرها وهو اختيار الأزهري وغيره من المحققين أنهم جميع الأمة. والثاني بنو هاشم وبنو المطلب. والثالث أهل بيته ﷺ وذريته والله أعلم.`,
        o: `الأظهر عند النووي والأزهري: جميع الأمة. الثاني: بنو هاشم وبنو المطلب. الثالث: أهل بيته وذريته.`,
        s: `القول الثاني هو الأظهر عندي، وهو من حُرمت عليهم الصدقة [بنو هاشم وبنو المطلب] وأزواجه ﷺ من أهل بيته بدليل الحديث: (اللَّهُمَّ صَلِّ عَلَى مُحَمَّدٍ وَعَلَى أَزْوَاجِهِ وَذُرِّيَّتِهِ) ولا شك في أن ذرِّيته من أهل البيت لأنهم من نسل فاطمة وعلي ابن أبي طالب فلا ذرية للنبي ﷺ إلا من هؤلاء وهم من بني هاشم، وأزواجه من أهل بيته.`,
        f: [] },
      { q: `سؤال الصحابة «كيف نصلي عليك»: هل هو في الصلاة أم في غيرها؟ ولماذا ذكره مسلم في كتاب الصلاة؟`, p: `136`,
        n: `قوله (أمرنا الله تعالى أن نصلي عليك يا رسول الله فكيف نصلي عليك) معناه أمرنا الله تعالى بقوله تعالى: (صلوا عليه وسلموا تسليمًا) فكيف نلفظ بالصلاة؟ وفي هذا أن من أمر بشيء لا يُفهم مراده يُسأل عنه ليعلم ما يأتي به. قال القاضي: [ويحتمل أن يكون سؤالهم عن كيفية الصلاة في غير الصلاة ويحتمل أن يكون في الصلاة. قال: وهو الأظهر. قلتُ: وهذا ظاهر اختيار مسلم ولهذا ذكر هذا الحديث في هذا الموضع].`,
        o: NO_O,
        s: `(أي بعد التشهد فقد أتى بوجوب الصلاة على النبي ﷺ، فلو كان عنده مطلقاً لوضعه في [الأذكار] ولكنه وضعه في [كتاب الصلاة].)`,
        f: [] },
      { q: `الحكمة في تشبيه الصلاة على محمد ﷺ بالصلاة على إبراهيم مع أنه أفضل منه (الأقوال)`, p: `137–138`,
        n: `واختلف العلماء في الحكمة في قوله: [اللهم صل على محمد كما صليت على إبراهيم] مع أن محمدًا ﷺ أفضل من إبراهيم ﷺ: قال القاضي عياض ﵀: أظهر الأقوال أن نبينا ﷺ سأل ذلك لنفسه ولأهل بيته ليتم النعمة عليهم كما أتمها على إبراهيم وعلى آله. وقيل بل سأل ذلك لأمته. وقيل بل ليبقى ذلك له دائمًا إلى يوم القيامة ويجعل له به لسان صدق في الآخرين كإبراهيم ﷺ. وقيل كان ذلك قبل أن يعلم أنه أفضل من إبراهيم ﷺ. وقيل سأل صلاة يتخذه بها خليلًا كما اتخذ إبراهيم. هذا كلام القاضي. والمختار في ذلك أحد ثلاثة أقوال: أحدها حكاه بعض أصحابنا عن الشافعي رحمه الله تعالى أن معناه: صل على محمد وتم الكلام هنا ثم استأنف وعلى آل محمد أي وصل على آل محمد كما صليت على إبراهيم وآل إبراهيم، فالمسئول له مثل إبراهيم وآله هم آل محمد ﷺ لا نفسه. القول الثاني معناه: اجعل لمحمد وآله صلاة منك كما جعلتها لإبراهيم وآله، فالمسئول المشاركة في أصل الصلاة لا قدرها. القول الثالث أنه على ظاهره والمراد: اجعل لمحمد وآله صلاة بمقدار الصلاة التي لإبراهيم وآله، والمسئول مقابلة الجملة بالجملة. فإن المختار في الآل كما قدمناه أنهم جميع الأتباع ويدخل في آل إبراهيم خلائق لا يحصون من الأنبياء ولا يدخل في آل محمد ﷺ نبي فطلب إلحاق هذه الجملة التي فيها نبي واحد بتلك الجملة التي فيها خلائق من الأنبياء. والله أعلم.`,
        o: `القاضي عياض وغيره: سأله لنفسه ولأهل بيته ليتم النعمة؛ أو لأمته؛ أو ليبقى له لسان صدق؛ أو قبل أن يعلم أنه أفضل؛ أو سأل صلاة يتخذه بها خليلًا. والمختار عند النووي أحد ثلاثة: (١) «وعلى آل محمد» استئناف (حكاه بعض الشافعية عن الشافعي)، (٢) المشاركة في أصل الصلاة لا قدرها، (٣) بمقدار صلاة إبراهيم وآله مقابلة الجملة بالجملة.`,
        s: `والقول الثالث هو أقرب الأقوال عندي. بمعنى أن آل إبراهيم فيه كل الأنبياء فهو يطلب صلاة عليه مجموع ما على إبراهيم وعلى الأنبياء وخصوصاً وأن كل الأنبياء من بعده من ذريته، فكل الأنبياء والصالحين من ذرية إبراهيم مطلوبٌ للنبي ﷺ صلاةٌ بمجموع كل هذه الصلوات.`,
        f: [] },
      { q: `الدعاء للنبي ﷺ بالرحمة (اللهم ارحم محمدًا) ضمن الصلاة عليه`, p: `138–139`,
        n: `قال القاضي عياض: ولم يجئ في هذه الأحاديث ذكر الرحمة على النبي ﷺ وقد وقع في بعض الأحاديث الغريبة. قال: واختلف شيوخنا في جواز الدعاء للنبي ﷺ بالرحمة: فذهب بعضهم وهو اختيار أبي عمر بن عبد البر إلى أنه لا يقال، وأجازه غيره وهو مذهب أبي محمد بن أبي زيد، وحجة الأكثرين تعليم النبي ﷺ الصلاة عليه وليس فيها ذكر الرحمة، والمختار أنه لا يُذكر الرحمة.`,
        o: `ابن عبد البر والأكثرون: لا يقال (اللهم ارحم محمدًا). ابن أبي زيد القيرواني وغيره: يجوز.`,
        s: `أي لا يذكر الرحمة في الصلاة على النبي ﷺ، وأما أن النبي ﷺ يصح له الدعاء بالرحمة فنعم، ولكن لا على سبيل الشعار، فلا تقول [محمد رحمه الله] ولكن نقول (محمد ﷺ)، الشعار الصلاة والسلام على النبي ﷺ لأنه شعار لازم فكلما يُذكر يُصلى ويسلم عليه ﷺ وإلا فقد قال النبي ﷺ في التشهد (السلام عليك أيها النبي ورحمة الله وبركاته) وهو دعاء بالرحمة، ولكن لا على سبيل الشعار، كما لا يصح على سبيل الشعار القول [محمد عز وجل] ولا [محمد رضي الله عنه] وهو قد رضي الله عنه، وكذلك ولا الصحابة [صلى الله عليهم وسلم] فكلٌ يختص بها جرت عليه عادة أهل السنة. (فقد أتت الرحمة مع السلام ولم تأتِ الرحمة مع الصلاة.)`,
        f: [`(ص139) والأول هو المشهور وهو البركة الخير الكثير المتزايد، ولا مانع من اجتماع ذلك، لأن الثبات مع الزيادة لا يتنافى فقد ثبت على الأول وزاد عليه. (تعليقًا على معنى «وبارك»: الزيادة في الخير والكرامة أو الثبات.)`] },
      { q: `الصلاة على غير الأنبياء استقلالًا (اللهم صل على أبي بكر): حكمها (مكروهة أم خلاف الأولى؟)`, p: `139–141`,
        n: `وقوله: (اللهم صل على محمد وعلى آل محمد) احتج به من أجاز الصلاة على غير الأنبياء وهذا مما اختلف العلماء فيه: فقال مالك والشافعي رحمهما الله تعالى والأكثرون: لا يُصلى على غير الأنبياء استقلالًا فلا يقال اللهم صل على أبي بكر أو عمر أو علي أو غيرهم ولكن يُصلى عليهم تبعًا فيقال اللهم صل على محمد وآل محمد وأصحابه وأزواجه وذريته كما جاءت به الأحاديث. وقال أحمد وجماعة: يُصلى على كل واحد من المؤمنين مستقلًّا، واحتجوا بأحاديث الباب وبقوله ﷺ: (اللهم صل على آل أبي أوفى)، وكان إذا أتاه قوم بصدقتهم صلى عليهم، قالوا وهو موافق لقول الله تعالى: (هو الذي يصلي عليكم وملائكته). واحتج الأكثرون بأن هذا النوع مأخوذ من التوقيف واستعمال السلف ولم يُنقل استعمالهم ذلك بل خصوا به الأنبياء كما خصوا الله تعالى بالتقديس والتسبيح فيقال قال الله سبحانه وتعالى وقال الله تعالى وقال ﷻ وقال جلت عظمته وتقدست أسماؤه وتبارك وتعالى ونحو ذلك ولا يقال قال النبي ﷺ وإن كان عزيزًا جليلًا ولا نحو ذلك؛ وأجابوا عن قول الله تعالى (هو الذي يصلي عليكم وملائكته) وعن الأحاديث: بأن ما كان من الله ﷻ ورسوله فهو دعاء وترحم وليس فيه معنى التعظيم والتوقير الذي يكون من غيرهما وأما الصلاة على الآل والأزواج والذرية فإنها جاء على التبع لا على الاستقلال وقد بينّا أنه يقال تبعًا لأن التابع يُحتمل فيه ما لا يُحتمل استقلالًا. واختلف أصحابنا في الصلاة على غير الأنبياء هل يقال هو مكروه أو هو مجرد ترك أدب، والصحيح المشهور أنه مكروه كراهة تنزيه. قال الشيخ أبو محمد الجويني: [والسلام في معنى الصلاة]، فإن الله تعالى قرن بينهما فلا يُفرد به غائب غير الأنبياء فلا يقال أبو بكر وعمر وعلي عليهم السلام وإنما يقال ذلك خطابًا للأحياء والأموات فيقال السلام عليكم ورحمة الله والله أعلم.`,
        o: `مالك والشافعي والأكثرون: لا يُصلى على غير الأنبياء استقلالًا، ويُصلى عليهم تبعًا. أحمد وجماعة: يصلى على كل مؤمن مستقلًّا. وعند الشافعية: مكروهة كراهة تنزيه (الصحيح المشهور)، أو ترك أدب. والسلام في معنى الصلاة (الجويني).`,
        s: `(هذا الكلام في النقل نعم إذا كان في الشعار كما ذكرنا، أما أنه لم يُنقل آحاد في بعض المواطن دون أن يكون شعاراً فمن أين ذلك؟ فالأحاديث ثابتة وأقوال العلماء منهم الإمام أحمد وغيره ومن وافقه ثابتة في ذلك، فكلامه أنه لم ينقل عن السلف فهل هو مطلقاً أم على سبيل الشعار؟ فهو لم يُنقل على سبيل الشعار.) (دون أن يُجعل شعاراً كما ذكرنا.) وهذا معنى صحيح، فلو أخذ الذي يجمع الصدقة الزكاة من قوم فقال اللهم صل عليهم صح ذلك، وهذا هو الصحيح. ووجه الاستدلال من الآية أن الملائكة تصلي على المؤمنين. (فلو قيل «اللهم صل على أبي بكر» فهل يكره أم ترك الأدب؟ أي ترك الأدب أي ترك الأولى وهو أقل من مرتبة الكراهة.) (عامة أهل السنة على ذلك أيضاً في باب الشعار إلا أن طائفة كبيرة من المتقدمين من أهل السنة وهي مليئة في البخاري وهي السلام على أهل البيت فالبخاري مليء بفاطمة عليها السلام وعلي عليه السلام والحسن والحسين عليهما السلام، وبالطبع فاطمة أكثر فمرات عديدة في البخاري وغيره من كتب الحديث فيها ذكر السلام على أهل البيت، ولكن الأولى في هذا المقام أن يصلى ويسلم على الأنبياء، وإن كان كثير من المتأخرين يسلم على الأنبياء غير النبي ﷺ حتى ظن بعض الناس أن الصلاة مختصة بالنبي ﷺ وليس كذلك، بل يُقال لجميع الأنبياء [ﷺ] ويُرضى عن الصحابة ويترحم على من دونهم، وإن خالف في ذلك لم يحرم ولم يُكره وإنما خالف الأولى، فمثلاً لو قال: الإمام النووي ﷺ فالأحسن أن يُقال [رحمه الله].)`,
        f: [] },
      { q: `معنى «من صلى عليَّ واحدة صلى الله عليه عشرًا»`, p: `141`,
        n: `قوله ﷺ: (من صلى عليَّ واحدة صلى الله عليه عشرًا) قال القاضي: معناه رحمته وتضعيف أجره كقوله تعالى: (من جاء بالحسنة فله عشر أمثالها) قال: وقد يكون الصلاة على وجهها وظاهرها تشريفًا له بين الملائكة، كما في الحديث: (وإن ذكرني في ملأ ذكرته في ملأ خير منهم).`,
        o: `القاضي عياض: معناه رحمته وتضعيف أجره، وقد تكون الصلاة على ظاهرها تشريفًا بين الملائكة.`,
        s: `وهذا هو الصحيح، فليس هناك معارضة، فالرحمة والثناء فيثني عليه ﷺ عشراً عند الملائكة في الملأ الأعلى كما في الحديث: (فإن ذكرني في ملأ ذكرته في ملأ خيراً منه).`,
        f: [] },
    ],
  },
  {
    title: `باب التسميع والتحميد والتأمين (ص142–145)`,
    items: [
      { q: `التأمين: متى يكون من المأموم؟ والجهر به للإمام والمنفرد والمأموم، وتأمين الإمام في الجهرية`, p: `143–144`,
        n: `في هذه الأحاديث: استحباب التأمين عقب الفاتحة للإمام والمأموم والمنفرد، وأنه ينبغي أن يكون تأمين المأموم مع تأمين الإمام لا قبله ولا بعده لقوله ﷺ: [وإذا قال ولا الضالين فقولوا آمين]، وأما رواية: [إذا أمّن فأمّنوا] فمعناها إذا أراد التأمين. وقد قدمنا بيان هذا قريبًا في حديث أبي موسى في باب التشهد. ويُسن للإمام والمنفرد الجهر بالتأمين وكذا للمأموم على المذهب الصحيح هذا تفصيل مذهبنا. وقد اجتمعت الأمة على أن المنفرد يؤمّن وكذلك الإمام والمأموم في الصلاة السرية: وكذلك قال الجمهور في الجهرية. وقال مالك رحمه الله تعالى في رواية: لا يؤمّن الإمام في الجهرية. وقال أبو حنيفة ﵁ والكوفيون ومالك في رواية لا يجهر بالتأمين. وقال الأكثرون يجهر.`,
        o: `مالك (رواية): لا يؤمن الإمام في الجهرية. أبو حنيفة والكوفيون ومالك (رواية): لا يجهر بالتأمين. الأكثرون: يجهر.`,
        s: `(وهذا يحتج بمثله في التحميد أيضاً لأن نفس اللفظ الذي ورد في التحميد هو الذي ورد في التأمين حيث قال: (فَإِنَّهُ مَنْ وَافَقَ تَأْمِينُهُ تَأْمِينَ الْمَلاَئِكَةِ غُفِرَ لَهُ مَا تَقَدَّمَ مِنْ ذَنْبِهِ) وفي التحميد قال: (فَإِنَّهُ مَنْ وَافَقَ قَوْلُهُ قَوْلَ الْمَلاَئِكَةِ غُفِرَ لَهُ مَا تَقَدَّمَ مِنْ ذَنْبِهِ) فينبغي أن يكون تحميده مع تحميد الملائكة فيقتضي هذا أن يكون تحميده وتحميد الإمام واحداً كما كان تأمينه وتأمين الإمام واحداً ليوافق تأمين الملائكة وتحميدهم.) (أو نقول [فأمنوا مع تأمينه] بدلالة حديث: [وإذا قال وَلاَ الضَّالِّينَ فَقُولُوا آمِينَ].) (وهذا خلاف ظاهر الحديث (إِذَا أَمَّنَ فَأَمِّنُوا) إذ الإمام يؤمن من يقول آمين.) (وذلك للإمام والمأموم والمنفرد للحديث وهو في السنن الكبرى للبيهقي: [عَنْ عَطَاءٍ قَالَ: "أَدْرَكْتُ مِائَتَيْنِ مِنْ أَصْحَابِ النَّبِيِّ ﷺ فِي هَذَا الْمَسْجِدِ إِذَا قَالَ الإِمَامُ: {غَيْرِ الْمَغْضُوبِ عَلَيْهِمْ وَلاَ الضَّالِّينَ} [الفاتحة: ٧]، سَمِعْتُ لَهُمْ رَجَّةً بِآمِينَ" وَرَوَاهُ إِسْحَاقُ الْحَنْظَلِيُّ، عَنْ عَلِيِّ بْنِ الْحَسَنِ، وَقَالَ: (رَفَعُوا أَصْوَاتَهُمْ بِآمِينَ).] وهذا يقتضي أنهم يجهرون جميعاً في صوت واحد.)`,
        f: [] },
      { q: `معنى «من وافق قوله قول الملائكة»: الموافقة في الوقت أم في الصفة والخشوع؟ ومن هم الملائكة؟`, p: `145`,
        n: `وقوله ﷺ: [من وافق قوله قول الملائكة]، [ومن وافق تأمينه تأمين الملائكة]: معناه وافقهم في وقت التأمين فأمّن مع تأمينهم فهذا هو الصحيح والصواب. وحكى القاضي عياض قولًا أن معناه وافقهم في الصفة والخشوع والإخلاص. واختلفوا في هؤلاء الملائكة فقيل هم الحفظة وقيل غيرهم لقوله ﷺ: [فوافق قوله قول أهل السماء]: وأجاب الأولون عنه بأنه إذا قالها الحاضرون من الحفظة قالها من فوقهم حتى ينتهي إلى أهل السماء.`,
        o: `القاضي عياض: الموافقة في الصفة والخشوع والإخلاص (قول). الملائكة: الحفظة، أو غيرهم من أهل السماء.`,
        s: `وهذا قول ضعيف، لأنه لا يستطيع أحد أن يخلص كإخلاص الملائكة وخشوعهم إلا الأنبياء أعلم؛ والصحيح أن نقول في هذه المسألة (الصحيح) ولا نقول (الصواب) لأن المسألة ليست نص، والقول الثاني الذي هو وافقهم في الخشوع ليس باطلاً — الذي هو عكس الصواب — ولكنه قول مرجوح والأول أرجح لأنه بين وقت التأمين وعلل بهذه العلة وكذا بين وقت التحميد وعلل بهذه العلة وهو ظاهر الحديث ومقصوده أنه وافقهم في التوقيت. وكما قلنا أن استدلال الإمام النووي هذا حجة على الشافعية في أن المأموم يقول (ربنا ولك الحمد) لأن هنا بيان وقت وافق قوله قول الملائكة في التوقيت فينبغي أن يقول مع الإمام ليوافقوا قول الملائكة، وهذا إنما يقع إذا وافق المأموم (ربنا ولك الحمد) مباشرةً وليس (سمع الله لمن حمده) لأنه لو قال (سمع الله لمن حمده) كان تحميده بعد تحميد الإمام. (والصحيح أنه يُعمم (قالت الملائكة) والله ﷻ أعلم بها.)`,
        f: [] },
      { q: `قول ابن شهاب «كان رسول الله ﷺ يقول آمين» وأن التأمين لا يكون إلا عقب الفاتحة`, p: `145`,
        n: `وقول ابن شهاب (وكان رسول الله ﷺ يقول آمين) معناه أن هذه صيغة تأمين النبي ﷺ وهو تفسير لقوله ﷺ: [إذا أمّن الإمام فأمّنوا] وردّ لقول من زعم أن معناه إذا دعا الإمام بقوله اهدنا الصراط إلى آخرها. وفي هذا الحديث دليل على قراءة الفاتحة لأن التأمين لا يكون إلا عقبها. والله أعلم.`,
        o: `قول من زعم أن التأمين عند دعاء الإمام بـ«اهدنا الصراط» (مردود).`,
        s: `(ولذلك الصحيح أيضاً أن المأموم يقرأ الفاتحة حتى إذا قرأ ولا الضالين يقول آمين.)`,
        f: [] },
    ],
  },
  {
    title: `باب ائتمام المأموم بالإمام (ص146–152)`,
    items: [
      { q: `متابعة الإمام في الأفعال والتكبير، والإشارة والعمل القليل في الصلاة للحاجة`, p: `148`,
        n: `(حديث أنس: سقط النبي ﷺ عن فرس فجحش شقه الأيمن... «إنما جعل الإمام ليؤتم به فإذا كبر فكبروا...») وفيه جواز الإشارة والعمل القليل في الصلاة للحاجة. وفيه متابعة الإمام في الأفعال والتكبير. وقوله: (ربنا ولك الحمد) كذا وقع هنا [ولك الحمد] بالواو، وفي روايات بحذفها. وقد سبق أنه يجوز الأمران.`,
        o: NO_O,
        s: `(فإنه أشار إليهم أن اجلسوا، فهذا دليل على جواز الإشارة والعمل القليل للحاجة، والقلة والكثرة مردها إلى العُرف.) (في الأفعال: بأن يتابع الإمام بعد أن يُتم الإمام حركته، يبدأ المأموم في الحركة، فإذا ركع ووصل إلى كمال الانحناء، يبدأ المأموم في الركوع وهكذا في السجود وسائر الحركات، ويكون التكبير بعد تكبير الإمام.) (ويجوز إضافة «اللهم» أيضاً.)`,
        f: [] },
      { q: `وجوب متابعة المأموم للإمام في التكبير والأفعال: متى يكبر تكبيرة الإحرام، ومن قارن الإمام أو سبقه، ومن سلّم قبله أو معه`, p: `149`,
        n: `وفيه وجوب متابعة المأموم لإمامه في التكبير والقيام والقعود والركوع والسجود وأنه يفعلها بعد الإمام: فيكبّر تكبيرة الإحرام بعد فراغ الإمام منها فإن شرع فيها قبل فراغ الإمام منها لم تنعقد صلاته. ويركع بعد شروع الإمام في الركوع وقبل رفعه منه فإن قارنه أو سبقه فقد أساء ولكن لا تبطل صلاته، وكذا السجود. ويسلّم بعد فراغ الإمام من السلام فإن سلّم قبله بطلت صلاته إلا أن ينوي المفارقة ففيه خلاف مشهور. وإن سلّم معه لا قبله ولا بعده فقد أساء ولا تبطل صلاته على الصحيح وقيل تبطل.`,
        o: `إن سبق الإمام في الركوع أو قارنه: لا تبطل صلاته. من سلّم معه: لا تبطل على الصحيح، وقيل تبطل. من سلّم قبله: تبطل إلا أن ينوي المفارقة (خلاف مشهور).`,
        s: `أي أن المأموم لا يبدأ التكبير إلا بعد انتهاء الإمام من حرف (الراء) في [أكبر]؛ وهو قول جمهور أهل العلم، أن مسابقة الإمام أو مساواته في تكبيرة الإحرام تبطل الصلاة. (ولا تبطل الصلاة:) لأن النبي ﷺ قال: [أَمَا يَخْشَى أَحَدُكُمْ، أَوْ لاَ يَخْشَى أَحَدُكُمْ – إِذَا رَفَعَ رَأْسَهُ قَبْلَ الإِمَامِ أَنْ يَجْعَلَ اللَّهُ رَأْسَهُ رَأْسَ حِمَارٍ، أَوْ يَجْعَلَ اللَّهُ صُورَتَهُ صُورَةَ حِمَارٍ.] البخاري. ولم يأمره بإعادة الصلاة، فهو دليل على أنه فعل محرم لأن العقوبة لا تكون إلا على فعل محرم ولكن لا تبطل الصلاة. (إن نوى المفارقة:) إن نوى مفارقة الإمام لعذر، كأن يكون الإمام طول فيسلم ناوياً مفارقة الإمام والصحيح صحة صلاته إن كان قد أتمها أو ينوي المفارقة ويكمل هو ما بقي منها ويسلم قبل إمامه، كأن يكون الإمام من عادته أن يصلي بسورة البقرة في صلاة العشاء كما صلى الرجل خلف معاذ في صلاة الفريضة فنوى رجل المفارقة وفارق الإمام وسلم قبل الإمام، فيحتمل أنه سلم واستأنف صلاته أو أكمل الصلاة وسلم، فيجزيه ذلك وذلك. (السلام أشبه بالركوع والسجود منه من تكبيرة الإحرام.)`,
        f: [] },
      { q: `صلاة القادر على القيام خلف إمام قاعد: (وإذا صلى قاعدًا فصلوا قعودًا)`, p: `150–151`,
        n: `وأما قوله ﷺ: (وإذا صلى قاعدًا فصلوا قعودًا) فاختلف العلماء فيه: فقالت طائفة بظاهره، وممن قال به أحمد بن حنبل والأوزاعي رحمهما الله تعالى. وقال مالك رحمه الله تعالى في رواية لا يجوز صلاة القادر على القيام خلف القاعد لا قائمًا ولا قاعدًا. وقال أبو حنيفة والشافعي وجمهور السلف رحمهم الله تعالى لا يجوز للقادر على القيام أن يصلي خلف القاعد إلا قائمًا، واحتجوا بأن النبي ﷺ في مرض وفاته بعد هذا صلى قاعدًا وأبو بكر ﵁ والناس خلفه قيامًا، وإن كان بعض العلماء زعم أن أبا بكر ﵁ كان هو الإمام والنبي ﷺ مقتدٍ به، لكن الصواب أن النبي ﷺ كان هو الإمام وقد ذكره مسلم بعد هذا الباب صريحًا أو كالصريح فقال في روايته عن أبي بكر بن أبي شيبة بإسناده عن عائشة رضي الله عنها قالت: (فجاء رسول الله ﷺ حتى جلس عن يسار أبي بكر وكان رسول الله ﷺ يصلي بالناس جالسًا وأبو بكر قائمًا يقتدي أبو بكر بصلاة النبي ﷺ ويقتدي الناس بصلاة أبي بكر).`,
        o: `طائفة (منهم أحمد والأوزاعي): يصلون قعودًا بظاهر الحديث. مالك (رواية): لا يجوز صلاة القادر على القيام خلف القاعد لا قائمًا ولا قاعدًا. أبو حنيفة والشافعي وجمهور السلف: لا يجوز إلا قائمًا. (وزعم بعضهم أن أبا بكر كان هو الإمام.)`,
        s: `(قول طائفة بظاهره:) وهو أن يصلي القادر على القيام قاعداً خلف الإمام القاعد. (أحمد والأوزاعي:) ولكن الإمام أحمد قال: إذا عرض للإمام عارض أثناء الصلاة فجلس صلى المأموم قائماً، وأما إذا بدأ الصلاة قاعداً صلى المأموم قاعداً. (قول مالك:) وهو قول مخالف سواء لأحاديث الباب أو الآتية في صلاة النبي ﷺ في مرض موته، فإبطال الصلاة للمأموم خلف الإمام القاعد ليس عليه دليل وقالوا لو صلى قاعداً فقد خالف قوله تعالى: (وَقُومُوا لِلَّهِ قَانِتِينَ) والأحاديث التي ذكرت (إذا قمت إلى الصلاة) فقالوا القيام ركن فسيترك ركن وهو قادر عليه؛ ولو أنه صلى قائماً خلف الإمام الجالس فقد خالف حديث: (وَإِذَا صَلَّى قَاعِدًا فَصَلُّوا قُعُودًا) فقالوا الحل ألا يصلي ويأتوا بإمام آخر، وللعلم الأحوط أن يأتوا بإمام آخر، ولكن هذا المذهب غير راجح فبطلان الصلاة مذهب ضعيف ولكن الأحوط خروجاً من الخلاف أن الإمام القاعد يستخلف وكذلك العاجز عن السجود بالأولى وكذا الركوع، فإمام يسجد بالإيماء فقط الأولى ألا يصلي إماماً خروجاً من الخلاف، فالخلاف في هذا أشد، فقول من يبطل صلاة المأموم خلف الذي لا يسجد ولا يركع أكثر. (خلافاً لهذا الحديث وللعلم فإن هذا ظاهر صنيع مسلم، فمسلم قد أتى بأحاديث (فَصَلُّوا جُلُوسًا أَجْمَعُونَ) وعقبها بحديث الصلاة خلف النبي ﷺ في مرض موته أنهم صلوا قياماً وسيأتي. وهذه طريقة مسلم أنه يأتي أولاً بالحديث المشكل ثم يأتي بالمبين سواء كان المشكل هذا مخصوصاً أو منسوخاً، فيأتي بالحديث المبين الذي عليه العمل مؤخراً.) (فقالوا بالنسخ، الإمام أحمد جمع بأنه هذا عرض أثناء الصلاة والحقيقة أن النبي ﷺ بدأ الصلاة جالساً ولكنه بدأ بعدهم، وقد كنت أميل لقول الإمام أحمد رحمه الله في الجمع ولكن قول الجمهور بالنسخ قوي في الدلالة.)`,
        f: [`(ص151) وهذا نص واضح في أن آخر الأمرين أن صلوا قياماً خلف رسول الله ﷺ قاعداً.`] },
      { q: `معنى «إنما جعل الإمام ليؤتم به»: هل تصح صلاة الفرض خلف النفل وعكسه، والظهر خلف العصر؟`, p: `151–152`,
        n: `وأما قوله ﷺ: (إنما جعل الإمام ليؤتم به): فمعناه عند الشافعي وطائفة في الأفعال الظاهرة وإلا فيجوز أن يصلي الفرض خلف النفل وعكسه، والظهر خلف العصر وعكسه. وقال مالك وأبو حنيفة ﵄ وآخرون لا يجوز ذلك، وقالوا معنى الحديث (ليؤتم به) في الأفعال والنيات. ودليل الشافعي ﵁ ومُوافقيه أن النبي ﷺ صلى بأصحابه ببطن نخل صلاة الخوف مرتين بكل فرقة مرة فصلاته الثانية وقعت له نفلًا وللمقتدين فرضًا، وأيضًا حديث معاذ: (كان يصلي العشاء مع النبي ﷺ ثم يأتي قومه فيصليها بهم هي له تطوع وهم فريضة)، ولهم مما يدل على أن الائتمام إنما يجب في الأفعال الظاهرة قوله ﷺ في رواية جابر ﵁: (ائتموا بأئمتكم إن صلى قائمًا فصلوا قيامًا وإن صلى قاعدًا فصلوا قعودًا). والله أعلم.`,
        o: `الشافعي وطائفة: يجوز الفرض خلف النفل وعكسه، والظهر خلف العصر وعكسه (الائتمام في الأفعال الظاهرة). مالك وأبو حنيفة وآخرون: لا يجوز (الائتمام في الأفعال والنيات).`,
        s: `(الفرض خلف النفل:) فهناك أدلة تفصيلية في ذلك منها: صلاة معاذ متنفلاً بقومه مفترضين، وصلاة الذي صلى في رحلة متنفلاً مع الإمام إذا حضرت الصلاة كما قال النبي ﷺ: (إِذَا صَلَّيْتُمَا فِي رِحَالِكُمَا ثُمَّ أَتَيْتُمَا مَسْجِدَ جَمَاعَةٍ فَصَلِّيَا مَعَهُمْ، فَتَكُونُ لَكُمَا نَافِلَةً، وَالَّتِي فِي رِحَالِكُمَا فَرِيضَةً) ((هق) ٣٤٦٢، (قط) ١/ ٤١٤، انظر صحيح الجامع: ٦٦٦) فصلى النفل خلف الفرض وكذلك حديث أبي سعيد الخدري، أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ "أَبْصَرَ رَجُلًا يُصَلِّي وَحْدَهُ، فَقَالَ: أَلَا رَجُلٌ يَتَصَدَّقُ عَلَى هَذَا فَيُصَلِّيَ مَعَهُ"، (د) ٥٧٤ [قال الألباني]: صحيح، فإنه كذلك صلاة النفل خلف الفرض. (الظهر خلف العصر:) أي والعصر خلف الظهر والظهر خلف العصر في الجمع لعذر وهذا عند الشافعية وطائفة من العلماء. (الصحيح قول الشافعي، ولكن إذا أقيمت الصلاة مع الإمام الراتب، الصحيح أن يصلي الصلاة التي أُقيمت، ولكن تصح الصلاة والله أعلى وأعلم.) (فيكون الكلام على الأفعال وليس النيات.)`,
        f: [`(ص152) وهذا ثابت في صحيح مسلم: (عَنْ أَبِي سَلَمَةَ عَنْ جَابِرٍ قَالَ أَقْبَلْنَا مَعَ رَسُولِ اللَّهِ ﷺ حَتَّى إِذَا كُنَّا بِذَاتِ الرِّقَاعِ... فَصَلَّى بِطَائِفَةٍ رَكْعَتَيْنِ ثُمَّ تَأَخَّرُوا وَصَلَّى بِالطَّائِفَةِ الأُخْرَى رَكْعَتَيْنِ، قَالَ فَكَانَتْ لِرَسُولِ اللَّهِ ﷺ أَرْبَعُ رَكَعَاتٍ وَلِلْقَوْمِ رَكْعَتَانِ.)`] },
    ],
  },
  {
    title: `باب النهي عن مبادرة الإمام بالتكبير وغيره (ص152–154)`,
    items: [
      { q: `النهي عن قيام الغلمان والأتباع على رأس متبوعهم الجالس، والقيام للداخل من أهل الفضل`, p: `153–154`,
        n: `قوله ﷺ: (إن كدتم تفعلون فعل فارس والروم يقومون على ملوكهم وهو قعود فلا تفعلوا): فيه النهي عن قيام الغلمان والأتباع على رأس متبوعهم الجالس لغير حاجة، وأما القيام للداخل إذا كان من أهل الفضل والخير فليس من هذا بل هو جائز قد جاءت به أحاديث وأطبق عليه السلف والخلف وقد جمعت دلائله وما يرد عليه في جزء وبالله التوفيق والعصمة.`,
        o: NO_O,
        s: `(فيقومون حوله وهو جالس أمر مكروه إلا أن يجلس بعضهم.) هذا في القيام للسلام عليه، أما القيام المجرد فهو داخل في النهي لأن النبي ﷺ كان يكره أن يقوموا إذا رأوه داخلاً، أما أن يقوم ليسلم فنعم، فالمدرس الذي يوقف التلاميذ لا ليسلموا عليه ولا لشيء فليس هذا بمشروع، بل هو داخلٌ في النهي.`,
        f: [] },
    ],
  },
  {
    title: `باب استخلاف الإمام إذا عرض له عذر من مرض وسفر وغيرهما من يصلي بالناس وأن من صلى خلف إمام جالس لعجزه عن القيام لزمه القيام إذا قدر عليه ونسخ القعود خلف القاعد في حق من قدر على القيام (ص154–166)`,
    items: [
      { q: `تواتر موت النبي ﷺ والاستخلاف: ما يدل عليه حديث مرض النبي ﷺ وتقديم أبي بكر`, p: `158`,
        n: `فيه حديث استخلاف النبي ﷺ أبا بكر ﵁ وقد قدمنا في آخر الباب السابق دليل ما ذكرته في الترجمة.`,
        o: NO_O,
        s: NO_N,
        f: [`(ص158) والحديث مع الذي قبله والذي قبله فيه تواتر النقل عن أصحاب النبي ﷺ أن رسول الله ﷺ قد مات، خلافاً للضلال المبتدعين القائلين أنه لم يمت، ولا نزاع في أنه يحيى حياة برزخية عند الله ﷻ، ولكن ليس على وجه الأرض، وقد مات ﷺ ولم تأكل جسده الأرض ولا دود ولا غيره.`] },
      { q: `الغسل من الإغماء: هل هو مستحب أم واجب؟ وجواز الإغماء على الأنبياء`, p: `159`,
        n: `قولها (قال ضعوا لي ماء في المخضب ففعلنا فاغتسل) دليل الاستحباب بالغسل من الإغماء وإذا تكرر الإغماء استحب تكرر الغسل لكل مرة، فإن لم يغتسل إلا بعد الإغماء مرات كفى غسل واحد. وقد حمل القاضي عياض الغسل هنا على الوضوء من حيث إن الإغماء ينقض الوضوء ولكن الصواب أن المراد غسل جميع البدن فإنه ظاهر اللفظ ولا مانع يمنع منه فإن الغسل مستحب من الإغماء. بل قال بعض أصحابنا إنه واجب وهذا شاذ ضعيف. وقوله (فأُغمي عليه) دليل على جواز الإغماء على الأنبياء صلوات الله وسلامه عليهم ولا شك في جوازه فإنه مرض والمرض يجوز عليهم بخلاف الجنون فإنه لا يجوز عليهم لأنه نقص والحكمة في جواز المرض عليهم ومصائب الدنيا تكثير أجرهم وتسلية الناس بهم ولئلا يفتتن الناس بهم ويعبدوهم لما يظهر عليهم من المعجزات والآيات البينات والله أعلم.`,
        o: `بعض الشافعية: الغسل من الإغماء واجب (شاذ ضعيف). القاضي عياض: المراد الوضوء.`,
        s: `(ولم نقل بالوجوب لأن الأفعال لا يلزم منها الوجوب.) (لأنه ليس بأمر.)`,
        f: [] },
      { q: `تأخر الإمام عن أول الوقت وانتظار المصلين له (وطلب الاستدعاء من المؤذن)`, p: `159–160`,
        n: `قولها (فقال أصلى الناس فقيل لا وهم ينتظرونك يا رسول الله) دليل على أنه إذا تأخر الإمام عن أول الوقت ورُجي مجيئه على قرب يُنتظر ولا يتقدم غيره وسنبسط المسألة في الباب بعده إن شاء الله تعالى. وقولها (لما ثقل رسول الله ﷺ جاء بلال يؤذنه بالصلاة): فيه دليل لما قاله أصحابنا أنه لا بأس باستدعاء الأئمة للصلاة.`,
        o: NO_O,
        s: `(يذهب المؤذن ويقول للإمام قد حان وقت إقامة الصلاة أو يقول له: أأقيم الصلاة؟ وأنه لابد وأن يستأذن.)`,
        f: [] },
      { q: `فضل أبي بكر وفوائد قولها «أنت أحق بذلك»، وقول أبي بكر «رجل رقيق» وقول عائشة في مراجعتها، ومعنى «إنكن لأنتن صواحب يوسف»`, p: `160–164`,
        n: `قولها (فأرسل رسول الله ﷺ إلى أبي بكر ﵁ أن يصلي بالناس فقال أبو بكر ﵁ وكان رجلًا رقيقًا يا عمر صل بالناس فقال عمر ﵁ أنت أحق بذلك) فيه فوائد: منها فضيلة أبي بكر الصديق ﵁ وترجيحه على جميع الصحابة رضوان الله عليهم أجمعين وتفضيله وتنبيه على أنه أحق بخلافة رسول الله ﷺ من غيره. ومنها أن الإمام إذا عرض له عذر عن حضور الجماعة استخلف من يصلي بهم وأنه لا يستخلف إلا أفضلهم. ومنها فضيلة عمر بعد أبي بكر ﵁ لأن أبا بكر ﵁ لم يعدل إلى غيره. ومنها أن المفضول إذا عرض عليه الفاضل مرتبة لا يقبلها بل يدعها للفاضل إذا لم يمنع مانع. ومنها جواز الثناء في الوجه لمن أمن عليه الإعجاب والفتنة لقوله (أنت أحق بذلك). وأما قول أبي بكر لعمر ﵁ صلِّ بالناس فقاله للعذر المذكور وهو أنه رجل رقيق القلب كثير الحزن والبكاء لا يملك عينيه، وقد تأوله بعضهم على أنه قاله تواضعًا والمختار ما ذكرناه. وقولها (فخرج بين رجلين أحدهما العباس) وفسر ابن عباس الآخر بعلي بن أبي طالب وفي الطريق الآخر (فخرج ويد له على الفضل بن عباس ويد له على رجل آخر) وجاء في غير مسلم بين رجلين أحدهما أسامة بن زيد، وطريق الجمع بين هذا كله أنهم كانوا يتناوبون الأخذ بيده الكريمة تارة هذا وتارة ذاك ويتنافسون في ذلك وهؤلاء هم خواص أهل بيته الرجال الكبار وكان العباس ﵁ أكثرهم ملازمة للأخذ بيده الكريمة المباركة ﷺ أو أنه أدام الأخذ بيده وإنما يتناوب الباقون في اليد الأخرى وأكرموا العباس باختصاصه بيد واستمرارها له لما له من السن والعمومة وغيرهما ولهذا ذكرته عائشة رضي الله عنها مسمى وأبهمت الرجل الآخر إذ لم يكن أحد الثلاثة الباقين ملازمًا في جميع الطريق ولا معظمه بخلاف العباس والله أعلم. وقوله ﷺ: (أجلساني إلى جنبه فأجلساه إلى جنبه) فيه جواز وقوف مأموم واحد بجنب الإمام لحاجة أو مصلحة كإسماع المأمومين وضيق المكان ونحو ذلك. وقوله (استأذن أزواجه أن يمرَّض في بيتها) يعني بيت عائشة وهذا يستدل به من يقول كان القسم واجبًا على النبي ﷺ بين أزواجه في الدوام كما يجب في حقنا ولأصحابنا وجهان: أحدهما هذا، والثاني سنة ويحملون هذا وقوله ﷺ [اللهم هذا قسمي فيما أملك] على الاستحباب ومكارم الأخلاق وجميل العشرة. وفيه فضيلة عائشة رضي الله عنها ورجحانها على جميع أزواجه الموجودات ذلك الوقت وكن تسعًا إحداهن عائشة رضي الله عنها وهذا لا خلاف فيه بين العلماء وإنما اختلفوا في عائشة وخديجة رضي الله عنهما. قوله: (يخطُّ برجليه في الأرض) أي لا يستطيع أن يرفعهما ويضعهما ويعتمد عليهما. قوله ﷺ: (إنكن لأنتن صواحب يوسف) أي في التظاهر على ما تردن وكثرة إلحاحكن في طلب ما تردنه وتملن إليه، وفي مراجعة عائشة جواز مراجعة ولي الأمر على سبيل العرض والمشاورة والإشارة بما يظهر أنه مصلحة وتكون تلك المراجعة بعبارة لطيفة ومثل هذه المراجعة مراجعة عمر ﵁ في قوله [لا تبشرهم فيتكلوا] وأشباهه كثيرة مشهورة.`,
        o: `قيل إن قول أبي بكر لعمر كان تواضعًا؛ المختار أنه للعذر المذكور. وفي القسم بين الأزواج على النبي ﷺ وجهان عند الشافعية: واجب أو سنة. واختلف في تفضيل عائشة وخديجة رضي الله عنهما.`,
        s: `(القسم:) والصحيح أنه كان سنة لقوله تعالى: (تُرْجِي مَن تَشَاءُ مِنْهُنَّ وَتُؤْوِي إِلَيْكَ مَن تَشَاءُ وَمَنِ ابْتَغَيْتَ مِمَّنْ عَزَلْتَ فَلاَ جُنَاحَ عَلَيْكَ) فالصحيح أن القسم لم يكن واجباً عليه ﷺ وإنما كان يفعله من باب مكارم الأخلاق، وأما في حق غيره ففرض. (عائشة وخديجة:) والصحيح أن خديجة أفضل لقوله ﷺ: («خَيْرُ نِسَائِهَا مَرْيَمُ بِنْتُ عِمْرَانَ وَخَيْرُ نِسَائِهَا خَدِيجَةُ بِنْتُ خُوَيْلِدٍ». قَالَ أَبُو كُرَيْبٍ وَأَشَارَ وَكِيعٌ إِلَى السَّمَاءِ وَالأَرْضِ.) مسلم. (صواحب يوسف:) بل الظاهر ما ذكرنا من إبداء أمر وإخفاء غيره لأن صواحب يوسف أبدين عتاب امرأة العزيز وكان كيداً منهن لأمر آخر وهو رؤية يوسف، فعائشة أظهرت أنها تريد أن تُسمع الناس لأن أبا بكر رجل رقيق وهي إنما كانت تكره أن يتشاءم الناس بأبيها. وهذا الأمر منها غير سديد رضي الله عنها، ولا شك أن أمر عمر ﵁ أن يصلي بالناس وفي القوم أبي بكر أمر غير سديد واقتراح غير صائب فضلاً أن يكون غرضه ما ذكرت رضي الله عنها قالت: [وَمَا حَمَلَنِي عَلَى كَثْرَةِ مُرَاجَعَتِهِ إِلاَّ أَنَّهُ لَمْ يَقَعْ فِي قَلْبِي أَنْ يُحِبَّ النَّاسُ بَعْدَهُ رَجُلاً قَامَ مَقَامَهُ أَبَدًا وَإِلاَّ أَنِّي كُنْتُ أَرَى أَنَّهُ لَنْ يَقُومَ مَقَامَهُ أَحَدٌ إِلاَّ تَشَاءَمَ النَّاسُ بِهِ فَأَرَدْتُ أَنْ يَعْدِلَ ذَلِكَ رَسُولُ اللَّهِ ﷺ عَنْ أَبِي بَكْرٍ.] وكان ظن رسول الله ﷺ بأصحابه خيراً من ظن عائشة بهم، فقد قام أبو بكر فقدمه الصحابة وأحبوه أشد أحد حباً بعد رسول الله ﷺ، وهكذا واجب على كل مكلف أن يُحب أبا بكر ﵁ بعد رسول الله ﷺ أشد من حب أي أحد، وذلك لأن الله ﷻ جعله صاحب رسول الله ﷺ المقرب إليه واختاره وأمر أن يصلي بالناس. قوله: (إِنَّكُنَّ لأَنْتُنَّ صَوَاحِبُ يُوسُفَ) فهذا دليل على أن صواحب يوسف أردن بقولهن: (إِنَّا لَنَرَاهَا فِي ضَلاَلٍ مُبِينٍ) أن يرون يوسف لذا قال ﷻ: (فَلَمَّا سَمِعَتْ بِمَكْرِهِنَّ) فأين المكر في ذلك أن يتكلم النسوة عن ذم من تحب فتاها، المكر في ذلك أنهن تكلمن بذلك يُظهرن الإنكار عليها وحقيقة الأمر موافقتها في طلب رؤية يوسف والتمتع بوجهه، فشبه النبي ﷺ إرادة عائشة أمراً وإخفاء أمر آخر والله أعلم بهذا أرادت حفصة أيضاً في العتاب (إِنَّكُنَّ) فشبه النبي ﷺ إرادتهن أمراً وإخفائهن غيره بما صنع النسوة بأنهن أظهرن الإنكار وغرضهن الموافقة والمراودة وغرضهن أن يفعلن ما فعلت من الحب ومن النظر إلى يوسف ﷺ والله أعلم. وهذا دليل على أن التشبيه لا يلزم أن يكون فيه كل الجوانب متفقة، فقد شبههن ﷺ صراحةً (إِنَّكُنَّ لأَنْتُنَّ صَوَاحِبُ يُوسُفَ) ومعلوم أن عائشة رضي الله عنها وحفصة رضي الله عنها أكرم بها لا يعلمه إلا الله من صواحب يوسف، ولكن التشبيه يمكن أن يقع في جزئية معينة وفي فعل معين ولو من بعيد ولا يلزم في التشبيه المساواة. وهذه الروايات صريحة في أن النبي ﷺ كان هو الإمام، وإليها ذهب الجمهور في كون هذا الحديث ناسخ للأحاديث الواردة في (صلوا قعوداً أجمعون) في أنهم يصلون قعوداً خلف الإمام الجالس، فقد كان النبي ﷺ إماماً جلس على يسار أبي بكر وقد كان أبو بكر يبلغ صلاة النبي ﷺ للناس، فكان يبلغ عنه فقط. وفي قول عروة: (فَجَلَسَ رَسُولُ اللَّهِ ﷺ حِذَاءَ أَبِي بَكْرٍ إِلَى جَنْبِهِ.) صريح أيضاً في أن المأموم يقف إلى جنب الإمام لا يتأخر عنه قليلاً كما يفعل البعض، فيتأخرون عن الإمام إذا كان رجل يؤم رجلاً، فالصحيح أن يقف بحذائه يقف بجواره تماماً لا يتأخر ولا يتقدم. وفيه مشروعية التبليغ عن الإمام إذا لم يصل صوت الإمام إلى الناس لعذر.`,
        f: [`(ص161) رقيق القلب كثير الحزن والبكاء لا يملك عينيه: ولهذا فإنه لا يُسمع الناس. وأما قراءة أبي بكر في الصلاة فإن النبي ﷺ للقرآن، فإن النبي ﷺ قال: (لَأُقْرِئُهُمْ لِكِتَابِ اللهِ أُبَيُّ بْنُ كَعْبٍ) قال الشيخ الألباني: صحيح. ومع ذلك أمر أبا بكر أن يصلي بالناس وذلك لما لأبي بكر من الفضيلة وليشير إلى أن الإمام بعده هو أبو بكر، وقد فهم الصحابة ذلك فقالوا: رضيه رسول الله ﷺ لدينتا أفلا نرضاه لدنيانا، فتقديم النبي ﷺ لأبي بكر رغم أنه ليس أقرأ في الصحابة من أجل هذه المصلحة الراجحة، وأبو بكر ﵁ قراءته كما قالت عائشة: رجل أسيف كثير البكاء، كانت قراءته تؤثر في الناس بمجرد القراءة، فلما دخل في جوار ابن الدغنة: [فَأَنْفَذَتْ قُرَيْشٌ جِوَارَ ابْنِ الدَّغِنَةِ وَآمَنُوا أَبَا بَكْرٍ... وَيَقْرَأُ الْقُرْآنَ فَيَتَقَصَّفُ عَلَيْهِ نِسَاءُ الْمُشْرِكِينَ وَأَبْنَاؤُهُمْ يَعْجَبُونَ وَيَنْظُرُونَ إِلَيْهِ، وَكَانَ أَبُو بَكْرٍ رَجُلاً بَكَّاءً لاَ يَمْلِكُ دَمْعَهُ حِينَ يَقْرَأُ الْقُرْآنَ] صحيح البخاري.`, `(ص161) الأخذ بيد الإمام: (جواز وقوف مأموم واحد بجنب الإمام لحاجة...)`, `(ص164) وفيه مشروعية التبليغ عن الإمام إذا لم يصل صوت الإمام إلى الناس لعذر.`] },
      { q: `الالتفات في الصلاة للحاجة، ومخاطبة المصلي بالإشارة، وسبب تبسم النبي ﷺ`, p: `164–165`,
        n: `قولها (يُهادى بين رجلين) أي يمشي بينهما متكئًا عليهما يتمايل إليهما. قوله (كأن وجهه ورقة مصحف) عبارة عن الجمال البارع وحسن البشرة وصفاء الوجه واستنارته، وفي المصحف ثلاث لغات ضم الميم وكسرها وفتحها. قوله (ثم تبسم رسول الله ﷺ ضاحكًا) سبب تبسمه ﷺ فرحه بما رأى من اجتماعهم على الصلاة واتباعهم لإمامهم وإقامتهم شريعته واتفاق كلمتهم واجتماع قلوبهم ولهذا استنار وجهه ﷺ على عادته إذا رأى أو سمع ما يسره يستنير وجهه. وفيه معنى آخر وهو تأنيسهم وإعلامهم بتأتي حاله في مرضه. وقيل يحتمل أنه ﷺ خرج ليصلي بهم فرأى من نفسه ضعفًا فرجع. قوله (ونكص) أي رجع إلى وراءه قهقرى.`,
        o: NO_O,
        s: `(والأظهر الأول، ويؤنسهم ويُعلمهم أنه بخير وأنه يريد أن يبقوا كما هم مجتمعي الكلمة متفقين على إمام، يقيمون عبادة الله ﷻ وشرعه من بعده ﷺ في غيابه كما كانوا في حضوره.) (الظاهر والله أعلى وأعلم أن النبي ﷺ إنما كشف الستارة ليطمئن عليهم ورأى ما يطمئنه وسُر بذلك ﷺ لما رأى انتظامهم في الصفوف، فأشار إليهم أن أكملوا صلاتكم.) وهذا الحديث دليل على جواز الالتفات في الصلاة للحاجة فإنهم بان ووضح لهم وجه رسول الله ﷺ وهم في الصلاة والرسول ﷺ في حجرته، إذاً قد نظروا إلى وجه رسول الله ﷺ في الصلاة، وهذا دليل على أنه يجوز أن يلتفت التفاته لا ينحرف بها عن القبلة وإنما يلتفت التفاتة يسيرة ينظر بها للحاجة، وأي حاجة أفضل من أن ينظروا إلى وجه رسول الله ﷺ النظرة الأخيرة. وفيه حب الصحابة ﵃ للنبي ﷺ حباً عظيماً أعظم الحب لمخلوق. وفيه جواز مخاطبة المصلي في الصلاة بالإشارة لأن النبي ﷺ [فَأَوْمَأَ نَبِيُّ اللَّهِ ﷺ بِيَدِهِ إِلَى أَبِى بَكْرٍ أَنْ يَتَقَدَّمَ] و[فَأَشَارَ إِلَيْهِمْ رَسُولُ اللَّهِ ﷺ بِيَدِهِ أَنْ أَتِمُّوا صَلاَتَكُمْ] فيجوز أن تخاطب المصلي بالإشارة لأمر لإصلاح صلاته وفعل المشروع فيها وهذا هو الأولى من أن تخاطبه كلاماً، وإن جاز ذلك كما قالت أسماء في حديث الكسوف آية فقالت برأسها أي نعم، فيجوز أن يخاطب بالكلام والأولى أن يخاطب بالإشارة إذا كان المخاطب ليس في الصلاة، أما المصلي فلا يتكلم بل يشير إذا احتاج إلى ذلك.`,
        f: [`(ص165) (أي دون أن يلتفت فنكص على عقبيه ووجهه إلى القبلة.)`] },
      { q: `رفع الصوت بالتكبير للإسماع واقتداء المأموم بصوت المبلّغ، وصحة صلاة المبلّغ والسامع`, p: `166`,
        n: `قولها (وأبو بكر يُسمع الناس التكبير) فيه جواز رفع الصوت بالتكبير ليسمعه الناس ويتبعوه. وأنه يجوز للمقتدي اتباع صوت المكبّر وهذا مذهبنا ومذهب الجمهور، ونقلوا فيه الإجماع وما أراه يصح الإجماع فيه فقد نقل القاضي عياض عن مذهبهم أن منهم من أبطل صلاة المقتدي ومنهم من لم يبطلها، ومنهم من قال إن أذن الإمام في الإسماع صح الاقتداء به وإلا فلا ومنهم من أبطل صلاة المسمع ومنهم من صححها ومنهم من شرط إذن الإمام ومنهم من قال إن تكلف صوتًا بطلت صلاته وصلاة من ارتبط بصلاته، وكل هذا ضعيف والصحيح جواز كل ذلك وصحة صلاة المُسمع والسامع ولا يعتبر إذن الإمام. والله أعلم.`,
        o: `قول بعض المالكية (نقله القاضي عياض): منهم من أبطل صلاة المقتدي، ومنهم من لم يبطلها، ومنهم من شرط إذن الإمام، ومنهم من أبطل صلاة المسمع.`,
        s: `(نقل القاضي عياض عن مذهبهم) أي المالكية، والصحيح أنها لا تبطل بل مشروعة. (طالما وجدت الحاجة، أما إذا لم توجد حاجة فقد أساء المبلغ وصلاته صحيحة لأنه لا دليل على بطلان صلاته، ولا ينبغي الاعتماد على صوته دون صوت الإمام طالما وصل صوت الإمام.)`,
        f: [] },
    ],
  },
  {
    title: `باب تقديم الجماعة من يصلي بهم إذا تأخر الإمام ولم يخافوا مفسدةً بالتقديم (ص166–171)`,
    items: [
      { q: `فوائد حديثي تقديم أبي بكر وعبد الرحمن بن عوف: الإصلاح بين الناس، وتقدم غير الإمام الراتب إذا تأخر، والالتفات والحمد والدعاء والمشي في الصلاة، والتسبيح والتصفيق`, p: `168–169`,
        n: `فيه حديث تقديم أبي بكر ﵁ وحديث تقدم عبد الرحمن بن عوف ﵁. فيه فضل الإصلاح بين الناس ومشي الإمام وغيره في ذلك، وأن الإمام إذا تأخر عن الصلاة تقدم غيره إذا لم يخف فتنة وإنكار من الإمام. وفيه أن المقدم نيابة عن الإمام يكون أفضل القوم وأصلحهم لذلك الأمر وأقومهم به. وفيه أن المؤذن وغيره يعرض التقدم على الفاضل وأن الفاضل يوافقه. وفيه أن الفعل القليل لا يبطل الصلاة لقوله (صفق الناس). وفيه جواز الالتفات في الصلاة للحاجة، واستحباب حمد الله تعالى لمن تجددت له نعمة ورفع اليدين بالدعاء وفعل ذلك الحمد والدعاء عقب النعمة وإن كان في صلاة. وفيه جواز مشي الخطوة والخطوتين في الصلاة. وفيه أن هذا القدر لا يكره إذا كان لحاجة. وفيه جواز استخلاف المصلي بالقوم من يتم الصلاة لهم وهذا هو الصحيح في مذهبنا. وفيه أن التابع إذا أمره المتبوع بشيء وفهم منه إكرامه بذلك الشيء لا تحتم الفعل فله أن يتركه ولا يكون هذا مخالفة للأمر بل يكون أدبًا وتواضعًا وتحذقًا في فهم المقاصد. وفيه ملازمة الأدب مع الكبار. وفيه أن السنة لمن نابه شيء في صلاته كإعلام من يستأذن عليه وتنبيه الإمام وغير ذلك أن يسبح إن كان رجلًا فيقول سبحان الله وأن تصفق وهو التصفيح إن كانت امرأة فتضرب بطن كفها اليمنى على ظهر كفها اليسرى ولا تضرب بطن كف على بطن كف على وجه اللعب واللهو فإن فعلت هكذا على جهة اللعب بطلت صلاتها لمنافاتها الصلاة.`,
        o: NO_O,
        s: `(حمد الله ورفع اليدين بالدعاء:) فلو سمع إنسان بنعمة من عند الله أثناء صلاته فليرفع يديه بالحمد والدعاء لله ﷻ. (مشي الخطوة والخطوتين:) لأن أبو بكر (رَجَعَ الْقَهْقَرَى) ويمكن أن يكون أكثر من خطوتين لعدم وجود نص بأنهم خطوتين اثنتين حتى وقف في الصف، وبين الصف وبين مقام النبي ﷺ ثلاثة أذرع، فهذه ربما احتاجت إلى ثلاث خطوات. (استخلاف المصلي:) وذلك إذا عرض له طارئ، لأن هذا الحديث يتضمن صلاة صلوا جزء منها بإمام وجزء منها بإمام آخر، الجزء الأول مؤتمين بأبي بكر والجزء الثاني مؤتمين برسول الله ﷺ، فهذا دليل على أنه لا تكره صلاة بإمامين لعذر، ومثلها الاستخلاف: فالإمام عرض له طارئ صلوا خلفه ثم انتقض وضوءه مثلاً فقدم من يصلي بهم، كما فعل عمر ﵁ فأقصاها أن يصلوا صلاة بإمامين. ويستدل به على أن من بدأ في الصلاة ثم جاءت جماعة فبدأوا صلاة الجماعة وأنه طالما في نفس الركعات فليدخل معهم ولا يخرج من صلاته بل يأتم بالإمام. (لا تحتم الفعل:) لأن أبي بكر أعتذر عن أن يتقدم بين يدي رسول الله ﷺ وهو أمر محبوب للنبي ﷺ هذا الأدب، وقد فهم أبو بكر من الأمر بقرينة السياق أنه أمر إباحة لا أمر إيجاب ولا حتى استحباب. (على وجه اللعب:) هذا فيما إذا كان على وجه اللعب أما إذا كانت جاهلة أو كانت تظن أن هذا هو التصفيق الجائز صحة صلاتها.`,
        f: [`(ص168) لأنه كان معه بعض الصحابة. (تعليقًا على «مشي الإمام وغيره في الإصلاح».)`, `(ص168) فالمسافة بين مكان الصلاة وبين حجرة النبي ﷺ أو آخر الصف الأول يسيرة، يمكن التفات يسير لا ينحرف به الإنسان عن القبلة.`] },
      { q: `الإقامة: متى تصح؟ ومن الذي يقيم؟ وإقامة غير المؤذن، وجواز خرق الصفوف، والاقتداء بمن أحرم بعده`, p: `170`,
        n: `وفيه أن الإقامة لا تصح إلا عند إرادة الدخول في الصلاة لقوله: (أتصلي فأقيم). وفيه أن المؤذن هو الذي يقيم الصلاة فهذا هو السنة، ولو أقام غيره كان خلاف السنة ولكن يُعتد بإقامته عندنا وعند جمهور العلماء. وفيه جواز خرق الإمام الصفوف ليصل إلى موضعه إذا احتاج إلى خرقها لخروجه لطهارة أو رعاف أو نحوهما ورجوعه وكذا من احتاج إلى الخروج من المأمومين لعذر وكذا له خرقها في الدخول إذا رأى قدّامهم فُرجةً فإنهم مقصّرون بتركها. واستدل به أصحابنا على جواز اقتداء المصلي بمن يحرم بالصلاة بعده فإن الصديق ﵁ أحرم بالصلاة أولًا ثم اقتدى بالنبي ﷺ حين أحرم بعده هذا هو الصحيح في مذهبنا. وقوله (ورجع القهقرى) فيه أن من رجع في صلاته لشيء يكون رجوعه إلى وراء ولا يستدبر القبلة ولا يتحرفها.`,
        o: NO_O,
        s: `(فهذا دليل أن هذا هو السنة، ولكن لو حدث تأخر فأقاموا الصلاة وحدث طارئ فأخروها قليلاً لا يضر والصلاة صحيحة والإقامة صحيحة ولا تُعاد.) (لأن بلال هو الذي جاء إلى أبي بكر.) (هذا فيما إذا كان على وجه اللعب...)`,
        f: [`(ص170) هذا فيما إذا كان على وجه اللعب أما إذا كانت جاهلة أو كانت تظن أن هذا هو التصفيق الجائز صحة صلاتها.`, `(ص170) فهذا دليل أن هذا هو السنة، ولكن لو حدث تأخر فأقاموا الصلاة وحدث طارئ فأخروها قليلاً لا يضر والصلاة صحيحة والإقامة صحيحة ولا تعاد.`, `(ص170) لأن بلال هو الذي جاء إلى أبي بكر ﵁.`] },
      { q: `فوائد حديث عبد الرحمن بن عوف: الاستعانة بصب الماء، الجباب (لبس ما صنعه الكفار)، تأخر الإمام المستخلف عند حضور الإمام الراتب، الصلاة خلف إمام يصلي صلاة غيرها`, p: `170–171`,
        n: `وأما حديث عبد الرحمن بن عوف ﵁ فقد تقدم شرحه في كتاب الطهارة وما فيه: حمل الإداوة مع الرجل الجليل. وجواز الاستعانة بصب الماء في الوضوء، وغسل الكفين في أوله ثلاثًا. وجواز لبس الجباب. وجواز إخراج اليد من أسفل الثوب إذا لم يتبين شيء من العورة. وجواز المسح على الخفين، وغير ذلك مما سبق بيانه في موضعه والله تعالى أعلم.`,
        o: NO_O,
        s: `(الاستعانة:) فيصب أحد عليه الماء فلا يكره ذلك خلافاً لبعض المتأخرين. وهذه الفائدة مأخوذة من أن المغيرة بن شعبة أهراق الماء وصبه على النبي ﷺ ليتوضأ. (الجباب:) وهو جمع (جُبة) وهو ثوب مفتوح من أمام وله كمان وفي هذا الحديث فيه أنه جبة رومية، فيستدل به على جواز لبس الملابس المشتركة بين المسلمين والكفار ولو صُنعت في بلاد الكفار، ولو كان تفصيلها على ما تعود الكفار، وقد سُميت جُبة شامية أو رومية وكلاهما واحد لأن الشام كانت في أيدي الروم، فقد لبس النبي ﷺ الملابس التي صنعت في بلاد الكفار. في هذا الحديث لم يقبل النبي ﷺ بتأخير عبد الرحمن بن عوف لأنه قد قضى ركعة، فدل ذلك على أن المشروع من تأخر الإمام المستخلف إذا حضر الإمام الراتب إنما إذا كان في الركعة الأولى، وأما إذا فاتهم شيء من الصلاة فيقع اختلاف على الإمام، إذا تقدم الإمام الراتب وقد نهى النبي ﷺ عن ذلك، فدل ذلك على عدم مشروعية تأخر الإمام المستخلف إذا كان قد صلى ركعة فما فوقها لأنه سيترتب على ذلك الاختلاف على الإمام. ومن هنا نأخذ عدم مشروعية صلاة خلف إمام يصلي صلاة غيرها يترتب عليها مخالفة الإمام كما هو قول جمهور أهل العلم كمن يصلي المغرب خلف العشاء أو العشاء خلف صلاة الكسوف مثلاً أو غير ذلك مما يترتب عليه مخالفة في الهيئة فإما أن يخالف الإمام وإما أن تفسد صلاته فيزيد فيها أو يُنقص منها، وهذا بخلاف أمر أبي بكر فإنه تراجع لأنه كان في أول ركعة، وأقره النبي ﷺ على ذلك وصلى النبي ﷺ إماماً. وفيه صلاة المسبوق أنه يُتم صلاته بعد صلاة الإمام. وفيه فضيلة الصلاة لوقتها أي في أول وقتها، وشفقة النبي ﷺ على أصحابه إذ هدأ من فزعهم لما رأوه ﷺ وقد صلى مأموماً. وفيه فضيلة عبد الرحمن بن عوف ﵁ إذ صلى إماماً برسول الله ﷺ، فقد صلى النبي ﷺ خلف بعض أمته.`,
        f: [`(ص171) وذلك لأن المغيرة حمل الإناء الذي فيه ماء مع الرسول ﷺ.`, `(ص171) أي في أول الوضوء، لقوله في حديث المغيرة: (وَغَسَلَ يَدَيْهِ ثَلاَثَ مَرَّاتٍ ثُمَّ غَسَلَ وَجْهَهُ).`] },
    ],
  },
  {
    title: `باب تسبيح الرجل وتصفيق المرأة إذا نابهما شيء في الصلاة (ص172–173)`,
    items: [
      { q: `إشارة المأمومين للإمام عند السهو في عدد الركعات، وحكم الكلام لإصلاح الصلاة`, p: `172`,
        n: `(حديث: «التسبيح للرجال والتصفيق للنساء» زاد حرملة في روايته قال ابن شهاب: ورأيت رجالًا من أهل العلم يسبّحون ويشيرون.)`,
        o: `بعض أهل العلم: يجوز الكلام لإصلاح الصلاة إذا لم تُصلح إلا بالكلام؛ ومن الفقهاء من يرى بطلان الصلاة بالكلام ولو لإصلاحها.`,
        s: `فلو أخطأ الإمام في عدد الركعات يمكن للمأمومين أن يشيرون له بأصابعهم (ثلاثة، أربعة) فلو أخطأ فيه دون أن يتكلموا، هذا هو الأصل؛ وإنما أجاز بعض أهل العلم الكلام، إذا لم تُصلح الصلاة إلا بالكلام، وأما إذا أمكن أن تُصلح بغير الكلام لم يجز الكلام عن من قال به فضلاً عن غيرهم ممن يرى بطلان الصلاة بالكلام ولو لإصلاحها، والأظهر أنها لو كانت لإصلاح الصلاة صح ذلك. وأما عن كيفية إدراك الإمام إشارة المأمومين: بالتفاته التفاته يسيرة فيدرك ذلك، أو يكون الإمام سلم والتفت والمأمومين لم يسلموا بعد لأنه قد سلم في غير الموضع كأن سلم في ركعتين (فإنهم لا يقولوا [اثنين]، ولا يقولوا [نحن في الركعة الثانية] ولا [اتينا بركعتين وباقي اثنين]) بل يشيرون له. إذا سلم الإمام من ركعتين لم يسلم المأمومون بل يسبحون له ويشيرون حتى ينتبه فيكبر من جديد ويصلي بهم الركعتين أو ما نقص من صلاته ثم يسجد للسهو على زيادة السلام.`,
        f: [] },
      { q: `التصفيق للرجال خارج الصلاة`, p: `173`,
        n: `قوله ﷺ: (التسبيح للرجال والتصفيق للنساء) تقدم شرحه في الباب قبله.`,
        o: NO_O,
        s: `التصفيق للرجال خارج الصلاة إن كان لتنبيه أو غير ذلك فلم يرد نهي فيها أعلم، وأما إن كان لتشجيع أو غير ذلك فهذا من بدع الكفار فلا يُتشبه بهم.`,
        f: [] },
    ],
  },
  {
    title: `باب الأمر بتحسين الصلاة وإتمامها والخشوع فيها (ص173–175)`,
    items: [
      { q: `رؤية النبي ﷺ من وراء ظهره: هل هي رؤية بالعين حقيقةً؟`, p: `174`,
        n: `قوله ﷺ: (يا فلان ألا تحسن صلاتك ألا ينظر المصلي إذا صلى كيف يصلي فإنما يصلي لنفسه إني والله لأبصر من ورائي كما أبصر من بين يدي) ... (أقيموا الركوع والسجود فوالله إني لأراكم من بعدي إذا ركعتم وسجدتم) قال العلماء معناه: أن الله تعالى خلق له ﷺ إدراكًا في قفاه يُبصر به من ورائه وقد انخرقت العادة له ﷺ بأكثر من هذا وليس يمنع من هذا عقل ولا شرع بل ورد الشرع بظاهره فوجب القول به. قال القاضي: قال أحمد بن حنبل رحمه الله تعالى وجمهور العلماء هذه الرؤية رؤية بالعين حقيقة.`,
        o: `أحمد وجمهور العلماء (على ما نقل القاضي عياض): رؤية بالعين حقيقةً. وقيل: خلق الله له إدراكًا في قفاه.`,
        s: `(وذلك باتساع أفق عين النبي ﷺ حيث يرى بعينه من وراء ظهره ﷺ.)`,
        f: [] },
      { q: `الحلف بالله تعالى من غير ضرورة، وحلف النبي ﷺ لتأكيد الأمور المهمة`, p: `174`,
        n: `وفيه: الأمر بإحسان الصلاة والخشوع وإتمام الركوع والسجود. وجواز الحلف بالله تعالى من غير ضرورة، لكن المستحب تركه إلا لحاجة كتأكيد أمر وتفخيمه والمبالغة في تحقيقه وتمكينه من النفوس، وعلى هذا يُحمل ما جاء في الأحاديث من الحلف.`,
        o: NO_O,
        s: `(لأنه قال: [إِنِّي وَاللَّهِ لأُبْصِرُ مِنْ وَرَائِي]، وقال: [فَوَاللَّهِ مَا يَخْفَى عَلَيَّ رُكُوعُكُمْ]، وقال: [وَالَّذِي نَفْسُ مُحَمَّدٍ بِيَدِهِ] ولم يُطلب منه حلف ﷺ، ولكن حلف ليؤكد الكلام.) فيحلف في الأمور العظيمة المهمة ليؤكدها، ويستحب ترك الحلف في الأمور غير المهمة. (فيكون حلف النبي ﷺ كله لتأكيد الأمور المهمة في النفوس وتقرير حقيقتها، والنهي عن كثرة الحلف في غير المهم كما ذكرنا، وتحريم الحلف الكاذب.)`,
        f: [] },
      { q: `معنى «إني لأراكم من بعدي»`, p: `175`,
        n: `وقوله ﷺ: (إني لأراكم من بعدي) أي: [من ورائي] كما في الروايات الباقية. قال القاضي عياض: وحمله بعضهم على بعد الوفاة وهو بعيد عن سياق الحديث.`,
        o: `بعضهم: المراد بعد الوفاة (بعيد عن سياق الحديث).`,
        s: `(نعم فهو بعيد عن سياق الحديث وعن المعنى وعن نصوص الأدلة في أن النبي ﷺ في الحديث: [فَأَقُولُ يَا رَبِّ أَصْحَابِي فَيُقَالُ لاَ تَدْرِي مَا أَحْدَثُوا بَعْدَكَ] البخاري. فهو ﷺ لا يراهم بعد وفاته لأنه لو كان يراهم بعد وفاته لعلم ما أحدثوه بعده إلا أن يُعلمه الله أو يُريه الله ما شاء ﷺ.)`,
        f: [] },
    ],
  },
  {
    title: `باب النهي عن سبق الإمام بركوع أو سجود ونحوهما (ص175–177)`,
    items: [
      { q: `مسابقة المأموم للإمام في الأفعال: حكمها (تحريم أم كراهة) وهل تبطل الصلاة؟ ومعنى «أن يحول الله رأسه رأس حمار»`, p: `175–177`,
        n: `قوله ﷺ: (لا تسبقوني بالركوع ولا بالسجود ولا بالقيام ولا بالانصراف) فيه تحريم هذه الأمور وما في معناها والمراد بالانصراف السلام. قوله ﷺ: (رأيت الجنة والنار) فيه أنهما مخلوقتان. وقوله ﷺ: (أما يخشى الذي يرفع رأسه قبل الإمام أن يحول الله رأسه رأس حمار) وفي رواية (صورته في صورة حمار) وفي رواية (وجهه وجه حمار) هذا كله بيان لغلظ تحريم ذلك. والله أعلم.`,
        o: `بعض العلماء: تكره المسابقة وتحرم المساواة. وبعضهم: تبطل الصلاة بالمسابقة (مثل تكبيرة الإحرام قبل الإمام).`,
        s: `([ونحوهما]) فيقتضي جميع الحركات، فالسنة في الحركات أن يبدأ المأموم في الحركة بعد أن يتمها الإمام وإذا ساواه فظاهر الأدلة التحريم وأغلظ منه المسابقة، وبعض العلماء يقولون تكره المساواة وتحرم المسابقة، ولكن الظاهر وقوع الفعل بعده ولكن قبل أن يتم الإمام حركته فهو مكروه بمعنى أن الإمام ينزل وهو ينزل بعده ولكن شاركه في جزء من الحركة فيكون مكروهاً، وذلك يُنبه على من يصلي خلف إمام يكبر قبل الحركة لأنه لا يبدأ حركته حتى يفعلها الإمام وليس فقط سماع الصوت، والأولى والسنة للإمام أن يكبر أثناء الحركة ويتم التكبير مع نهايتها أو قريباً منه بحيث من لا يراه من المأمومين ويسمع صوته يستطيع أن يتابعه على السنة من غير اختلال. (إذا نوى المفارقة فسلم قبل الإمام لعذر صحة صلاته، وأما إن كان بلا عذر ففيها القولين ولكن ظاهر الأدلة مثل رفع الرأس قبل الإمام.) (رأيت الجنة والنار:) أي موجودتان الآن، قد خلقتا ووجدتا. (العقاب:) فهذا العقاب إما أن يجعله الله ﷻ في الدنيا ويكون كما وردت في الأحاديث بوجود المسخ في آخر الزمان: [عَنِ النَّبِيِّ ﷺ قَالَ: بَيْنَ يَدَيِ السَّاعَةِ مَسْخٌ، وَخَسْفٌ، وَقَذْفٌ]. سنن ابن ماجة. والله أعلى وأعلم. أو أن يجعله يوم القيامة كذلك فإذا قام يكون وجهه في صورة حمار أو وجهه وجه حمار نعوذ بالله من ذلك، لأن الحمار قليل الفهم، فالذي يرفع رأسه قبل الإمام في صلاة الجماعة قليل الفهم قد خالف الأمر الواجب عليه في متابعة الإمام وسبقه، ولكن هذا الحديث يدل على عدم بطلان الصلاة لأنه يظهر أن ذلك قد وقع من بعضهم بدليل قوله ﷺ: "يَا فُلاَنُ أَلاَ تُحْسِنُ صَلاَتَكَ" فهذا يدل على أنه قد خالف فيها ومع ذلك لم يأمره بالإعادة، ولكن ذكر الوعيد الشديد، دل ذلك على وجود بعض المحرمات في الأفعال في الصلاة لا تبطل بها الصلاة مثل مسابقة الإمام، أما تكبيرة الإحرام فلأنه نوى الاقتداء ولا يصح إلا أن يكون بعد تكبيرة الإحرام ولذلك نقل النووي وغيره الإجماع على بطلان الصلاة من كبر تكبيرة الإحرام قبل الإمام ناوياً الاقتداء به إلا أن يكون هناك سبب مثلما قلنا في الإمام إذا أتى الإمام الراتب وقد كان المستخلف قد صلى والمأمومون قد صلوا فينوون تغيير الاقتداء بالإمام الراتب إذا دخل في الصلاة بعدهم. هذه صورة أخرى غير التي نقل عليها الاتفاق، والصورة التي عليها الاتفاق أن يكونوا واقفين في الصف والإمام لم يقل بعد (الله أكبر) والمأموم يُكبر.`,
        f: [] },
    ],
  },
  {
    title: `باب النهي عن رفع البصر إلى السماء في الصلاة (ص177–178)`,
    items: [
      { q: `رفع البصر إلى السماء في الدعاء: في الصلاة وخارجها`, p: `178`,
        n: `قوله ﷺ: (لينتهين أقوام يرفعون أبصارهم إلى السماء في الصلاة) أو لا ترجع إليهم. وفي رواية: (أو لتخطفن أبصارهم) فيه النهي الأكيد والوعيد الشديد في ذلك وقد نُقل الإجماع في النهي عن ذلك. قال القاضي عياض: واختلفوا في كراهة رفع البصر إلى السماء في الدعاء في غير الصلاة فكرهه شريح وآخرون وجوزه الأكثرون وقالوا لأن السماء قبلة الدعاء كما أن الكعبة قبلة الصلاة ولا يُنكر رفع الأبصار إليها كما لا يُكره رفع اليد قال الله تعالى: [وفي السماء رزقكم وما توعدون].`,
        o: `شريح وآخرون: يكره رفع البصر إلى السماء في الدعاء خارج الصلاة. الأكثرون: يجوز.`,
        s: `وهذا لم يثبت عن النبي ﷺ من رفع البصر للدعاء خارج الصلاة ونقل الإجماع عن النهي عن ذلك وظاهر هذا تحريم رفع البصر إلى السماء لأنه لا عقوبة إلا على فعل محرم.`,
        f: [] },
    ],
  },
  {
    title: `باب الأمر بالسكون في الصلاة والنهي عن الإشارة باليد ورفعها عند السلام وإتمام الصفوف الأول والتراص فيها والأمر بالاجتماع (ص178–182)`,
    items: [
      { q: `السكون في الصلاة والنهي عن رفع الأيدي عند السلام: المراد بالرفع، وما يُستفاد منه عمومًا`, p: `180`,
        n: `قوله ﷺ: (مالي أراكم رافعي أيديكم كأنها أذناب خيل شمس) هو بإسكان الميم وضمها، وهي التي لا تستقر بل تضطرب وتتحرك بأذنابها وأرجلها، والمراد بالرفع المنهي عنه هنا رفعهم أيديهم عند السلام مشيرين إلى السلام من الجانبين كما صرح به في الرواية الثانية.`,
        o: NO_O,
        s: `وهذا يستفاد منه عموماً أن السكون في الصلاة أعم من ذلك، فعلى المصلي ألا يحرك أعضاءه في الصلاة إلا لحاجة لا كما نرى فيحرك يده يميناً ويساراً ويلتفت، فهذا ينافي الخشوع (اسْكُنُوا فِي الصَّلاَةِ) وإن كان الموضع الذي حركوا فيه أثناء السلام كما يفعل كثير من الناس فتجد أيديهم تتحرك مع السلام جهة الإشارة بالرأس.`,
        f: [] },
      { q: `الحلق في المسجد (الجلوس حلقًا حلقًا)، ومعنى «ما لي أراكم عزين»`, p: `180`,
        n: `قوله (فرآنا حلقًا) هو بكسر الحاء وفتحها لغتان جمع حلقة بإسكان اللام. قوله ﷺ: (ما لي أراكم عزين) أي متفرقين جماعة جماعة وهو بتخفيف الزاي الواحدة عزة معناه النهي عن التفرق والأمر بالاجتماع.`,
        o: NO_O,
        s: `فلا يوجد حلق (شِلل) في المسجد – جماعات متفرقة – بل يجتمعون وهذا أنفع لهم في مجالس علمهم وفي طعامهم وشرابهم ولكن في الطعام والشراب يجوز أن يكونوا جماعات ومتفرقين لقوله تعالى: (لَيْسَ عَلَيْكُمْ جُنَاحٌ أَن تَأْكُلُوا جَمِيعًا أَوْ أَشْتَاتًا) ولكن لعل هنا في الحديث على وجود بعض الكلام وفي الدرس.`,
        f: [] },
      { q: `إتمام الصفوف الأول والتراص فيها، وصفوف الصبيان والنساء`, p: `180`,
        n: `وفيه الأمر بإتمام الصفوف الأول والتراص في الصفوف، ومعنى إتمام الصفوف الأول أن يتم الأول ولا يشرع في الثاني حتى يتم الأول ولا في الثالث حتى يتم الثاني ولا في الرابع حتى يتم الثالث وهكذا إلى آخرها.`,
        o: NO_O,
        s: `فلا يُبدأ صف إلا بعد إتمام الصف الذي يسبقه، ومن هنا يقف الصبيان المميزين في الصف الأخير يُتم بهم الصف، ولا يبدأ صف صبيان مستقلاً عن صفوف الرجال الأخيرة حتى يُتم صف الرجال أولاً، وأما النساء فيبدأ صف مستقل لحديث أنس: [فَقَامَ عَلَيْهِ رَسُولُ اللَّهِ ﷺ وَصَفَفْتُ أَنَا وَالْيَتِيمُ وَرَاءَهُ وَالْعَجُوزُ مِنْ وَرَائِنَا فَصَلَّى لَنَا رَسُولُ اللَّهِ ﷺ رَكْعَتَيْنِ ثُمَّ انْصَرَفَ.] مسلم. (والتراص بمعنى عدم وجود فُرج.)`,
        f: [] },
      { q: `صيغة السلام من الصلاة: زيادة «وبركاته»، وتسليمة اليمين واليسار، وهل هي بدعة؟`, p: `181`,
        n: `وفيه أن السنة في السلام من الصلاة أن يقول: [السلام عليكم ورحمة الله] عن يمينه [السلام عليكم ورحمة الله] عن شماله، ولا يُسن زيادة [وبركاته] وإن كان قد جاء فيها حديث ضعيف وأشار إليها بعض العلماء ولكنها بدعة إذ لم يصح فيها حديث بل صح هذا الحديث وغيره في تركها.`,
        o: NO_O,
        s: `هذا الكلام غير صحيح، نعم قد وردت أحاديث ضعيفة في ذلك ولكن قد وردت طرق أخرى صحيحة وإن كان الأكثر والأعم الاقتصار على ذكر الرحمة ولكن قد ثبتت زيادة [وبركاته] في بعض الروايات، فتحمل على الزيادة في بعض الأحيان وثبتت في اليمين دون الشمال وثبتت عن اليمين والشمال، فالصحيح أن هذه الأفعال يخير بينها لعدم تعارض الأفعال، وإن كان الأغلب الأعم القول [السَّلاَمُ عَلَيْكُمْ وَرَحْمَةُ اللَّهِ، السَّلاَمُ عَلَيْكُمْ وَرَحْمَةُ اللَّهِ] ويفعل أحياناً أن يقول [السَّلاَمُ عَلَيْكُمْ وَرَحْمَةُ اللَّهِ وَبَرَكَاتُهُ، السَّلاَمُ عَلَيْكُمْ وَرَحْمَةُ اللَّهِ] وأحياناً أخرى أقل: [السَّلاَمُ عَلَيْكُمْ وَرَحْمَةُ اللَّهِ وَبَرَكَاتُهُ، السَّلاَمُ عَلَيْكُمْ وَرَحْمَةُ اللَّهِ وَبَرَكَاتُهُ] فقد صحح ابن حجر حديث (وبركاته) وصححه الشيخ الألباني أيضاً.`,
        f: [`(ص181) وصححه الألباني في [صحيح وضعيف أبي داود]: حَدَّثَنَا عَبْدَةُ بْنُ عَبْدِ اللَّهِ، حَدَّثَنَا يَحْيَى بْنُ آدَمَ، حَدَّثَنَا مُوسَى بْنُ قَيْسٍ الْحَضْرَمِيُّ، عَنْ سَلَمَةَ بْنِ كُهَيْلٍ، عَنْ عَلْقَمَةَ بْنِ وَائِلٍ، عَنْ أَبِيهِ، قَالَ: صَلَّيْتُ مَعَ النَّبِيِّ ﷺ فَكَانَ يُسَلِّمُ عَنْ يَمِينِهِ: السَّلاَمُ عَلَيْكُمْ وَرَحْمَةُ اللَّهِ وَبَرَكَاتُهُ، وَعَنْ شِمَالِهِ: السَّلاَمُ عَلَيْكُمْ وَرَحْمَةُ اللَّهِ. تحقيق الألباني: صحيح. وحديث ابن مسعود: «كَانَ يُسَلِّمُ عَنْ يَمِينِهِ وَعَنْ شِمَالِهِ حَتَّى يُرَى بَيَاضُ خَدِّهِ: السَّلاَمُ عَلَيْكُمْ وَرَحْمَةُ اللَّهِ وَبَرَكَاتُهُ». (وبعد ذلك حاشية تحقيق منقولة عن محققي الكتاب المنقول عنه، وليست من كلام الشيخ.)`] },
      { q: `الواجب من السلام: «السلام عليكم» مرة واحدة، واستحباب التسليمتين`, p: `182`,
        n: `والواجب منه السلام عليكم مرة واحدة، ولو قال السلام عليك بغير ميم لم تصح صلاته. وفيه دليل على استحباب تسليمتين، وهذا مذهبنا ومذهب الجمهور. وقوله ﷺ: (ثم يسلم على أخيه من على يمينه وشماله) المراد بالأخ الجنس أي إخوانه الحاضرين عن اليمين والشمال. وفيه الأمر بالسكون في الصلاة والخشوع فيها والإقبال عليها وأن الملائكة يصلون وأن صفوفهم على هذه الصفة والله أعلم.`,
        o: NO_O,
        s: `(الحديث: عائشة أن رسول الله ﷺ [كان يسلم تسليمة واحدة تلقاء وجهه]. قال الشيخ الألباني: صحيح. سنن ابن ماجة. فيُجزئ تسليمة واحدة.) (قلنا قبل ذلك أن الراجح أن السلام واجب وليس بركن. والله أعلم. ولا تبطل الصلاة بالسلام عليك فقط.)`,
        f: [] },
    ],
  },
  {
    title: `باب تسوية الصفوف وإقامتها وفضل الأول فالأول منها والازدحام على الصف الأول والمسابقة إليها وتقديم أولي الفضل وتقريبهم من الإمام (ص182–190)`,
    items: [
      { q: `ترتيب الصفوف عند ازدحام الصف الأول وسبب حرص الصحابة عليه (القرعة)، وبناء الصف الأول فالأول`, p: `184`,
        n: `(حديث: «لو يعلم الناس ما في النداء والصف الأول ثم لم يجدوا إلا أن يستهموا عليه لاستهموا...»؛ «لو تعلمون ما في الصف المقدم لكانت قرعة».) [استهم: اقترع عليه].`,
        o: NO_O,
        s: `(فينبغي أن يُبدأ الصف فيكمل الأول فالأول، فلا يُبدأ صف مؤخر بعيداً عن الإمام كما يفعل كثير من الناس فيضعون صف من الكراسي فيضعون صف من الكراسي بالخلف ويقفوا بالخلف.)`,
        f: [] },
    ],
  },
];
